INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('857f534a-8077-4932-b335-c845b7c2fa47', '東亭柳', '东亭柳', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["拂水斜煙一萬條，幾隨春色倚河橋。","不知別後誰攀折，猶自風流勝舞腰。"]', '["拂水斜煙一万條，幾隨春色倚河橋。","不知別後誰攀折，猶自风流勝舞腰。"]', '诗', 'shi', '', NULL, '東亭柳 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb969fae-a944-4186-b1ff-fff7ada5dd90', '僧舍二首 一', '僧舍二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["秖言雙鬢未蹉跎，獨奈牛羊送日何。","禪客不歸車馬去，晚簷山色爲誰多。"]', '["秖言雙鬢未蹉跎，独奈牛羊送日何。","禪客不归车马去，晚簷山色爲誰多。"]', '诗', 'shi', '', NULL, '僧舍二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0660d11e-db79-4fd7-9a3d-9210857877d4', '僧舍二首 二', '僧舍二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪上禪關水木間，水南山色與僧閑。","春風盡日無來客，幽磬一聲高鳥還。"]', '["溪上禪关水木间，水南山色與僧闲。","春风尽日無来客，幽磬一声高鸟還。"]', '诗', 'shi', '', NULL, '僧舍二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a2351d-06b8-4425-956b-6e6a32570c13', '新月', '新月', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["玉鉤斜傍畫簷生，雲匣初開一寸明。","何事最能悲少婦，夜來依約落邊城。"]', '["玉鉤斜傍畫簷生，云匣初开一寸明。","何事最能悲少婦，夜来依約落邊城。"]', '诗', 'shi', '', NULL, '新月 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52f23e0-29a9-4dab-9359-a0a0597c4853', '贈皇甫垣', '贈皇甫垣', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["養由弓箭已無功，牢落生涯事事同。","相勸一杯寒食酒，幾多辛苦到春風。"]', '["養由弓箭已無功，牢落生涯事事同。","相勸一杯寒食酒，幾多辛苦到春风。"]', '诗', 'shi', '', NULL, '贈皇甫垣 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7672fee3-837f-4485-bf36-8d4bc85b7ae1', '四祖寺', '四祖寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["千株松下雙峰寺，一盞燈前萬里身。","自爲心猿不調伏，祖師元是世間人。"]', '["千株松下雙峰寺，一盞灯前万里身。","自爲心猿不調伏，祖師元是世间人。"]', '诗', 'shi', '', NULL, '四祖寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd0fe66f-7b88-4249-8fb1-9bd892496e53', '聽蟬', '听蟬', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["噪蟬聲亂日初曛，絃管樓中永不聞。","獨奈愁人數莖髮，故園秋隔五湖雲。"]', '["噪蟬声亂日初曛，絃管楼中永不闻。","独奈愁人數莖髮，故园秋隔五湖云。"]', '诗', 'shi', '', NULL, '聽蟬 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06be1d4-e9d9-4e50-9447-adc4118c8b68', '寄遠', '寄远', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["禁鐘聲盡見棲禽，關塞迢迢故國心。","無限春愁莫相問，落花流水洞房深。"]', '["禁鐘声尽见棲禽，关塞迢迢故国心。","無限春愁莫相问，落花流水洞房深。"]', '诗', 'shi', '', NULL, '寄遠 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1def6971-c540-4e99-b642-7351749cabde', '池上', '池上', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["正憐佳月夜深坐，池上暖回燕雁聲。","猶有漁舟繫江岸，故人歸盡獨何情。"]', '["正怜佳月夜深坐，池上暖回燕雁声。","猶有漁舟繫江岸，故人归尽独何情。"]', '诗', 'shi', '', NULL, '池上 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c25ad5-91a1-49fe-95e2-4dc5c14eb09c', '春日書懷', '春日书懷', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["暖鶯春日舌難窮，枕上愁生曉聽中。","應褭綠窗殘夢斷，杏園零落滿枝風。"]', '["暖鶯春日舌难窮，枕上愁生晓听中。","應褭綠窗殘梦斷，杏园零落满枝风。"]', '诗', 'shi', '', NULL, '春日書懷 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba29023a-ed78-449a-9de5-2b05cdcbe5bc', '贈別', '贈別', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["水邊秋草暮萋萋，欲駐殘陽恨馬蹄。","曾是管絃同醉伴，一聲歌盡各東西。"]', '["水邊秋草暮萋萋，欲駐殘陽恨马蹄。","曾是管絃同醉伴，一声歌尽各东西。"]', '诗', 'shi', '', NULL, '贈別 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b12ed6-731e-4b61-af99-604abbc9fd04', '靈巖寺', '靈巖寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["館娃宮伴千年寺，水闊雲多客到稀。","聞說春來更惆悵，百花深處一僧歸。"]', '["館娃宮伴千年寺，水闊云多客到稀。","闻说春来更惆悵，百花深处一僧归。"]', '诗', 'shi', '', NULL, '靈巖寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f971b5-1bcc-488a-90c4-6abde891ee7f', '代人聽琴二首 一', '代人听琴二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["抱琴花夜不勝春，獨奏相思淚滿巾。","第五指中心最恨，數聲嗚咽爲何人。"]', '["抱琴花夜不勝春，独奏相思泪满巾。","第五指中心最恨，數声嗚咽爲何人。"]', '诗', 'shi', '', NULL, '代人聽琴二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6733b73-bd2e-415e-b77c-526b05a24ded', '代人聽琴二首 二', '代人听琴二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["湘娥不葬九疑雲，楚水連天坐憶君。","惟有啼烏舊名在，忍敎嗚咽夜長聞。"]', '["湘娥不葬九疑云，楚水連天坐憶君。","惟有啼烏旧名在，忍敎嗚咽夜长闻。"]', '诗', 'shi', '', NULL, '代人聽琴二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3438e4-946a-47f7-8457-9a80f0e4c3b8', '訪沈舍人不遇', '訪沈舍人不遇', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪翁強訪紫微郎，曉鼓聲中滿鬢霜。","知在禁闈人不見，好風飄下九天香。"]', '["溪翁強訪紫微郎，晓鼓声中满鬢霜。","知在禁闈人不见，好风飄下九天香。"]', '诗', 'shi', '', NULL, '訪沈舍人不遇 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990164b1-47e8-432f-b7cf-d976f92c4952', '座上獻元相公', '座上獻元相公', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["寂寞堂前日又曛，陽臺去作不歸雲。","從來聞說沙[吒]利，今日青娥屬使君。"]', '["寂寞堂前日又曛，陽台去作不归云。","從来闻说沙[吒]利，今日青娥屬使君。"]', '诗', 'shi', '', NULL, '座上獻元相公 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397819cc-e9a2-4f8c-849c-d4ddd546c505', '遣興二首 一', '遣兴二首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["溪花入夏漸稀疎，雨氣如秋麥熟初。","終日苦吟人不會，海邊兄弟久無書。"]', '["溪花入夏漸稀疎，雨氣如秋麦熟初。","終日苦吟人不會，海邊兄弟久無书。"]', '诗', 'shi', '', NULL, '遣興二首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b8ddf58-7516-430c-b341-91a949972d97', '遣興二首 二', '遣兴二首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["讀徹殘書弄水回，暮天何處笛聲哀？花前獨立無人會，依舊去年雙燕來。"]', '["读徹殘书弄水回，暮天何处笛声哀？花前独立無人會，依旧去年雙燕来。"]', '诗', 'shi', '', NULL, '遣興二首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e01365-143a-428f-baf7-905a2e6e3180', '送李給事', '送李給事', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["眼前軒冕是鴻毛，天上人間漫自勞。","脫却朝衣獨歸去，青雲不及白雲高。"]', '["眼前軒冕是鴻毛，天上人间漫自勞。","脫却朝衣独归去，青云不及白云高。"]', '诗', 'shi', '', NULL, '送李給事 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebc6009-94a1-4c43-ba9e-654d3b6a5608', '宿僧舍', '宿僧舍', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["高僧夜滴芙蓉漏，遠客窗含楊柳風。","何處相逢話心地，月明身在磬聲中。"]', '["高僧夜滴芙蓉漏，远客窗含楊柳风。","何处相逢話心地，月明身在磬声中。"]', '诗', 'shi', '', NULL, '宿僧舍 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a16c1aea-ad3c-48c1-9136-d9efa03f4225', '吳門夢故山', '吳门梦故山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["心熟家山夢不迷，孤峰寒遶一條溪。","秋窗覺後情無限，月墮館娃宮樹西。"]', '["心熟家山梦不迷，孤峰寒遶一條溪。","秋窗覺後情無限，月墮館娃宮樹西。"]', '诗', 'shi', '', NULL, '吳門夢故山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c949afb6-9040-48f8-8007-facc32e766d1', '別李譜', '別李譜', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["尊前路映暮塵紅，池上琴橫醉席風。","今日別君如別鶴，聲容長在楚絃中。"]', '["尊前路映暮塵紅，池上琴橫醉席风。","今日別君如別鹤，声容长在楚絃中。"]', '诗', 'shi', '', NULL, '別李譜 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd2bcf2-6a2b-4c85-b5ce-7f53dffc9e11', '和杜侍郎題禪智寺南樓', '和杜侍郎題禪智寺南楼', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["樓畔花枝拂檻紅，露天香動滿簾風。","誰知野寺遺鈿處，盡在相如春思中。"]', '["楼畔花枝拂檻紅，露天香动满簾风。","誰知野寺遺鈿处，尽在相如春思中。"]', '诗', 'shi', '', NULL, '和杜侍郎題禪智寺南樓 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fedea37c-9971-4004-9bd8-b0ef4c5804a1', '發青山', '發青山', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["鳧鷖聲暖野塘春，鞍馬嘶風驛路塵。","一宿青山又前去，古來難得是閑人。"]', '["鳧鷖声暖野塘春，鞍马嘶风驛路塵。","一宿青山又前去，古来难得是闲人。"]', '诗', 'shi', '', NULL, '發青山 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d995b3-6a67-4e5d-8fa4-a84d64e89b18', '入藍關', '入藍关', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["微煙已辨秦中樹，遠夢更依江上臺。","看落晚花還悵望，鯉魚時節入關來。"]', '["微煙已辨秦中樹，远梦更依江上台。","看落晚花還悵望，鯉鱼时節入关来。"]', '诗', 'shi', '', NULL, '入藍關 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1954529d-bba3-4792-b937-57a7e5924785', '落第寄沈詢', '落第寄沈詢', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["穿楊力盡獨無功，華髮相期一夜中。","別到江頭舊吟處，爲將雙淚問春風。"]', '["穿楊力尽独無功，华髮相期一夜中。","別到江头旧吟处，爲將雙泪问春风。"]', '诗', 'shi', '', NULL, '落第寄沈詢 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be9bf0f-d5e9-4ca5-9b16-14505c9fd885', '送韋中丞', '送韋中丞', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["二年恩意是春輝，清淨胸襟似者希。","泣盡楚人多少淚，滿船唯載酒西歸。"]', '["二年恩意是春輝，清淨胸襟似者希。","泣尽楚人多少泪，满船唯載酒西归。"]', '诗', 'shi', '', NULL, '送韋中丞 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51c1702-9c66-4b9d-9863-f6c12ca79921', '詠端正春樹', '詠端正春樹', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["一樹繁陰先著名，異花奇葉儼天成。","馬嵬此去無多地，祗合楊妃墓上生。"]', '["一樹繁陰先著名，異花奇葉儼天成。","马嵬此去無多地，祗合楊妃墓上生。"]', '诗', 'shi', '', NULL, '詠端正春樹 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96ce99c3-5898-4e39-9a70-07345817dd88', '敘事獻同州侍御三首 一', '敘事獻同州侍御三首 一', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["青雲席中羅襪塵，白首江上吟詩人。","登龍不及三千士，虛度膺門二十春。"]', '["青云席中羅襪塵，白首江上吟诗人。","登龙不及三千士，虛度膺门二十春。"]', '诗', 'shi', '', NULL, '敘事獻同州侍御三首 一 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b2b5f8-01d0-4af1-ac31-d5263defb7c9', '敘事獻同州侍御三首 二', '敘事獻同州侍御三首 二', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["平生望斷雲層層，紫府杳是他人登。","却應歸訪溪邊寺，說向當時同社僧。"]', '["平生望斷云層層，紫府杳是他人登。","却應归訪溪邊寺，说向當时同社僧。"]', '诗', 'shi', '', NULL, '敘事獻同州侍御三首 二 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40b81b5-e9ce-4dff-aedd-2d04c5527a00', '敘事獻同州侍御三首 三', '敘事獻同州侍御三首 三', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["尊前誰伴謝公遊，蓮岳晴來翠滿樓。","坐見一方金變化，獨吟紅藥對殘秋。"]', '["尊前誰伴謝公游，蓮岳晴来翠满楼。","坐见一方金变化，独吟紅藥对殘秋。"]', '诗', 'shi', '', NULL, '敘事獻同州侍御三首 三 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a5843a-5c93-42cc-ac96-02a6e96e00e1', '婺州宴上留別', '婺州宴上留別', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雙溪樓影向雲橫，歌舞高臺晚更清。","獨自下樓騎瘦馬，搖鞭重入亂蟬聲。"]', '["雙溪楼影向云橫，歌舞高台晚更清。","独自下楼騎瘦马，搖鞭重入亂蟬声。"]', '诗', 'shi', '', NULL, '婺州宴上留別 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bccb9f1-cffe-4671-a612-df0aa404ac82', '別牛郎中門館', '別牛郎中门館', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["整襟收淚別朱門，自料難酬顧念恩。","招得片魂騎匹馬，西風斜日入秋原。"]', '["整襟收泪別朱门，自料难酬顧念恩。","招得片魂騎匹马，西风斜日入秋原。"]', '诗', 'shi', '', NULL, '別牛郎中門館 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff8447f-af54-4d5f-992d-0f49c2dfaecc', '山中寄盧簡求', '山中寄盧簡求', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["竹西池上有花開，日日幽吟看又回。","心憶郡中蕭記室，何時暫别醉鄉来。"]', '["竹西池上有花开，日日幽吟看又回。","心憶郡中蕭記室，何时暫别醉乡来。"]', '诗', 'shi', '', NULL, '山中寄盧簡求 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9938b88-61aa-465d-a53d-9160cb9033f7', '寄梁佾兄弟', '寄梁佾兄弟', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["桃李春多翠影重，竹樓當月夜無風。","荀家兄弟來還去，獨倚欄干花露中。"]', '["桃李春多翠影重，竹楼當月夜無风。","荀家兄弟来還去，独倚欄干花露中。"]', '诗', 'shi', '', NULL, '寄梁佾兄弟 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bf0399-b363-44e5-9114-37f2db253467', '同州南亭陪劉侍郎送劉先輩', '同州南亭陪劉侍郎送劉先輩', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["處處雲隨晚望開，洞庭秋水管絃來。","謝公待醉消離恨，莫惜臨川酒一杯。"]', '["处处云隨晚望开，洞庭秋水管絃来。","謝公待醉消離恨，莫惜臨川酒一杯。"]', '诗', 'shi', '', NULL, '同州南亭陪劉侍郎送劉先輩 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e8cb1e3-f087-47ba-ba7c-ec284211e11d', '贈館驛劉巡官', '贈館驛劉巡官', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["雲別青山馬踏塵，負才難覓作閑人。","莫言館驛無公事，詩酒能消一半春。"]', '["云別青山马踏塵，負才难覓作闲人。","莫言館驛無公事，诗酒能消一半春。"]', '诗', 'shi', '', NULL, '贈館驛劉巡官 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cc0800-96a4-419e-9296-83078924dfdb', '贈解頭賈嵩', '贈解头賈嵩', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["賈生名跡忽無倫，十月長安看盡春。","顧我先鳴還自笑，空沾一第是何人。"]', '["賈生名跡忽無倫，十月长安看尽春。","顧我先鳴還自笑，空沾一第是何人。"]', '诗', 'shi', '', NULL, '贈解頭賈嵩 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af8d6c8-ded8-44d3-a3d9-c1f17bd23f34', '題僧壁', '題僧壁', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["曉望疎林露滿巾，碧山秋寺屬閑人。","溪頭盡日看紅葉，却笑高僧衣有塵。"]', '["晓望疎林露满巾，碧山秋寺屬闲人。","溪头尽日看紅葉，却笑高僧衣有塵。"]', '诗', 'shi', '', NULL, '題僧壁 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30250ce2-508e-4bdb-b920-066f764d472c', '沙溪館', '沙溪館', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["翠濕衣襟山滿樓，竹間溪水遶牀流。","行人莫羨郵亭吏，生向此中今白頭。"]', '["翠濕衣襟山满楼，竹间溪水遶牀流。","行人莫羨郵亭吏，生向此中今白头。"]', '诗', 'shi', '', NULL, '沙溪館 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153d4060-dfc3-4656-abad-0a84df6adc85', '李侍御歸炭谷山居同宿華嚴寺', '李侍御归炭谷山居同宿华嚴寺', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["家在青山近玉京，白雲紅樹滿歸程。","相逢一宿最高寺，半夜翠微泉落聲。"]', '["家在青山近玉京，白云紅樹满归程。","相逢一宿最高寺，半夜翠微泉落声。"]', '诗', 'shi', '', NULL, '李侍御歸炭谷山居同宿華嚴寺 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6266414-0f25-4679-b5d6-d620701d9c5b', '過噴玉泉', '過噴玉泉', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["平生半爲山淹留，馬上欲去還回頭。","兩京塵路一雙鬢，不見玉泉千萬秋。"]', '["平生半爲山淹留，马上欲去還回头。","兩京塵路一雙鬢，不见玉泉千万秋。"]', '诗', 'shi', '', NULL, '過噴玉泉 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09746fa-a6d8-42a1-a0e6-b803d7d90ed4', '漢陰庭樹', '漢陰庭樹', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["掘溝引水澆蔬圃，插竹爲籬護藥苗。","楊柳如絲風易亂，梅花似雪日難消。"]', '["掘溝引水澆蔬圃，插竹爲籬護藥苗。","楊柳如絲风易亂，梅花似雪日难消。"]', '诗', 'shi', '', NULL, '漢陰庭樹 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2cf855a-cd7f-426b-97c8-c4df04325628', '送王龜拾遺謝官後歸滻水山居', '送王龟拾遺謝官後归滻水山居', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["水邊殘雪照亭臺，臺上風襟向雪開。","還似當時姓丁鶴，羽毛成後一歸來。"]', '["水邊殘雪照亭台，台上风襟向雪开。","還似當时姓丁鹤，羽毛成後一归来。"]', '诗', 'shi', '', NULL, '送王龜拾遺謝官後歸滻水山居 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec48c8d1-d8ac-488f-b5b6-dc702d74a9cd', '宿長水主人', '宿长水主人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["白雲溪北叢巖東，樹石夜與潺湲通。","行人一宿翠微月，二十五絃聲滿風。"]', '["白云溪北叢巖东，樹石夜與潺湲通。","行人一宿翠微月，二十五絃声满风。"]', '诗', 'shi', '', NULL, '宿長水主人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5914d2a-193a-4c4d-915a-079a6c2bbccd', '寒食離白沙', '寒食離白沙', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["莫驚客路已經年，尚有青春一半妍。","試上方垣望春野，萬條楊柳拂青天。"]', '["莫驚客路已經年，尚有青春一半妍。","試上方垣望春野，万條楊柳拂青天。"]', '诗', 'shi', '', NULL, '寒食離白沙 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e694bc-0a6a-4b8c-8d0a-c1c723a78000', '將發循州社日于所居館宴送', '將發循州社日于所居館宴送', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["浪花如雪疊江風，社過高秋萬恨中。","明日便隨江燕去，依依俱是故巢空。"]', '["浪花如雪叠江风，社過高秋万恨中。","明日便隨江燕去，依依俱是故巢空。"]', '诗', 'shi', '', NULL, '將發循州社日于所居館宴送 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aae63bc-43db-4428-865c-61655fa0d5e6', '句', '句', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["浮雲悲晚翠，落日泣秋風。","語風雙燕立，褭樹百勞飛。","松島鶴歸書信絕，橘洲風起夢魂香。","徒知六國隨斤斧，莫有羣儒定是非。","一千里色中秋月，十萬軍聲半夜潮。","梁王舊館已秋色，珠履少年輕繡衣。"]', '["浮云悲晚翠，落日泣秋风。","語风雙燕立，褭樹百勞飞。","松島鹤归书信絕，橘洲风起梦魂香。","徒知六国隨斤斧，莫有羣儒定是非。","一千里色中秋月，十万軍声半夜潮。","梁王旧館已秋色，珠履少年轻繡衣。"]', '诗', 'shi', '', NULL, '句 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb1cb4d4-b158-4534-ba22-3b8198b0d8b6', '漢堤詩', '漢堤诗', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["陰沴姦陽，來暴於襄。","洎入大郛，波端若鋩。","觸厚摧高，不知其防。","駭潰顛委，萬室皆毀。","竈登蛟鼉，堂集鱣鮪。","惟恩若讎，母不能子。","洪潰既涸，閈閎其虛。","以隳我堵，以剝我廬。","酸傷顧望，若踐丘墟。","帝曰念嗟，朕日南顧。","流災降慝，天曷台怒。","滔滔襄郊，捽我嬰孺。","於惟餘甿，飢傷喘呼。","斯爲淫痍，孰往膏傅。","惟汝元寮，僉舉明哲。","我公用諧，苴茅杖節。","來視襄人，噢咻提挈。","不日不月，咍乎抃悅。","乃泳故隄，陷於沙泥。","缺落坳圯，由東訖西。","公曰嗚呼，漢之有隄。","實命襄人，不力乃力，則及乃身。","具鍤與畚，漢隄其新。","帝廩有粟，帝府有緡。","爾成爾隄，必錫爾勤。","襄人怡怡，聽命襄滸。","背襄肩杵，奔走蹈舞。","分之卒伍，令以麾鼓。","尋尺既度，日月可數。","登登嶪嶪，周旋上下。","披峴斲楚，飛石輓土。","舉築殷雷，駭汗霏雨。","疲癃鰥獨，奮有筋膂。","呀吁來助，提筐負筥。","不勞其勞，雜沓笑語。","咸曰盧公，來賜我生。","斯隄既成，蜿蜿而平。","確爾山固，屹如雲橫。","漢流雖狂，堅不可蝕。","代千年億，與天無極。","惟公之隄，昔在人心。","既築既城，橫之於南。","萌渚不峻，此門不深。","今復在茲，於漢之陰。","斯堤已崇，茲民獲祐。","齯童相慶，室以完富。","貽於襄人，願保厥壽。","繄公之功，赫焉如晝。","捍此巨災，崒若京阜。","天子賜之，百姓載之。","族孫作詩，昭示厥後。"]', '["陰沴姦陽，来暴於襄。","洎入大郛，波端若鋩。","觸厚摧高，不知其防。","駭潰顛委，万室皆毀。","竈登蛟鼉，堂集鱣鮪。","惟恩若讎，母不能子。","洪潰既涸，閈閎其虛。","以隳我堵，以剝我廬。","酸傷顧望，若踐丘墟。","帝曰念嗟，朕日南顧。","流災降慝，天曷台怒。","滔滔襄郊，捽我嬰孺。","於惟餘甿，飢傷喘呼。","斯爲淫痍，孰往膏傅。","惟汝元寮，僉舉明哲。","我公用諧，苴茅杖節。","来視襄人，噢咻提挈。","不日不月，咍乎抃悅。","乃泳故隄，陷於沙泥。","缺落坳圯，由东訖西。","公曰嗚呼，漢之有隄。","實命襄人，不力乃力，則及乃身。","具鍤與畚，漢隄其新。","帝廩有粟，帝府有緡。","爾成爾隄，必錫爾勤。","襄人怡怡，听命襄滸。","背襄肩杵，奔走蹈舞。","分之卒伍，令以麾鼓。","尋尺既度，日月可數。","登登嶪嶪，周旋上下。","披峴斲楚，飞石輓土。","舉築殷雷，駭汗霏雨。","疲癃鰥独，奮有筋膂。","呀吁来助，提筐負筥。","不勞其勞，杂沓笑語。","咸曰盧公，来賜我生。","斯隄既成，蜿蜿而平。","確爾山固，屹如云橫。","漢流雖狂，堅不可蝕。","代千年億，與天無極。","惟公之隄，昔在人心。","既築既城，橫之於南。","萌渚不峻，此门不深。","今复在茲，於漢之陰。","斯堤已崇，茲民獲祐。","齯童相慶，室以完富。","貽於襄人，願保厥壽。","繄公之功，赫焉如晝。","捍此巨災，崒若京阜。","天子賜之，百姓載之。","族孫作诗，昭示厥後。"]', '诗', 'shi', '', NULL, '漢堤詩 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce218e95-f182-49c9-b256-402c0ea4a0ba', '題甘露寺', '題甘露寺', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["北固巖端寺，佳名自上台。","地從京口斷，山到海門迴。","曙色煙中滅，潮聲日下來。","一隅通雉堞，千仞聳樓臺。","林暗疑降虎，江空想度杯。","福庭增氣象，仙磬落昭回。","覺路花非染，流年景謾催。","隋宮凋綠草，晉室散黃埃。","西蜀波湍盡，東溟日月開。","如登最高處，應得見蓬萊。"]', '["北固巖端寺，佳名自上台。","地從京口斷，山到海门迴。","曙色煙中滅，潮声日下来。","一隅通雉堞，千仞聳楼台。","林暗疑降虎，江空想度杯。","福庭增氣象，仙磬落昭回。","覺路花非染，流年景謾催。","隋宮凋綠草，晉室散黄埃。","西蜀波湍尽，东溟日月开。","如登最高处，應得见蓬萊。"]', '诗', 'shi', '', NULL, '題甘露寺 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd4140e-ba4f-45ee-85e7-20059eee6bd3', '江陵府初試澄心如水', '江陵府初試澄心如水', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["丹心何所喻，唯水並清虛。","莫測千尋底，難知一勺初。","內明非有物，上善本無魚。","澹泊隨高下，波瀾逐卷舒。","養蒙方浩浩，出險每徐徐。","若灌情田裏，常流盡不如。"]', '["丹心何所喻，唯水並清虛。","莫測千尋底，难知一勺初。","內明非有物，上善本無鱼。","澹泊隨高下，波瀾逐卷舒。","養蒙方浩浩，出險每徐徐。","若灌情田裏，常流尽不如。"]', '诗', 'shi', '', NULL, '江陵府初試澄心如水 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b95fdfcb-149d-46e7-a72c-5279ad03975b', '風不鳴條', '风不鳴條', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["習習和風至，過條不自鳴。","暗通青律起，遠傍白蘋生。","拂樹花仍落，經林鳥自驚。","幾牽蘿蔓動，潛惹柳絲輕。","入谷迷松響，開窗失竹聲。","薰弦方在御，萬國仰皇情。"]', '["習習和风至，過條不自鳴。","暗通青律起，远傍白蘋生。","拂樹花仍落，經林鸟自驚。","幾牽蘿蔓动，潛惹柳絲轻。","入谷迷松响，开窗失竹声。","薰弦方在御，万国仰皇情。"]', '诗', 'shi', '', NULL, '風不鳴條 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8159f17b-e5dd-4f1c-8347-cc576023ab17', '別宜春赴舉', '別宜春赴舉', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["秋天草木正蕭疎，西望秦關別舊居。","筵上芳樽今日酒，篋中黃卷古人書。","辭鄉且伴銜蘆雁，入海終爲戴角魚。","長短九霄飛直上，不敎毛羽落空虛。"]', '["秋天草木正蕭疎，西望秦关別旧居。","筵上芳樽今日酒，篋中黄卷古人书。","辞乡且伴銜蘆雁，入海終爲戴角鱼。","长短九霄飞直上，不敎毛羽落空虛。"]', '诗', 'shi', '', NULL, '別宜春赴舉 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03242a8b-2d7e-4677-bb24-24708db0f371', '射策後作', '射策後作', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["射策明時愧不才，敢期青律變寒灰。","晴憐斷雁侵雲去，暖見醯雞傍酒來。","箭發尚憂楊葉遠，愁生只恐杏花開。","曲江春淺人游少，盡日看山醉獨回。"]', '["射策明时愧不才，敢期青律变寒灰。","晴怜斷雁侵云去，暖见醯雞傍酒来。","箭發尚憂楊葉远，愁生只恐杏花开。","曲江春淺人游少，尽日看山醉独回。"]', '诗', 'shi', '', NULL, '射策後作 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2928212e-c708-48b1-8ee6-184e09ebd4da', '和主司王起', '和主司王起', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["嵩高降德爲時生，洪筆三題造化名。","鳳詔佇歸專北極，驪珠搜得盡東瀛。","褒衣已換金章貴，禁掖曾隨玉樹榮。","明日定知同相印，青衿新列柳間營。"]', '["嵩高降德爲时生，洪笔三題造化名。","鳳詔佇归專北極，驪珠搜得尽东瀛。","褒衣已換金章貴，禁掖曾隨玉樹榮。","明日定知同相印，青衿新列柳间營。"]', '诗', 'shi', '', NULL, '和主司王起 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ed3d65-746c-4a9c-9f26-2608b486af0a', '及第送潘圖歸宜春', '及第送潘圖归宜春', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["三載皇都恨食貧，北溟今日化窮鱗。","青雲乍喜逢知己，白社猶悲送故人。","對酒共驚千里別，看花自感一枝春。","君歸爲說龍門寺，雷雨初生電遶身。"]', '["三載皇都恨食貧，北溟今日化窮鱗。","青云乍喜逢知己，白社猶悲送故人。","对酒共驚千里別，看花自感一枝春。","君归爲说龙门寺，雷雨初生電遶身。"]', '诗', 'shi', '', NULL, '及第送潘圖歸宜春 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103988e1-bd51-4114-b08b-af14f1cf2224', '將歸宜春留題新安館', '將归宜春留題新安館', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["東里如今號鄭鄉，西家昔日近丘墻。","芸臺四部添新學，秘殿三年學老郎。","天外鴛鸞愁不見，山中雲鶴喜相忘。","猶張皂蓋歸蓬蓽，直謂時無許子將。"]', '["东里如今號鄭乡，西家昔日近丘墻。","芸台四部添新学，秘殿三年学老郎。","天外鴛鸾愁不见，山中云鹤喜相忘。","猶張皂蓋归蓬蓽，直謂时無許子將。"]', '诗', 'shi', '', NULL, '將歸宜春留題新安館 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7788b1f7-db6a-47b6-8e96-0689afff0c8f', '競渡詩', '競渡诗', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["石溪久住思端午，館驛樓前看發機。","鼙鼓動時雷隱隱，獸頭凌處雪微微。","衝波突出入齊[譀]，躍浪爭先鳥退飛。","向道是龍剛不信，果然奪得錦標歸。"]', '["石溪久住思端午，館驛楼前看發機。","鼙鼓动时雷隐隐，獸头凌处雪微微。","衝波突出入齊[譀]，躍浪爭先鸟退飞。","向道是龙剛不信，果然奪得錦標归。"]', '诗', 'shi', '', NULL, '競渡詩 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827f90ed-ddc0-45ff-b874-6958be37aabe', '除歙州途中寄座主王侍郎', '除歙州途中寄座主王侍郎', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["忽忝專城奉六條，自憐出谷屢遷喬。","驅車雖道還家近，捧日惟愁去國遙。","朱戶昨經新棨戟，風帆常覺戀簞瓢。","江天夜夜知消息，長見台星在碧霄。"]', '["忽忝專城奉六條，自怜出谷屢遷喬。","驱车雖道還家近，捧日惟愁去国遙。","朱戶昨經新棨戟，风帆常覺戀簞瓢。","江天夜夜知消息，长见台星在碧霄。"]', '诗', 'shi', '', NULL, '除歙州途中寄座主王侍郎 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6609985-8c69-4caa-a71b-20240ff12823', '御溝水', '御溝水', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["萬壑朝溟海，縈迴歲月多。","無如此溝水，咫尺奉天波。"]', '["万壑朝溟海，縈迴歲月多。","無如此溝水，咫尺奉天波。"]', '诗', 'shi', '', NULL, '御溝水 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5893314-7666-4343-8f5b-596bd10988bd', '楊柳枝', '楊柳枝', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["青鳥泉邊草木春，黃雲塞上是征人。","歸來若得長條贈，不憚風霜與苦辛。"]', '["青鸟泉邊草木春，黄云塞上是征人。","归来若得长條贈，不憚风霜與苦辛。"]', '诗', 'shi', '', NULL, '楊柳枝 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12891135-c82d-4c3f-abfc-abda5d41711d', '新植紅茶花偶出被人移去以詩索之', '新植紅茶花偶出被人移去以诗索之', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["嚴恨柴門一樹花，便隨香遠逐香車。","花如解語還應道，欺我郎君不在家。"]', '["嚴恨柴门一樹花，便隨香远逐香车。","花如解語還應道，欺我郎君不在家。"]', '诗', 'shi', '', NULL, '新植紅茶花偶出被人移去以詩索之 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a75702b-396d-448c-916d-0dab9cde542b', '戲題', '戲題', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["神女初離碧玉堦，彤雲猶擁牡丹鞋。","知道相公憐玉腕，強將纖手整金釵。"]', '["神女初離碧玉堦，彤云猶擁牡丹鞋。","知道相公怜玉腕，強將纖手整金釵。"]', '诗', 'shi', '', NULL, '戲題 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c035017-f98d-4922-9f93-4629cd53d771', '成名後作', '成名後作', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["桂在蟾宮不可攀，功成業熟也何難。","今朝折得東歸去，共與鄉閭年少看。"]', '["桂在蟾宮不可攀，功成業熟也何难。","今朝折得东归去，共與乡閭年少看。"]', '诗', 'shi', '', NULL, '成名後作 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a01f28-9a95-451d-8764-7cd54d4cbe7c', '登祝融寺蘭若', '登祝融寺蘭若', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["祝融絕頂萬餘層，策杖攀蘿步步登。","行到月宮霞外寺，白雲相伴兩三僧。"]', '["祝融絕頂万餘層，策杖攀蘿步步登。","行到月宮霞外寺，白云相伴兩三僧。"]', '诗', 'shi', '', NULL, '登祝融寺蘭若 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ea69c75-5aa8-47f9-980d-b65d7cdb01ee', '被謫連州', '被謫連州', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["黃絹外孫翻得罪，華顛故老莫相嗤。","連州萬里無親戚，舊識唯應有荔枝。"]', '["黄絹外孫翻得罪，华顛故老莫相嗤。","連州万里無親戚，旧識唯應有荔枝。"]', '诗', 'shi', '', NULL, '被謫連州 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca8e155-a2e7-466b-b002-509820884ebc', '謫後再書一絕', '謫後再书一絕', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["崆峒道士悞燒丹，赤鼠黃牙幾許難。","墜墮閻浮南斗下，不知何事犯星官。"]', '["崆峒道士悞燒丹，赤鼠黄牙幾許难。","墜墮閻浮南斗下，不知何事犯星官。"]', '诗', 'shi', '', NULL, '謫後再書一絕 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924eca61-cda9-41c2-bcd7-18aaae35802d', '題清遠峽觀音院二首 一', '題清远峽观音院二首 一', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["清潭洞澈深千丈，危岫攀蘿上幾層。","秋盡更無黃葉樹，夜闌唯對白頭僧。"]', '["清潭洞澈深千丈，危岫攀蘿上幾層。","秋尽更無黄葉樹，夜闌唯对白头僧。"]', '诗', 'shi', '', NULL, '題清遠峽觀音院二首 一 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6135c93-7c18-44bb-9d64-bff0773f2f21', '題清遠峽觀音院二首 二', '題清远峽观音院二首 二', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["風入古松添急雨，月臨虛檻背殘燈。","老猨嘯狖還欺客，來撼窗前百尺藤。"]', '["风入古松添急雨，月臨虛檻背殘灯。","老猨嘯狖還欺客，来撼窗前百尺藤。"]', '诗', 'shi', '', NULL, '題清遠峽觀音院二首 二 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41de33cc-8047-40b7-8c95-11b2668051e1', '喜楊舍人入翰林', '喜楊舍人入翰林', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["御筆親批翰長銜，夜開金殿送瑤緘。","平明玉案臨宣室，已見龍光出傅巖。"]', '["御笔親批翰长銜，夜开金殿送瑤緘。","平明玉案臨宣室，已见龙光出傅巖。"]', '诗', 'shi', '', NULL, '喜楊舍人入翰林 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff189c5-3f65-4f89-a969-6484d7ba1273', '謫連州書春牛榜子', '謫連州书春牛榜子', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["陽和未解逐民憂，雪滿羣山對白頭。","不得職田飢欲死，兒儂何事打春牛。"]', '["陽和未解逐民憂，雪满羣山对白头。","不得職田飢欲死，兒儂何事打春牛。"]', '诗', 'shi', '', NULL, '謫連州書春牛榜子 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0121f5-dd8e-4c64-99d8-5b7a547becec', '送弟', '送弟', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["去日家無擔石儲，汝須勤苦事樵漁。","古人盡向塵中遠，白日耕田夜讀書。"]', '["去日家無擔石儲，汝須勤苦事樵漁。","古人尽向塵中远，白日耕田夜读书。"]', '诗', 'shi', '', NULL, '送弟 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e7bb97-8b44-486d-9046-9a575f9ec7a7', '牧童', '牧童', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["誰人得似牧童心，牛上橫眠秋聽深。","時復往來吹一曲，何愁南北不知音。"]', '["誰人得似牧童心，牛上橫眠秋听深。","时复往来吹一曲，何愁南北不知音。"]', '诗', 'shi', '', NULL, '牧童 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92369195-889f-414e-8045-88e4a9e3c3d9', '嘲小兒', '嘲小兒', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["貪生只愛眼前珍，不覺風光度歲頻。","昨日見來騎竹馬，今朝早是有年人。"]', '["貪生只愛眼前珍，不覺风光度歲頻。","昨日见来騎竹马，今朝早是有年人。"]', '诗', 'shi', '', NULL, '嘲小兒 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2f667b-51d0-423e-8733-075fe00403b5', '金錢花', '金錢花', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["輪郭休誇四字書，紅窠寫出對庭除。","時時買得佳人笑，本色金錢却不如。"]', '["輪郭休誇四字书，紅窠寫出对庭除。","时时買得佳人笑，本色金錢却不如。"]', '诗', 'shi', '', NULL, '金錢花 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654ce2d7-35b0-494a-918b-7d87f8559335', '木筆花', '木笔花', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["媆如新竹管初齊，粉膩紅輕樣可攜。","誰與詩人偎檻看，好於牋墨併分題。"]', '["媆如新竹管初齊，粉膩紅轻樣可携。","誰與诗人偎檻看，好於牋墨併分題。"]', '诗', 'shi', '', NULL, '木筆花 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba28d02a-0178-475a-9f13-025bbc6b8a34', '句', '句', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["君夢涔陽月，中秋憶棹歌。","妙吹應諧鳳，工書定得鵝。","亭邊古木晝陰陰，亭下寒潭百丈深。","黃菊舊連陶令宅，青山遙負向平心。"]', '["君梦涔陽月，中秋憶棹歌。","妙吹應諧鳳，工书定得鵝。","亭邊古木晝陰陰，亭下寒潭百丈深。","黄菊旧連陶令宅，青山遙負向平心。"]', '诗', 'shi', '', NULL, '句 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f133ced6-8bcb-4a1b-bddb-4a571a3e8000', '塞下曲', '塞下曲', 'ae9ab17d-49ff-4d93-811f-1c2505859112', '唐', '["北風鳴晚角，雨雪塞雲低。","烽舉戰軍動，天寒征馬嘶。","出營紅斾展，過磧暗沙迷。"]', '["北风鳴晚角，雨雪塞云低。","烽舉戰軍动，天寒征马嘶。","出營紅斾展，過磧暗沙迷。"]', '诗', 'shi', '', NULL, '塞下曲 丁稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12726193-5bd7-4256-963b-0722e4457ce7', '和主司王起', '和主司王起', 'ae9ab17d-49ff-4d93-811f-1c2505859112', '唐', '["公心獨立副天心，三轄春闈冠古今。","蘭署門生皆入室，蓮峰太守別知音。","同升翰苑時名重，遍歷朝端主意深。","新有受恩江海客，坐聽朝夕繼爲霖。"]', '["公心独立副天心，三轄春闈冠古今。","蘭署门生皆入室，蓮峰太守別知音。","同升翰苑时名重，遍歷朝端主意深。","新有受恩江海客，坐听朝夕繼爲霖。"]', '诗', 'shi', '', NULL, '和主司王起 丁稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df259936-03b8-42cf-8db5-12f4c6c3417a', '和主司王起', '和主司王起', '3ee6a3b5-9455-485a-8011-427a773e2137', '唐', '["昔年桃李已滋榮，今日蘭蓀又發生。","葑菲采時皆有道，權衡分處且無情。","叨陪鴛鷺朝天客，共作門闌出谷鸎。","何事感恩偏覺重，忽聞金榜扣柴荆。"]', '["昔年桃李已滋榮，今日蘭蓀又發生。","葑菲采时皆有道，權衡分处且無情。","叨陪鴛鷺朝天客，共作门闌出谷鸎。","何事感恩偏覺重，忽闻金榜扣柴荆。"]', '诗', 'shi', '', NULL, '和主司王起 高退之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450da1d8-8fdd-473d-ad15-85b7aabfcdb2', '和主司王起', '和主司王起', 'd16b24c2-3b11-4285-877e-c101ba4178d0', '唐', '["當年門下化龍成，今日餘波進後生。","仙籍共知推麗藻，禁垣同得薦嘉名。","桃蹊早茂誇新萼，菊圃初開耀晚英。","誰料羽毛方出谷，許敎齊和九臯鳴。"]', '["當年门下化龙成，今日餘波進後生。","仙籍共知推丽藻，禁垣同得薦嘉名。","桃蹊早茂誇新萼，菊圃初开耀晚英。","誰料羽毛方出谷，許敎齊和九臯鳴。"]', '诗', 'shi', '', NULL, '和主司王起 孟球 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac42eb7-aca0-40cc-8737-474974bf2849', '和主司王起', '和主司王起', '30b16dcd-bd31-4693-81d2-76481d1a4b9e', '唐', '["孔門頻建鑄顏功，紫綬青衿感激同。","一簣勤勞成太華，三年恩德仰維嵩。","楊隨前輩穿皆中，桂許平人折欲空。","慚和周郎應見顧，感知大造竟無窮。"]', '["孔门頻建鑄顏功，紫綬青衿感激同。","一簣勤勞成太华，三年恩德仰維嵩。","楊隨前輩穿皆中，桂許平人折欲空。","慚和周郎應见顧，感知大造竟無窮。"]', '诗', 'shi', '', NULL, '和主司王起 劉耕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78b7af99-f1d7-4db1-b2cf-d2f419c6fd30', '和主司王起', '和主司王起', '581dc0ea-deaa-4d12-9305-5bff6b27fdc8', '唐', '["常將公道選羣生，猶被春闈屈重名。","文柄久持殊歲紀，恩門三啓動寰瀛。","雲霄幸接鴛鸞盛，變化欣同草木榮。","乍得陽和如細柳，參差長近亞夫營。"]', '["常將公道選羣生，猶被春闈屈重名。","文柄久持殊歲紀，恩门三啓动寰瀛。","云霄幸接鴛鸾盛，变化欣同草木榮。","乍得陽和如細柳，參差长近亞夫營。"]', '诗', 'shi', '', NULL, '和主司王起 裴翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0958b4-7b3c-4ba9-bbb2-f2f851a86843', '和主司王起', '和主司王起', '21df6ebe-f3c6-4cb4-8deb-4b00bc828cef', '唐', '["滿朝簪髮半門生，又見新書甲乙名。","孤進自今開道路，至公依舊振寰瀛。","雲飛太華清詞著，花發長安白屋榮。","忝受恩光同上客，惟將報德是經營。"]', '["满朝簪髮半门生，又见新书甲乙名。","孤進自今开道路，至公依旧振寰瀛。","云飞太华清词著，花發长安白屋榮。","忝受恩光同上客，惟將報德是經營。"]', '诗', 'shi', '', NULL, '和主司王起 樊驤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b06eaa-d8c0-41d9-b404-8a0d3f57dcf1', '和主司王起', '和主司王起', 'f43b6821-a81b-45f7-9ff4-dd0eff623ab8', '唐', '["滿朝朱紫半門生，新榜勞人又得名。","國器舊知收片玉，朝宗轉覺集登瀛。","同升翰苑三年美，繼入花源九族榮。","共仰蓮峰聽雪唱，欲賡仙曲意怔營。"]', '["满朝朱紫半门生，新榜勞人又得名。","国器旧知收片玉，朝宗轉覺集登瀛。","同升翰苑三年美，繼入花源九族榮。","共仰蓮峰听雪唱，欲賡仙曲意怔營。"]', '诗', 'shi', '', NULL, '和主司王起 崔軒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ce8bfc-de62-4c4f-8864-4c42992edaa8', '和主司王起', '和主司王起', 'c743261b-c571-47ed-829e-5205f7e34b98', '唐', '["一振聲華入紫薇，三開秦鏡照春闈。","龍門舊列金章貴，鶯谷新遷碧落飛。","恩感風雷宜變化，詩裁錦繡借光輝。","誰知散質多榮忝，鴛鷺清塵接布衣。"]', '["一振声华入紫薇，三开秦镜照春闈。","龙门旧列金章貴，鶯谷新遷碧落飞。","恩感风雷宜变化，诗裁錦繡借光輝。","誰知散質多榮忝，鴛鷺清塵接布衣。"]', '诗', 'shi', '', NULL, '和主司王起 蒯希逸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549adca9-4e7c-4947-ba37-7577efd1c0da', '句', '句', 'c743261b-c571-47ed-829e-5205f7e34b98', '唐', '["蟾蜍醉裏破，蛺蝶夢中殘。","山險不曾離馬後，酒醒長見在牀前。"]', '["蟾蜍醉裏破，蛺蝶梦中殘。","山險不曾離马後，酒醒长见在牀前。"]', '诗', 'shi', '', NULL, '句 蒯希逸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ac8e10-2d47-4abf-a30b-019f8053a0be', '望九華山', '望九华山', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["茲山突出何怪奇，上有萬狀無凡姿。","大者嶙峋若奔兕，小者㠥嵬如嬰兒。","玉柱金莖相拄枝，干空踰碧勢參差。","虛中始訝巨靈擘，阧處乍驚愚叟移。","蘿煙石月相蔽虧，天風褭褭猨咿咿。","龍潭萬古噴飛溜，虎穴幾人能得窺。","吁予比年愛靈境，到此始覺魂神馳。","如何獨得百丈索，直上高峰拋俗羈。"]', '["茲山突出何怪奇，上有万狀無凡姿。","大者嶙峋若奔兕，小者㠥嵬如嬰兒。","玉柱金莖相拄枝，干空踰碧勢參差。","虛中始訝巨靈擘，阧处乍驚愚叟移。","蘿煙石月相蔽虧，天风褭褭猨咿咿。","龙潭万古噴飞溜，虎穴幾人能得窺。","吁予比年愛靈境，到此始覺魂神驰。","如何独得百丈索，直上高峰拋俗羈。"]', '诗', 'shi', '', NULL, '望九華山 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae6f6ea-c871-49b4-932e-5e3e0931714c', '春望', '春望', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["春海鏡長天，青郊麗上年。","林光虛霽曉，山翠薄晴煙。","氣暖禽聲變，風恬草色鮮。","散襟披石磴，韶景自深憐。"]', '["春海镜长天，青郊丽上年。","林光虛霽晓，山翠薄晴煙。","氣暖禽声变，风恬草色鲜。","散襟披石磴，韶景自深怜。"]', '诗', 'shi', '', NULL, '春望 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37033da7-e91a-442b-99d0-08013f7f359f', '蠡澤旅懷', '蠡澤旅懷', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["誰言行旅日，況復桃花時。","水即滄溟遠，星從天漢垂。","川光獨鳥暮，林色落英遲。","豈是王程急，偏多游子悲。"]', '["誰言行旅日，況复桃花时。","水即滄溟远，星從天漢垂。","川光独鸟暮，林色落英遲。","豈是王程急，偏多游子悲。"]', '诗', 'shi', '', NULL, '蠡澤旅懷 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8793db-cd72-4133-9a1d-902fe663291a', '宴韋侍御新亭', '宴韋侍御新亭', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["煙磴披青靄，風筵藉紫苔。","花香凌桂醑，竹影落藤桮。","鳴籟將歌遠，飛枝拂舞開。","未愁留興晚，明月度雲來。"]', '["煙磴披青靄，风筵藉紫苔。","花香凌桂醑，竹影落藤桮。","鳴籟將歌远，飞枝拂舞开。","未愁留兴晚，明月度云来。"]', '诗', 'shi', '', NULL, '宴韋侍御新亭 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c9c567-cd90-4a43-b10c-9e1769ed0ee0', '人日', '人日', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["春輝新入碧煙開，芳院初將穆景來。","共向花前圖瑞勝，試看池上動輕苔。","林香半落沾羅幌，蕙色微含近酒桮。","聞道宸游方命賞，應隨恩賚喜昭回。"]', '["春輝新入碧煙开，芳院初將穆景来。","共向花前圖瑞勝，試看池上动轻苔。","林香半落沾羅幌，蕙色微含近酒桮。","闻道宸游方命賞，應隨恩賚喜昭回。"]', '诗', 'shi', '', NULL, '人日 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd3313c-f78d-4976-80e5-c6d87addffc6', '和主司王起', '和主司王起', '6b50d7e0-b238-4111-99e0-1a4d056bbaff', '唐', '["龍門一變荷生成，況是三傳不朽名。","美譽早聞喧北闕，頹波今見走東瀛。","鴛行既接參差影，雞樹仍同次第榮。","從此青衿與朱紫，升堂侍宴更何營。"]', '["龙门一变荷生成，況是三傳不朽名。","美譽早闻喧北闕，頹波今见走东瀛。","鴛行既接參差影，雞樹仍同次第榮。","從此青衿與朱紫，升堂侍宴更何營。"]', '诗', 'shi', '', NULL, '和主司王起 林滋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e427cef-2f58-4725-a290-2e3e6f4db072', '聽蜀道士琴歌', '听蜀道士琴歌', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["至道不可見，正聲難得聞。","忽逢羽客抱綠綺，西別峨嵋峰頂雲。","初排□面躡輕響，似擲細珠鳴玉上。","忽揮素爪畫七弦，蒼崖劈裂迸碎泉。","憤聲高，怨聲咽，屈原呌天兩妃絕。","朝雉飛，雙鶴離，屬玉夜啼獨鶩悲。","吹我神飛碧霄裏，牽我心靈入秋水。","有如驅逐太古來，邪淫辟蕩貞心開。","孝爲子，忠爲臣，不獨語言能敎人。","前弄嘯，後弄嚬，一舒一慘非冬春。","從朝至暮聽不足，相將直說瀛洲宿。","更深彈罷背孤燈，窗雪蕭蕭打寒竹。","人間豈合值仙蹤，此別多應不再逢。","抱琴却上瀛洲去，一片白雲千萬峰。"]', '["至道不可见，正声难得闻。","忽逢羽客抱綠綺，西別峨嵋峰頂云。","初排□面躡轻响，似擲細珠鳴玉上。","忽揮素爪畫七弦，蒼崖劈裂迸碎泉。","憤声高，怨声咽，屈原呌天兩妃絕。","朝雉飞，雙鹤離，屬玉夜啼独鶩悲。","吹我神飞碧霄裏，牽我心靈入秋水。","有如驱逐太古来，邪淫辟蕩貞心开。","孝爲子，忠爲臣，不独語言能敎人。","前弄嘯，後弄嚬，一舒一慘非冬春。","從朝至暮听不足，相將直说瀛洲宿。","更深彈罷背孤灯，窗雪蕭蕭打寒竹。","人间豈合值仙蹤，此別多應不再逢。","抱琴却上瀛洲去，一片白云千万峰。"]', '诗', 'shi', '', NULL, '聽蜀道士琴歌 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4854ab-22e7-44f8-9069-7ef8b9ffc114', '和主司王起', '和主司王起', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["恩光忽逐曉春生，金榜前頭忝姓名。","三感至公裨造化，重揚文德振寰瀛。","佇爲霖雨曾相賀，半在雲霄覺更榮。","何處新詩添照灼，碧蓮峰下柳間營。"]', '["恩光忽逐晓春生，金榜前头忝姓名。","三感至公裨造化，重揚文德振寰瀛。","佇爲霖雨曾相賀，半在云霄覺更榮。","何处新诗添照灼，碧蓮峰下柳间營。"]', '诗', 'shi', '', NULL, '和主司王起 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce26a624-d69c-4a08-b37e-f188fbbaabcc', '杜司空席上賦', '杜司空席上賦', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["紅燈初上月輪高，照見堂前萬朵桃。","觱栗調清銀象管，琵琶聲亮紫檀槽。","能歌姹女顏如玉，解引蕭郎眼似刀。","爭奈夜深拋耍令，舞來挼去使人勞。"]', '["紅灯初上月輪高，照见堂前万朵桃。","觱栗調清銀象管，琵琶声亮紫檀槽。","能歌姹女顏如玉，解引蕭郎眼似刀。","爭奈夜深拋耍令，舞来挼去使人勞。"]', '诗', 'shi', '', NULL, '杜司空席上賦 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93bfdbd2-59a7-4d8f-b00a-3d2e7a38bbe1', '賦寒食日亥時', '賦寒食日亥时', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["人定朱門尚未開，初星粲粲照人回。","此時寒食無煙火，花柳蒼蒼月欲來。"]', '["人定朱门尚未开，初星粲粲照人回。","此时寒食無煙火，花柳蒼蒼月欲来。"]', '诗', 'shi', '', NULL, '賦寒食日亥時 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ff08ae-7a07-4825-9dd3-ef08233463bc', '句', '句', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["翠蓋不西來，池上天池歇。","冉冉池上煙，盈盈池上柳。","生貴非道傍，不斷行人手。"]', '["翠蓋不西来，池上天池歇。","冉冉池上煙，盈盈池上柳。","生貴非道傍，不斷行人手。"]', '诗', 'shi', '', NULL, '句 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bee6ea7-4c8e-4c50-972a-82cac662b932', '風不鳴條', '风不鳴條', '2e24a33c-37b8-4a77-8e04-c11623cc5e5f', '唐', '["五緯起祥飆，無聲瑞聖朝。","稍開含露蘂，纔轉惹煙條。","密葉應潛變，低枝幾暗搖。","林間鶯欲囀，花下蝶微飄。","初滿沿堤草，因生逐水苗。","太平無一事，天外奏虞韶。"]', '["五緯起祥飆，無声瑞聖朝。","稍开含露蘂，纔轉惹煙條。","密葉應潛变，低枝幾暗搖。","林间鶯欲囀，花下蝶微飄。","初满沿堤草，因生逐水苗。","太平無一事，天外奏虞韶。"]', '诗', 'shi', '', NULL, '風不鳴條 黃頗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ffec39-c0a6-46ca-ae5d-53c32c239bd7', '和主司王起', '和主司王起', '2e24a33c-37b8-4a77-8e04-c11623cc5e5f', '唐', '["二十二年文敎主，三千上士滿皇州。","獨陪宣父蓬瀛奏，方接顏生魯衛遊。","多羨龍門齊變化，屢看雞樹第名流。","升堂何處最榮美，朱紫環[尊]幾處酬。"]', '["二十二年文敎主，三千上士满皇州。","独陪宣父蓬瀛奏，方接顏生魯衛游。","多羨龙门齊变化，屢看雞樹第名流。","升堂何处最榮美，朱紫环[尊]幾处酬。"]', '诗', 'shi', '', NULL, '和主司王起 黃頗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8bd2fe-2125-4a44-a3e9-25b7ffd4706f', '聞宜春諸舉子陪郡主登河梁翫月', '闻宜春諸舉子陪郡主登河梁翫月', '2e24a33c-37b8-4a77-8e04-c11623cc5e5f', '唐', '["一年秋半月當空，遙羨飛觴接庾公。","虹影迥分銀漢上，兔輝全寫玉筵中。","笙歌送盡迎寒漏，冰雪吟消永夜風。","雖向東堂先折桂，不如賓席此時同。"]', '["一年秋半月當空，遙羨飞觴接庾公。","虹影迥分銀漢上，兔輝全寫玉筵中。","笙歌送尽迎寒漏，冰雪吟消永夜风。","雖向东堂先折桂，不如賓席此时同。"]', '诗', 'shi', '', NULL, '聞宜春諸舉子陪郡主登河梁翫月 黃頗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4922f871-64de-47b8-b45c-dee50d277f28', '和主司王起', '和主司王起', 'f91fca6f-3ec2-4c82-97a3-b5795acfbc85', '唐', '["三開文鏡繼芳聲，暗暗雲霄接去程。","會壓洪波先得路，早陞清禁共垂名。","蓮峰對處朱輪貴，金榜傳時玉韻成。","更許下才聽白雪，一枝今過郄詵榮。"]', '["三开文镜繼芳声，暗暗云霄接去程。","會壓洪波先得路，早陞清禁共垂名。","蓮峰对处朱輪貴，金榜傳时玉韻成。","更許下才听白雪，一枝今過郄詵榮。"]', '诗', 'shi', '', NULL, '和主司王起 張道符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cea501-63bf-4629-be32-2c452d3fa8e0', '和主司王起', '和主司王起', 'f737d594-282f-4660-8ba9-e2df5056f561', '唐', '["常將公道選諸生，不是鴛鴻不得名。","天上宴回聯步武，禁中麻出滿寰瀛。","簪裾盡過前賢貴，門館仍叨舊學榮。","看著鳳池相繼入，都堂那肯滯關營。"]', '["常將公道選諸生，不是鴛鴻不得名。","天上宴回聯步武，禁中麻出满寰瀛。","簪裾尽過前賢貴，门館仍叨旧学榮。","看著鳳池相繼入，都堂那肯滯关營。"]', '诗', 'shi', '', NULL, '和主司王起 丘上卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df9c129-217f-4c79-9bf7-536b449c9e04', '和主司王起', '和主司王起', '1036e46f-2b45-4238-9109-4b60c0ff4fc3', '唐', '["重德由來爲國生，五朝清顯冠公卿。","風波久佇濟川檝，羽翼三遷出谷鶯。","絳帳青衿同日貴，春蘭秋菊異時榮。","孔門弟子皆賢哲，誰料窮儒忝一名。"]', '["重德由来爲国生，五朝清显冠公卿。","风波久佇濟川檝，羽翼三遷出谷鶯。","絳帳青衿同日貴，春蘭秋菊異时榮。","孔门弟子皆賢哲，誰料窮儒忝一名。"]', '诗', 'shi', '', NULL, '和主司王起 石貫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('765c2296-3b94-4f60-ac6d-b6d55064e36a', '和主司王起', '和主司王起', '0654cda4-85f8-4320-96be-2bc3c560521f', '唐', '["文學宗師心秤平，無私三用佐貞明。","恩波舊是仙舟客，德宇新添月桂名。","蘭署崇資金色重，蓮峰高唱玉音清。","羽毛方荷生成力，難繼鸞皇上漢聲。"]', '["文学宗師心秤平，無私三用佐貞明。","恩波旧是仙舟客，德宇新添月桂名。","蘭署崇資金色重，蓮峰高唱玉音清。","羽毛方荷生成力，难繼鸾皇上漢声。"]', '诗', 'shi', '', NULL, '和主司王起 李潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('922c39a1-9e9c-4353-b82c-ce2cf1dd11ec', '和主司王起', '和主司王起', '437dd367-dadd-4124-90a8-813d54921023', '唐', '["科文又主守初時，光顯門生濟會期。","美擅東堂登甲乙，榮同內署侍恩私。","羣鶯共喜新遷木，雙鳳皆當即入池。","別有倍深知感士，曾經兩度得芳枝。"]', '["科文又主守初时，光显门生濟會期。","美擅东堂登甲乙，榮同內署侍恩私。","羣鶯共喜新遷木，雙鳳皆當即入池。","別有倍深知感士，曾經兩度得芳枝。"]', '诗', 'shi', '', NULL, '和主司王起 孟守 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe559bd-08aa-4f4b-98bb-792a73aeb220', '和主司王起', '和主司王起', 'e7711fe5-7195-4c59-b4d5-c3311fdde608', '唐', '["儒雅皆傳德敎行，幾崇浮俗贊文明。","龍門昔上波濤遠，禁署同登渥澤榮。","虛散謬當陪杞梓，後先寧異感生成。","時方側席徵賢急，況說謌謠近帝京。"]', '["儒雅皆傳德敎行，幾崇浮俗贊文明。","龙门昔上波濤远，禁署同登渥澤榮。","虛散謬當陪杞梓，後先寧異感生成。","时方側席徵賢急，況说謌謠近帝京。"]', '诗', 'shi', '', NULL, '和主司王起 唐思言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ca8540-d994-4db6-93ce-fc4a58771397', '風不鳴條', '风不鳴條', 'ee5cb883-3dd0-4666-a04c-2f349f2df897', '唐', '["旭日懸清景，微風在綠條。","入松聲不發，度柳影空搖。","長養應潛變，扶疎每暗飄。","有林時嫋嫋，無樹漸蕭蕭。","慢逐青煙散，輕和瑞氣饒。","豐年知有待，歌詠美唐堯。"]', '["旭日懸清景，微风在綠條。","入松声不發，度柳影空搖。","长養應潛变，扶疎每暗飄。","有林时嫋嫋，無樹漸蕭蕭。","慢逐青煙散，轻和瑞氣饒。","豐年知有待，歌詠美唐堯。"]', '诗', 'shi', '', NULL, '風不鳴條 戈牢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a5e0a7-720c-4c82-9f37-5aef6360fb4c', '和主司王起', '和主司王起', 'ee5cb883-3dd0-4666-a04c-2f349f2df897', '唐', '["聖乾文德最稱賢，自古儒生少比肩。","再啓龍門將二紀，兩司鶯谷已三年。","蓬山皆美成榮貴，金榜誰知忝後先。","正是感恩流涕日，但思旌斾碧峰前。"]', '["聖乾文德最稱賢，自古儒生少比肩。","再啓龙门將二紀，兩司鶯谷已三年。","蓬山皆美成榮貴，金榜誰知忝後先。","正是感恩流涕日，但思旌斾碧峰前。"]', '诗', 'shi', '', NULL, '和主司王起 戈牢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661a011f-b13e-43e3-8ed0-7899fe6d1c17', '風不鳴條', '风不鳴條', 'de30f321-38b8-493f-ab19-c6fe6c6ef547', '唐', '["寂寂曙風生，遲遲散野輕。","露華搖有滴，林葉褭無聲。","暗翦藂芳發，空傳谷鳥鳴。","悠揚韶景靜，澹蕩霽煙橫。","遠水波瀾息，荒郊草樹榮。","吾君垂至化，萬類共澄清。"]', '["寂寂曙风生，遲遲散野轻。","露华搖有滴，林葉褭無声。","暗翦藂芳發，空傳谷鸟鳴。","悠揚韶景静，澹蕩霽煙橫。","远水波瀾息，荒郊草樹榮。","吾君垂至化，万類共澄清。"]', '诗', 'shi', '', NULL, '風不鳴條 金厚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a0b7cd-4720-4ffb-92d6-0d72359fdf65', '和主司王起', '和主司王起', 'de30f321-38b8-493f-ab19-c6fe6c6ef547', '唐', '["長慶曾收間世英，果居臺閣冠公卿。","天書再受恩波遠，金榜三開日月明。","已見差肩趍翰苑，更期連步掌台衡。","小儒謬蹟雲霄路，心仰蓮峰望太清。"]', '["长慶曾收间世英，果居台閣冠公卿。","天书再受恩波远，金榜三开日月明。","已见差肩趍翰苑，更期連步掌台衡。","小儒謬蹟云霄路，心仰蓮峰望太清。"]', '诗', 'shi', '', NULL, '和主司王起 金厚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ff208d-be9b-4ed3-9fbc-c8f45a42f941', '風不鳴條', '风不鳴條', '390d0d6d-c78e-423d-8a3c-4492f3ae97bc', '唐', '["聖日祥風起，韶暉助發生。","蒙蒙遙野色，褭褭細條輕。","荏弱看漸動，怡和吹不鳴。","枝含餘露濕，林霽曉煙平。","縹緲春光媚，悠揚景氣晴。","康哉帝堯代，寰宇共澄清。"]', '["聖日祥风起，韶暉助發生。","蒙蒙遙野色，褭褭細條轻。","荏弱看漸动，怡和吹不鳴。","枝含餘露濕，林霽晓煙平。","縹緲春光媚，悠揚景氣晴。","康哉帝堯代，寰宇共澄清。"]', '诗', 'shi', '', NULL, '風不鳴條 王甚夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b26e5a5-cf1f-4349-8e7f-3a294937ba77', '和主司王起', '和主司王起', '390d0d6d-c78e-423d-8a3c-4492f3ae97bc', '唐', '["春闈帝念主生成，長慶公聞兩歲名。","有蘊赤心分雨露，無私和氣浹寰瀛。","龍門乍出難勝幸，鴛侶先行是最榮。","遙仰高峰看白雪，多慚屬和意屏營。"]', '["春闈帝念主生成，长慶公闻兩歲名。","有蘊赤心分雨露，無私和氣浹寰瀛。","龙门乍出难勝幸，鴛侶先行是最榮。","遙仰高峰看白雪，多慚屬和意屏營。"]', '诗', 'shi', '', NULL, '和主司王起 王甚夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b3df43d-b443-466e-8850-b800c99ec211', '送李潛歸綿州覲省', '送李潛归綿州覲省', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["朱樓對翠微，紅斾出重扉。","此地千人望，寥天一鶴歸。","雪封山崦白，鳥拂棧梁飛。","誰比趨庭戀，驪珠耀綵衣。"]', '["朱楼对翠微，紅斾出重扉。","此地千人望，寥天一鹤归。","雪封山崦白，鸟拂棧梁飞。","誰比趨庭戀，驪珠耀綵衣。"]', '诗', 'shi', '', NULL, '送李潛歸綿州覲省 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2f6c8f-6000-403e-8488-a2e31862191b', '塞外寄張侍御', '塞外寄張侍御', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["千里入黃雲，羈愁日日新。","疎鐘關路曉，遠雨塞山春。","南眺有歸鴈，北來無故人。","却思陪宴處，迴望與天隣。"]', '["千里入黄云，羈愁日日新。","疎鐘关路晓，远雨塞山春。","南眺有归鴈，北来無故人。","却思陪宴处，迴望與天隣。"]', '诗', 'shi', '', NULL, '塞外寄張侍御 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('078879f1-198b-4373-af92-9be67071767e', '曉發', '晓發', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["旅行宜早發，況復是南歸。","月影緣山盡，鐘聲隔浦微。","殘星螢共失，落葉鳥和飛。","去去渡南浦，村中人出稀。"]', '["旅行宜早發，況复是南归。","月影緣山尽，鐘声隔浦微。","殘星螢共失，落葉鸟和飞。","去去渡南浦，村中人出稀。"]', '诗', 'shi', '', NULL, '曉發 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e275cf-2879-446f-92a4-4a57e69f819a', '題終南山隱者居', '題終南山隐者居', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["開門絕壑旁，躡蘚過花梁。","路入峰巒影，風來芝朮香。","夜吟明雪牖，春夢閉雲房。","盡室更何有，一琴兼一觴。"]', '["开门絕壑旁，躡蘚過花梁。","路入峰巒影，风来芝朮香。","夜吟明雪牖，春梦閉云房。","尽室更何有，一琴兼一觴。"]', '诗', 'shi', '', NULL, '題終南山隱者居 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b63cf2d-0b6b-46fa-9be4-cfa9d397dc15', '嘉川驛樓晚望', '嘉川驛楼晚望', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["樓壓寒江上，開簾對翠微。","斜陽諸嶺暮，古渡一僧歸。","窗逈雲衝起，汀遙鳥背飛。","誰言坐多倦，目極自忘機。"]', '["楼壓寒江上，开簾对翠微。","斜陽諸嶺暮，古渡一僧归。","窗逈云衝起，汀遙鸟背飞。","誰言坐多倦，目極自忘機。"]', '诗', 'shi', '', NULL, '嘉川驛樓晚望 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b9d040-a851-4b52-9a73-2fa4f0e919d3', '送人歸吳', '送人归吳', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["東吳與上國，萬里路迢迢。","爲別晨昏久，全輕水陸遙。","湘陰島上寺，楚色月中潮。","到此一長望，知君積恨銷。"]', '["东吳與上国，万里路迢迢。","爲別晨昏久，全轻水陸遙。","湘陰島上寺，楚色月中潮。","到此一长望，知君積恨銷。"]', '诗', 'shi', '', NULL, '送人歸吳 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e6633c-de24-4266-b94d-3b588c4001f9', '送石貫歸湖州', '送石貫归湖州', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["同志幸同年，高堂君獨還。","齊榮恩未報，共隱事應閑。","訪寺臨湖岸，開樓見海山。","洛中推二陸，莫久戀鄉關。"]', '["同志幸同年，高堂君独還。","齊榮恩未報，共隐事應闲。","訪寺臨湖岸，开楼见海山。","洛中推二陸，莫久戀乡关。"]', '诗', 'shi', '', NULL, '送石貫歸湖州 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc1b513-d9b8-47ac-ad9b-d05fad839597', '送劉耕歸舒州', '送劉耕归舒州', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["四座莫紛紛，須臾岐路分。","自從同得意，誰不惜離羣。","舊國連青海，歸程在白雲。","棄繻當日路，應競看終軍。"]', '["四座莫紛紛，須臾岐路分。","自從同得意，誰不惜離羣。","旧国連青海，归程在白云。","棄繻當日路，應競看終軍。"]', '诗', 'shi', '', NULL, '送劉耕歸舒州 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693778c0-81f5-4fa1-97a3-a53246b99651', '寄贈許璋少府', '寄贈許璋少府', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["若說君高道，何人更得如。","公庭唯樹石，生計是琴書。","詩句峭無敵，文才清有餘。","不知尺水內，爭滯北溟魚。"]', '["若说君高道，何人更得如。","公庭唯樹石，生計是琴书。","诗句峭無敵，文才清有餘。","不知尺水內，爭滯北溟鱼。"]', '诗', 'shi', '', NULL, '寄贈許璋少府 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8dff789-b8cb-423b-a259-465e5c6f8e69', '寄雍陶先輩', '寄雍陶先輩', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["知音杳何處，書札寄無由。","獨宿月中寺，相思天畔樓。","露凝衰草白，螢度遠煙秋。","悵望難歸枕，吟勞生夜愁。"]', '["知音杳何处，书札寄無由。","独宿月中寺，相思天畔楼。","露凝衰草白，螢度远煙秋。","悵望难归枕，吟勞生夜愁。"]', '诗', 'shi', '', NULL, '寄雍陶先輩 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a647860-3e15-44de-8557-a01692364456', '寄友人', '寄友人', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["西風又開菊，久客意如何。","舊國天涯遠，清砧月夜多。","明時難際會，急景易蹉跎。","抱玉終須獻，誰言戀薜蘿。"]', '["西风又开菊，久客意如何。","旧国天涯远，清砧月夜多。","明时难際會，急景易蹉跎。","抱玉終須獻，誰言戀薜蘿。"]', '诗', 'shi', '', NULL, '寄友人 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74eded6-c668-4055-996b-b238c2531254', '感懷陳情', '感懷陳情', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["恩重空感激，何門誓殺身。","謬曾分玉石，竟自困風塵。","陰谷非因暖，幽叢豈望春。","升沈在言下，應念異他人。"]', '["恩重空感激，何门誓殺身。","謬曾分玉石，竟自困风塵。","陰谷非因暖，幽叢豈望春。","升沈在言下，應念異他人。"]', '诗', 'shi', '', NULL, '感懷陳情 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6503dc8-2d00-4ee0-a3cd-dc55313bd97d', '送程秀才下第歸蜀', '送程秀才下第归蜀', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["鶯遷與鶂退，十載泣岐分。","蜀道重來老，巴猨此去聞。","曉程侵嶺雪，遠棧入谿雲。","莫滯趨庭戀，榮親祗待君。"]', '["鶯遷與鶂退，十載泣岐分。","蜀道重来老，巴猨此去闻。","晓程侵嶺雪，远棧入谿云。","莫滯趨庭戀，榮親祗待君。"]', '诗', 'shi', '', NULL, '送程秀才下第歸蜀 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83520070-449b-4362-bddf-708f5038024f', '旱魚詞上苗相公', '旱鱼词上苗相公', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["似龍鱗已足，唯是欠登門。","日裏腮猶濕，泥中目未昏。","乞鋤防蟻穴，望水瀉金盆。","他日能爲雨，公田報此恩。"]', '["似龙鱗已足，唯是欠登门。","日裏腮猶濕，泥中目未昏。","乞鋤防蟻穴，望水瀉金盆。","他日能爲雨，公田報此恩。"]', '诗', 'shi', '', NULL, '旱魚詞上苗相公 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e041d3f4-bb26-40d0-9252-1826e250ad8e', '野寺寓居即事二首 一', '野寺寓居即事二首 一', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["南山色當戶，初日半簷時。","鶴去臥看遠，僧來嫌起遲。","窗明雲影斷，庭曉樹陰移。","何處題新句，連谿密葉垂。"]', '["南山色當戶，初日半簷时。","鹤去臥看远，僧来嫌起遲。","窗明云影斷，庭晓樹陰移。","何处題新句，連谿密葉垂。"]', '诗', 'shi', '', NULL, '野寺寓居即事二首 一 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f8acdb-25d2-4cdd-90ac-b5028d3fc423', '野寺寓居即事二首 二', '野寺寓居即事二首 二', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["古寺更何有，當庭唯折幢。","伴僧青蘚榻，對雨白雲窗。","暝色生前嶺，離魂隔遠江。","沙洲半藜草，飛鷺白雙雙。"]', '["古寺更何有，當庭唯折幢。","伴僧青蘚榻，对雨白云窗。","暝色生前嶺，離魂隔远江。","沙洲半藜草，飞鷺白雙雙。"]', '诗', 'shi', '', NULL, '野寺寓居即事二首 二 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd89a46-2d7a-4510-80db-5bcfbaffa33b', '襄州獻盧尚書', '襄州獻盧尚书', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["立事成功盡遠圖，一方獨與萬方殊。","藩臣皆競師兵畧，相國今多揖廟謨。","禮樂政行凋弊俗，歌謠聲徹帝王都。","即隨鳳詔歸何處，祗是操持造化鑪。"]', '["立事成功尽远圖，一方独與万方殊。","藩臣皆競師兵畧，相国今多揖廟謨。","禮乐政行凋弊俗，歌謠声徹帝王都。","即隨鳳詔归何处，祗是操持造化鑪。"]', '诗', 'shi', '', NULL, '襄州獻盧尚書 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b5920c0-c1a7-44c7-8d14-48c22657b8a5', '將歸蜀留獻恩地僕射二首 一', '將归蜀留獻恩地僕射二首 一', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["自持衡鏡採幽沈，此事常聞曠古今。","危葉只將終委地，焦桐誰料却爲琴。","蒿萊詎報生成德，犬馬空懷感戀心。","明日還家盈眼血，定應迴首即霑襟。"]', '["自持衡镜採幽沈，此事常闻曠古今。","危葉只將終委地，焦桐誰料却爲琴。","蒿萊詎報生成德，犬马空懷感戀心。","明日還家盈眼血，定應迴首即霑襟。"]', '诗', 'shi', '', NULL, '將歸蜀留獻恩地僕射二首 一 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35cf4d8e-6ecd-49fe-8a3a-d098f9f32bd9', '將歸蜀留獻恩地僕射二首 二', '將归蜀留獻恩地僕射二首 二', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["江上長思狎釣翁，此心難與昨心同。","自承丘壑新恩重，已分煙霞舊隱空。","龍變偶因資巨浪，鳥飛誰肯借高風。","應憐死節無門効，永歎潛懷似轉蓬。"]', '["江上长思狎釣翁，此心难與昨心同。","自承丘壑新恩重，已分煙霞旧隐空。","龙变偶因資巨浪，鸟飞誰肯借高风。","應怜死節無门効，永歎潛懷似轉蓬。"]', '诗', 'shi', '', NULL, '將歸蜀留獻恩地僕射二首 二 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea858a2-2beb-4a9f-945d-d13ae55873bc', '隨州獻李侍御二首 一', '隨州獻李侍御二首 一', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["彩筆曾專造化權，道尊翻向宦途閑。","端居有地唯栽藥，靜坐無時不憶山。","德望舊懸霄漢外，政聲新溢路歧間。","衆知聖主搜賢相，朝夕欲徴黃霸還。"]', '["彩笔曾專造化權，道尊翻向宦途闲。","端居有地唯栽藥，静坐無时不憶山。","德望旧懸霄漢外，政声新溢路歧间。","衆知聖主搜賢相，朝夕欲徴黄霸還。"]', '诗', 'shi', '', NULL, '隨州獻李侍御二首 一 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b182ea-c7d2-4b63-9fe0-1a30ce4b7e8c', '隨州獻李侍御二首 二', '隨州獻李侍御二首 二', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["再刖未甘何處說，但垂雙淚出咸秦。","風塵匹馬來千里，蓬梗全家望一身。","舊隱每懷空竟夕，愁眉不展幾經春。","今朝儻降非常顧，倒屐寧惟有古人。"]', '["再刖未甘何处说，但垂雙泪出咸秦。","风塵匹马来千里，蓬梗全家望一身。","旧隐每懷空竟夕，愁眉不展幾經春。","今朝儻降非常顧，倒屐寧惟有古人。"]', '诗', 'shi', '', NULL, '隨州獻李侍御二首 二 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8d7bec-ed39-4510-b722-72bdb045268c', '虢州獻楊抑卿二首 一', '虢州獻楊抑卿二首 一', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["蓋世英華更有誰，賦成傳寫遍坤維。","名科累中求賢日，苦節高標守郡時。","樓上呌雲秋鼓角，林間宿鶴夜旌旗。","徵歸詔下應非久，德望人情在鳳池。"]', '["蓋世英华更有誰，賦成傳寫遍坤維。","名科累中求賢日，苦節高標守郡时。","楼上呌云秋鼓角，林间宿鹤夜旌旗。","徵归詔下應非久，德望人情在鳳池。"]', '诗', 'shi', '', NULL, '虢州獻楊抑卿二首 一 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37df6bb-80b8-4100-96fb-bb5e97473b1d', '虢州獻楊抑卿二首 二', '虢州獻楊抑卿二首 二', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["碧山曾共惜分陰，暗學相如賦上林。","到此敢逾千里恨，歸家且遂十年心。","疎愚祗怯膺門險，淺薄爭窺孔室深。"]', '["碧山曾共惜分陰，暗学相如賦上林。","到此敢逾千里恨，归家且遂十年心。","疎愚祗怯膺门險，淺薄爭窺孔室深。"]', '诗', 'shi', '', NULL, '虢州獻楊抑卿二首 二 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9533027b-3b0d-43ad-adbb-d79e3d998136', '贈邊將', '贈邊將', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["三邊近日往來通，盡是將軍鎮撫功。","兵統萬人爲上將，威加千里懾西戎。","清笳遶塞吹寒月，紅斾當山肅曉風。","却恨北荒霑雨露，無因掃盡虜庭空。"]', '["三邊近日往来通，尽是將軍鎮撫功。","兵統万人爲上將，威加千里懾西戎。","清笳遶塞吹寒月，紅斾當山肅晓风。","却恨北荒霑雨露，無因掃尽虜庭空。"]', '诗', 'shi', '', NULL, '贈邊將 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b182d19-23c0-49cc-a663-14344b7e22e9', '送費[鍊]師供奉赴上都', '送費[鍊]師供奉赴上都', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["縮地周遊不計程，古今應只有先生。","已同化鶴臨華表，又見驂龍向玉清。","蘿磴靜攀雲共過，雪壇當醮月孤明。","無因相逐朝天帝，空羨煙霞得送迎。"]', '["縮地周游不計程，古今應只有先生。","已同化鹤臨华表，又见驂龙向玉清。","蘿磴静攀云共過，雪壇當醮月孤明。","無因相逐朝天帝，空羨煙霞得送迎。"]', '诗', 'shi', '', NULL, '送費[鍊]師供奉赴上都 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8ac12d-7aee-40e0-842b-1f37e00c53d2', '和徐先輩秋日遊涇州南亭呈三二同年', '和徐先輩秋日游涇州南亭呈三二同年', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["多此歡情泛鷁舟，桂枝同折塞同遊。","聲喧島上巢松鶴，影落杯中過水鷗。","送日暮鐘交戍嶺，呌雲寒角動城樓。","酒酣笑語秋風裏，誰道槐花更起愁。"]', '["多此歡情泛鷁舟，桂枝同折塞同游。","声喧島上巢松鹤，影落杯中過水鷗。","送日暮鐘交戍嶺，呌云寒角动城楼。","酒酣笑語秋风裏，誰道槐花更起愁。"]', '诗', 'shi', '', NULL, '和徐先輩秋日遊涇州南亭呈三二同年 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd6f483-2ffd-45c3-b25a-f1f50aef5bf9', '送黃頗歸袁', '送黄頗归袁', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["莫倦連期在醉鄉，孔門多戀惜分行。","文章聲價從來重，霄漢途程此去長。","何處聽猨臨萬壑，幾宿因月滯三湘。","鑪峰若上應相憶，不得同過惠遠房。"]', '["莫倦連期在醉乡，孔门多戀惜分行。","文章声價從来重，霄漢途程此去长。","何处听猨臨万壑，幾宿因月滯三湘。","鑪峰若上應相憶，不得同過惠远房。"]', '诗', 'shi', '', NULL, '送黃頗歸袁 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('613c1144-f6d1-4030-b3be-2cf0ac060ae1', '和陝州參軍李通微首夏書懷呈同寮張裳段羣二先輩', '和陝州參軍李通微首夏书懷呈同寮張裳段羣二先輩', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["公門何事更相牽，邵伯優賢任養閑。","滿院落花從覆地，半簷初日未開關。","尋仙鄭谷煙霞裏，避暑柯亭樹石間。","獨爲高懷誰和繼，掾曹同處桂同攀。"]', '["公门何事更相牽，邵伯優賢任養闲。","满院落花從覆地，半簷初日未开关。","尋仙鄭谷煙霞裏，避暑柯亭樹石间。","独爲高懷誰和繼，掾曹同处桂同攀。"]', '诗', 'shi', '', NULL, '和陝州參軍李通微首夏書懷呈同寮張裳段羣二先輩 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29cc3989-63f7-48c0-af2d-f1494809de6f', '玉真觀尋趙尊師不遇', '玉真观尋趙尊師不遇', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["羽客朝元晝掩扉，林中一徑雪中微。","松陰遶院鶴相對，山色滿樓人未歸。","盡日獨思風馭返，寥天幾望野雲飛。","凭高目斷無消息，自醉自吟愁落暉。"]', '["羽客朝元晝掩扉，林中一徑雪中微。","松陰遶院鹤相对，山色满楼人未归。","尽日独思风馭返，寥天幾望野云飞。","凭高目斷無消息，自醉自吟愁落暉。"]', '诗', 'shi', '', NULL, '玉真觀尋趙尊師不遇 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3398d6f2-5628-409b-925e-d590d76ae703', '及第後上主司王起', '及第後上主司王起', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["三年竭力向春闈，塞斷浮華衆路岐。","盛選棟梁非昔日，平均雨露及明時。","登龍舊美無邪徑，折桂新榮盡直枝。","莫道只陪金馬貴，相期更在鳳皇池。"]', '["三年竭力向春闈，塞斷浮华衆路岐。","盛選棟梁非昔日，平均雨露及明时。","登龙旧美無邪徑，折桂新榮尽直枝。","莫道只陪金马貴，相期更在鳳皇池。"]', '诗', 'shi', '', NULL, '及第後上主司王起 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f70a421-963d-4afa-bb66-8760f4959ebd', '送賀知章入道', '送賀知章入道', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["若非堯運及垂衣，肯許巢由脫俗機。","太液始同黃鶴下，仙鄉已駕白雲歸。","還披舊褐辭金殿，却捧玄珠向翠微。","羈束慙無仙藥分，隨車空有夢魂飛。"]', '["若非堯運及垂衣，肯許巢由脫俗機。","太液始同黄鹤下，仙乡已駕白云归。","還披旧褐辞金殿，却捧玄珠向翠微。","羈束慙無仙藥分，隨车空有梦魂飞。"]', '诗', 'shi', '', NULL, '送賀知章入道 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca79976d-55e8-40de-a56f-9e31715405bb', '送友人出塞', '送友人出塞', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["帝城春色著寒梅，去恨離懷醉不開。","作別欲將何計免，此行應又隔年回。","入河殘日鵰西盡，卷雪驚蓬馬上來。","有思莫忘清塞學，衆傳君負佐王才。"]', '["帝城春色著寒梅，去恨離懷醉不开。","作別欲將何計免，此行應又隔年回。","入河殘日鵰西尽，卷雪驚蓬马上来。","有思莫忘清塞学，衆傳君負佐王才。"]', '诗', 'shi', '', NULL, '送友人出塞 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ddf027-8dae-4fb9-b08b-b52c49374d70', '送僧歸新羅', '送僧归新羅', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["淼淼萬餘里，扁舟發落暉。","滄溟何歲別，白首此時歸。","寒暑途中變，人煙嶺外稀。","驚天巨鰲鬬，蔽日大鵬飛。","雪入行砂屨，雲生坐石衣。","漢風深習得，休恨本心違。"]', '["淼淼万餘里，扁舟發落暉。","滄溟何歲別，白首此时归。","寒暑途中变，人煙嶺外稀。","驚天巨鰲鬬，蔽日大鵬飞。","雪入行砂屨，云生坐石衣。","漢风深習得，休恨本心違。"]', '诗', 'shi', '', NULL, '送僧歸新羅 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f56d7c61-30f6-408f-bb9e-16866c1b9c54', '奉和秘監從翁夏日陝州河亭晚望', '奉和秘監從翁夏日陝州河亭晚望', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["洪河何處望，一境在孤煙。","極野如藍日，長波似鏡年。","卷簾花影裏，倚檻鶴巢邊。","霞焰侵旌斾，灘聲雜管弦。","鍾微來疊岫，帆遠落遙天。","過客多相指，應疑會水仙。"]', '["洪河何处望，一境在孤煙。","極野如藍日，长波似镜年。","卷簾花影裏，倚檻鹤巢邊。","霞焰侵旌斾，灘声杂管弦。","鍾微来叠岫，帆远落遙天。","過客多相指，應疑會水仙。"]', '诗', 'shi', '', NULL, '奉和秘監從翁夏日陝州河亭晚望 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217e20a4-f217-4632-9c40-8783c5be5eab', '風不鳴條', '风不鳴條', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["吾君理化清，上瑞報時平。","曉吹何曾歇，柔條自不鳴。","花香知暗度，柳動覺潛生。","只見低垂影，那聞擊觸聲。","大王初溥暢，少女正輕盈。","幸遇無私力，幽芳願發榮。"]', '["吾君理化清，上瑞報时平。","晓吹何曾歇，柔條自不鳴。","花香知暗度，柳动覺潛生。","只见低垂影，那闻擊觸声。","大王初溥暢，少女正轻盈。","幸遇無私力，幽芳願發榮。"]', '诗', 'shi', '', NULL, '風不鳴條 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a05d15-81fa-4e16-a387-df81a786aa4c', '書情獻知己', '书情獻知己', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["日日恨何窮，巴雲舊隱空。","一爲棲寓客，二見北歸鴻。","有道期攀桂，無門息轉蓬。","賃居將罄比，乞食與僧同。","花月登臨處，江山悵望中。","衆皆輕病驥，誰肯救焦桐。","坐惜春還至，愁吟夜每終。","谷寒思變律，葉晚怯迴風。","謁蔡慙王粲，憐衡冀孔融。"]', '["日日恨何窮，巴云旧隐空。","一爲棲寓客，二见北归鴻。","有道期攀桂，無门息轉蓬。","賃居將罄比，乞食與僧同。","花月登臨处，江山悵望中。","衆皆轻病驥，誰肯救焦桐。","坐惜春還至，愁吟夜每終。","谷寒思变律，葉晚怯迴风。","謁蔡慙王粲，怜衡冀孔融。"]', '诗', 'shi', '', NULL, '書情獻知己 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b45aa1b-9537-4358-8fa5-0b21e1845559', '和工部楊尚書重送絕句', '和工部楊尚书重送絕句', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["桂枝攀得獻庭闈，何似空懷楚橘歸。","好控扶搖早迴首，人人思看大鵬飛。"]', '["桂枝攀得獻庭闈，何似空懷楚橘归。","好控扶搖早迴首，人人思看大鵬飞。"]', '诗', 'shi', '', NULL, '和工部楊尚書重送絕句 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656e060a-c7c2-478f-9feb-8a31896b2d08', '寄石橋僧', '寄石橋僧', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["逢師入山日，道在石橋邊。","別後何人見，秋來幾處禪。","溪中雲隔寺，夜半雪添泉。","生有天台約，知無却出緣。"]', '["逢師入山日，道在石橋邊。","別後何人见，秋来幾处禪。","溪中云隔寺，夜半雪添泉。","生有天台約，知無却出緣。"]', '诗', 'shi', '', NULL, '寄石橋僧 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6f8831f-8a6e-489a-b3c5-7a47faaaa98b', '送歐陽衮歸閩中', '送歐陽衮归閩中', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["秦城幾年住，猶著故鄉衣。","失意時相識，成名後獨歸。","海秋蠻樹黑，嶺夜瘴禽飛。","爲學心難滿，知君更掩扉。"]', '["秦城幾年住，猶著故乡衣。","失意时相識，成名後独归。","海秋蠻樹黑，嶺夜瘴禽飞。","爲学心难满，知君更掩扉。"]', '诗', 'shi', '', NULL, '送歐陽衮歸閩中 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c4668b-11ba-49d3-8500-cccc2a2f6fc1', '古觀', '古观', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["置觀碑已折，看松年不分。","洞中誰識藥，門外日添墳。","放去龜隨水，呼來鹿怕薰。","壇邊見灰火，幾燒祭星文。"]', '["置观碑已折，看松年不分。","洞中誰識藥，门外日添墳。","放去龟隨水，呼来鹿怕薰。","壇邊见灰火，幾燒祭星文。"]', '诗', 'shi', '', NULL, '古觀 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3945113d-2603-4c26-8739-050a676f2868', '題令狐處士谿居', '題令狐处士谿居', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["白髮已過半，無心離此溪。","病嘗山藥徧，貧起草堂低。","爲月窗從破，因詩壁重泥。","近來常夜坐，寂莫與僧齊。"]', '["白髮已過半，無心離此溪。","病嘗山藥徧，貧起草堂低。","爲月窗從破，因诗壁重泥。","近来常夜坐，寂莫與僧齊。"]', '诗', 'shi', '', NULL, '題令狐處士谿居 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806a80d2-a6d3-4180-bf07-e2560c3ae1b5', '送僧歸南嶽', '送僧归南嶽', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["心知衡嶽路，不怕去人稀。","船裏誰鳴磬，沙頭自曝衣。","有家從小別，是寺即言歸。","料得逢春住，當禪雲滿扉。"]', '["心知衡嶽路，不怕去人稀。","船裏誰鳴磬，沙头自曝衣。","有家從小別，是寺即言归。","料得逢春住，當禪云满扉。"]', '诗', 'shi', '', NULL, '送僧歸南嶽 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6147f80e-6161-4a16-aa92-27210e6d856b', '寧州春思', '寧州春思', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["失意離城早，邊城任見花。","初爲斷酒客，舊識賣書家。","寒寺稀無雪，春風亦有沙。","思歸頻入夢，即路不言賒。"]', '["失意離城早，邊城任见花。","初爲斷酒客，旧識賣书家。","寒寺稀無雪，春风亦有沙。","思归頻入梦，即路不言賒。"]', '诗', 'shi', '', NULL, '寧州春思 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968139f4-44e2-401d-b6fb-198b2e829282', '山友贈蘚花冠', '山友贈蘚花冠', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["塵汙出華髮，慙君青蘚冠。","此身閑未得，終日戴應難。","好就松陰挂，宜當枕石看。","會須尋道士，簪去繞霜壇。"]', '["塵汙出华髮，慙君青蘚冠。","此身闲未得，終日戴應难。","好就松陰挂，宜當枕石看。","會須尋道士，簪去繞霜壇。"]', '诗', 'shi', '', NULL, '山友贈蘚花冠 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad81bb9-42e7-4771-8c49-3be1f721acce', '蠻家', '蠻家', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["領得賣珠錢，還歸銅柱邊。","看兒調小象，打鼓試新船。","醉後眠神樹，耕時語瘴煙。","不逢寒便老，相問莫知年。"]', '["領得賣珠錢，還归銅柱邊。","看兒調小象，打鼓試新船。","醉後眠神樹，耕时語瘴煙。","不逢寒便老，相问莫知年。"]', '诗', 'shi', '', NULL, '蠻家 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ee6f2a-01cc-44e1-a732-3a68788368bd', '早春題湖上顧氏新居二首 一', '早春題湖上顧氏新居二首 一', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["近得水雲看，門長侵早開。","到時微有雪，行處又無苔。","勸酒客初醉，留茶僧未來。","每逢晴暖日，唯見乞花栽。"]', '["近得水云看，门长侵早开。","到时微有雪，行处又無苔。","勸酒客初醉，留茶僧未来。","每逢晴暖日，唯见乞花栽。"]', '诗', 'shi', '', NULL, '早春題湖上顧氏新居二首 一 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0b2bf4-6e70-465f-899a-388237378795', '早春題湖上顧氏新居二首 二', '早春題湖上顧氏新居二首 二', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["門不當官道，行人到亦稀。","故從餐後出，方至夜深歸。","開篋揀書卷，掃牀移褐衣。","幾時同買宅，相近有柴扉。"]', '["门不當官道，行人到亦稀。","故從餐後出，方至夜深归。","开篋揀书卷，掃牀移褐衣。","幾时同買宅，相近有柴扉。"]', '诗', 'shi', '', NULL, '早春題湖上顧氏新居二首 二 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fe5fbba-4fe0-4e93-8151-ab491b885164', '蒼梧雲氣', '蒼梧云氣', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["何年化作愁，漠漠便難收。","數點山能遠，平鋪水不流。","濕連湘竹暮，濃蓋舜墳秋。","亦有思歸客，看來盡白頭。"]', '["何年化作愁，漠漠便难收。","數点山能远，平鋪水不流。","濕連湘竹暮，濃蓋舜墳秋。","亦有思归客，看来尽白头。"]', '诗', 'shi', '', NULL, '蒼梧雲氣 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17299dfe-e9be-43d4-a1f8-684d03c32655', '晚春花', '晚春花', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["陰洞日光薄，花開不及時。","當春無半樹，經燒足空枝。","疎與香風會，細將泉影移。","此中人到少，開盡幾人知。"]', '["陰洞日光薄，花开不及时。","當春無半樹，經燒足空枝。","疎與香风會，細將泉影移。","此中人到少，开尽幾人知。"]', '诗', 'shi', '', NULL, '晚春花 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9ac9e3-f35f-44fb-a5ba-dced5b585227', '宿胡氏溪亭', '宿胡氏溪亭', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["獨住水聲裏，有亭無熱時。","客來因月宿，牀勢向山移。","鶴睡松枝定，螢歸葛葉垂。","寂寥猶欠伴，誰爲報僧知。"]', '["独住水声裏，有亭無熱时。","客来因月宿，牀勢向山移。","鹤睡松枝定，螢归葛葉垂。","寂寥猶欠伴，誰爲報僧知。"]', '诗', 'shi', '', NULL, '宿胡氏溪亭 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc39b9dc-841f-4da9-8ba0-e6c398081166', '送華陰隱者', '送华陰隐者', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["往往到城市，得非徵藥錢。","世人空識面，弟子莫知年。","自說能醫死，相期更學仙。","近來移住處，毛女舊峰前。"]', '["往往到城市，得非徵藥錢。","世人空識面，弟子莫知年。","自说能醫死，相期更学仙。","近来移住处，毛女旧峰前。"]', '诗', 'shi', '', NULL, '送華陰隱者 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c820c6a4-d11c-445d-bc22-968fb8905c74', '落第後寄江南親友', '落第後寄江南親友', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["古巷槐陰合，愁多晝掩扉。","獨存過江馬，強拂看花衣。","送客心先醉，尋僧夜不歸。","龍鍾易惆悵，莫遣寄書稀。"]', '["古巷槐陰合，愁多晝掩扉。","独存過江马，強拂看花衣。","送客心先醉，尋僧夜不归。","龙鍾易惆悵，莫遣寄书稀。"]', '诗', 'shi', '', NULL, '落第後寄江南親友 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4849d122-5a12-4463-a2db-1c94f034f23f', '欲別', '欲別', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["花時人欲別，每日醉櫻桃。","買酒金錢盡，彈箏玉指勞。","歸期無歲月，客路有風濤。","錦緞裁衣贈，麒麟落剪刀。"]', '["花时人欲別，每日醉櫻桃。","買酒金錢尽，彈箏玉指勞。","归期無歲月，客路有风濤。","錦緞裁衣贈，麒麟落剪刀。"]', '诗', 'shi', '', NULL, '欲別 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6735c6-9657-4687-9915-4fdd497df3f2', '留別張水部籍', '留別張水部籍', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["省中重拜別，兼領寄人書。","已念此行遠，不應相問疎。","子城西並宅，御水北同渠。","要取春前到，乘閑候起居。"]', '["省中重拜別，兼領寄人书。","已念此行远，不應相问疎。","子城西並宅，御水北同渠。","要取春前到，乘闲候起居。"]', '诗', 'shi', '', NULL, '留別張水部籍 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56cb0805-f673-4961-a7ed-e2ca4dedefc8', '小古鏡', '小古镜', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["字已無人識，唯應記鑄年。","見來深似水，攜去重於錢。","鸞翅巢空月，菱花徧小天。","宮中照黃帝，曾得化爲仙。"]', '["字已無人識，唯應記鑄年。","见来深似水，携去重於錢。","鸾翅巢空月，菱花徧小天。","宮中照黄帝，曾得化爲仙。"]', '诗', 'shi', '', NULL, '小古鏡 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97efefd9-0a91-4d13-9fd8-8910edf544fd', '題太白山隱者', '題太白山隐者', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["高居在幽嶺，人得見時稀。","寫籙扃虛白，尋僧到翠微。","掃壇星下宿，收藥雨中歸。","從服小還後，自疑身解飛。"]', '["高居在幽嶺，人得见时稀。","寫籙扃虛白，尋僧到翠微。","掃壇星下宿，收藥雨中归。","從服小還後，自疑身解飞。"]', '诗', 'shi', '', NULL, '題太白山隱者 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10abbf2-121a-4f19-9997-ede071aa3c04', '病中懷王展先輩在天台', '病中懷王展先輩在天台', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["枕上用心靜，唯應改舊詩。","強行休去早，暫臥起還遲。","因說來歸處，却愁初病時。","赤城山下寺，無計得相隨。"]', '["枕上用心静，唯應改旧诗。","強行休去早，暫臥起還遲。","因说来归处，却愁初病时。","赤城山下寺，無計得相隨。"]', '诗', 'shi', '', NULL, '病中懷王展先輩在天台 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925eb6e7-50a8-4683-8f76-155d993df2a2', '鯉魚', '鯉鱼', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["似龍鱗又足，只是欠登門。","月裏腮猶濕，泥中目未昏。","乞鋤防蟻穴，望水寫金盆。","他日能爲雨，公田報此恩。"]', '["似龙鱗又足，只是欠登门。","月裏腮猶濕，泥中目未昏。","乞鋤防蟻穴，望水寫金盆。","他日能爲雨，公田報此恩。"]', '诗', 'shi', '', NULL, '鯉魚 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2a40ff-c1c2-47e8-9d2c-91e3a50fd579', '子規', '子規', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["遊魂自相叫，寧復記前身。","飛過人家月，聲連客路春。","夢邊催曉急，愁外送風頻。","自有霑花血，相和淚滴新。"]', '["游魂自相叫，寧复記前身。","飞過人家月，声連客路春。","梦邊催晓急，愁外送风頻。","自有霑花血，相和泪滴新。"]', '诗', 'shi', '', NULL, '子規 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7ebb74-8bcf-4235-8215-e93ad75a9a85', '邊州客舍', '邊州客舍', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["開門不成出，麥色徧前坡。","自小詩名在，如今白髮多。","經年無越信，終日厭蕃歌。","近寺居僧少，春來亦嬾過。"]', '["开门不成出，麦色徧前坡。","自小诗名在，如今白髮多。","經年無越信，終日厭蕃歌。","近寺居僧少，春来亦嬾過。"]', '诗', 'shi', '', NULL, '邊州客舍 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3c63ce-c129-4339-b35b-9f58b7f68b8c', '贈道者', '贈道者', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["晏來知養氣，度日語時稀。","到處留丹井，終寒不絮衣。","病鄉多惠藥，鬼俗有符威。","自說身輕健，今年數夢飛。"]', '["晏来知養氣，度日語时稀。","到处留丹井，終寒不絮衣。","病乡多惠藥，鬼俗有符威。","自说身轻健，今年數梦飞。"]', '诗', 'shi', '', NULL, '贈道者 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b58924-a27b-449a-b0fd-9f224646c2e5', '邊游', '邊游', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["古鎮門前去，長安路在東。","天寒明堠火，日晚裂旗風。","塞館皆無事，儒裝亦有弓。","防秋故鄉卒，暫喜語音同。"]', '["古鎮门前去，长安路在东。","天寒明堠火，日晚裂旗风。","塞館皆無事，儒裝亦有弓。","防秋故乡卒，暫喜語音同。"]', '诗', 'shi', '', NULL, '邊游 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33fa5fe-7bf9-45dd-95a9-9fcc4b795901', '夜泊淮陰', '夜泊淮陰', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["夜入楚家煙，煙中人未眠。","望來淮岸盡，坐到酒樓前。","燈影半臨水，箏聲多在船。","乘流向東去，別此易經年。"]', '["夜入楚家煙，煙中人未眠。","望来淮岸尽，坐到酒楼前。","灯影半臨水，箏声多在船。","乘流向东去，別此易經年。"]', '诗', 'shi', '', NULL, '夜泊淮陰 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8770c779-b6e0-48fe-9e82-3f65d75941a5', '遠水', '远水', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["渺渺浸天色，一邊生晚光。","闊浮萍思遠，寒入鴈愁長。","北極連平地，東流即故鄉。","扁舟來宿處，髣髴似瀟湘。"]', '["渺渺浸天色，一邊生晚光。","闊浮萍思远，寒入鴈愁长。","北極連平地，东流即故乡。","扁舟来宿处，髣髴似瀟湘。"]', '诗', 'shi', '', NULL, '遠水 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26955633-a9af-48c8-81ce-12bf7f5848cb', '黃州暮愁', '黄州暮愁', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["凌澌衝淚眼，重疊自西來。","即夜寒應合，非春暖不開。","豈無登陸計，宜棄濟川材。","願寄浮天外，高風萬里回。"]', '["凌澌衝泪眼，重叠自西来。","即夜寒應合，非春暖不开。","豈無登陸計，宜棄濟川材。","願寄浮天外，高风万里回。"]', '诗', 'shi', '', NULL, '黃州暮愁 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc63d2f-5dff-4407-be6b-747a651c4505', '曉發昭應', '晓發昭應', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["行人見雪愁，初作帝鄉游。","旅店開偏早，鄉帆去未收。","燈殘催卷席，手冷怕梳頭。","是物寒無色，湯泉正自流。"]', '["行人见雪愁，初作帝乡游。","旅店开偏早，乡帆去未收。","灯殘催卷席，手冷怕梳头。","是物寒無色，湯泉正自流。"]', '诗', 'shi', '', NULL, '曉發昭應 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4607a7-ce8d-49e6-a479-d76ad43ee0db', '贈金州姚合使君', '贈金州姚合使君', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["爲郎名更重，領郡是蹉跎。","官壁題詩盡，衙庭看鶴多。","城池連草塹，籬落帶椒坡。","未覺旗旛貴，閑行觸處過。"]', '["爲郎名更重，領郡是蹉跎。","官壁題诗尽，衙庭看鹤多。","城池連草塹，籬落带椒坡。","未覺旗旛貴，闲行觸处過。"]', '诗', 'shi', '', NULL, '贈金州姚合使君 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7882ad-97b2-4e10-9380-f4b9631c313b', '送殷中丞遊邊', '送殷中丞游邊', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["話別無長夜，燈前聞曙鵶。","已行難避雪，何處合逢花？","野寺門多閉，羌樓酒不賒。","還須見邊將，誰擬靜塵沙。"]', '["話別無长夜，灯前闻曙鵶。","已行难避雪，何处合逢花？","野寺门多閉，羌楼酒不賒。","還須见邊將，誰擬静塵沙。"]', '诗', 'shi', '', NULL, '送殷中丞遊邊 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb3a1fbf-4d7c-4d65-9c10-b3d8096f7fc7', '寄坐夏僧', '寄坐夏僧', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["坐夏日偏長，知師在律堂。","多因束帶熱，更憶剃頭涼。","苔色侵經架，松陰到簟牀。","還應鍊詩句，借臥石池傍。"]', '["坐夏日偏长，知師在律堂。","多因束带熱，更憶剃头涼。","苔色侵經架，松陰到簟牀。","還應鍊诗句，借臥石池傍。"]', '诗', 'shi', '', NULL, '寄坐夏僧 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78c85b2e-80de-4b1f-957d-7d36d726e2c8', '寄盧式', '寄盧式', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["到處久南望，未知何日回。","寄書頻到海，得夢忽聞雷。","嶺日當秋暗，蠻花近臘開。","白身居瘴癘，誰不惜君才。"]', '["到处久南望，未知何日回。","寄书頻到海，得梦忽闻雷。","嶺日當秋暗，蠻花近臘开。","白身居瘴癘，誰不惜君才。"]', '诗', 'shi', '', NULL, '寄盧式 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4d1d67-24f7-4e25-8672-5bb1ad607810', '日東病僧', '日东病僧', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["雲水絕歸路，來時風送船。","不言身後事，猶坐病中禪。","深壁藏燈影，空窗出艾煙。","已無鄉土信，起塔寺門前。"]', '["云水絕归路，来时风送船。","不言身後事，猶坐病中禪。","深壁藏灯影，空窗出艾煙。","已無乡土信，起塔寺门前。"]', '诗', 'shi', '', NULL, '日東病僧 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c6730d-21b4-4081-94ce-4db0ed748fa0', '泛溪', '泛溪', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["溪船泛渺瀰，漸覺滅炎輝。","動水花連影，逢人鳥背飛。","深猶見白石，涼好換生衣。","未得多詩句，終須隔宿歸。"]', '["溪船泛渺瀰，漸覺滅炎輝。","动水花連影，逢人鸟背飞。","深猶见白石，涼好換生衣。","未得多诗句，終須隔宿归。"]', '诗', 'shi', '', NULL, '泛溪 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b52e5f8-5d28-4e1d-9314-1af0b70b9cf5', '送顧少府', '送顧少府', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["作尉年猶少，無辭去路賒。","漁舟縣前泊，山吏日高衙。","幽景臨谿寺，秋蟬織杼家。","行程須過越，先醉鏡湖花。"]', '["作尉年猶少，無辞去路賒。","漁舟縣前泊，山吏日高衙。","幽景臨谿寺，秋蟬织杼家。","行程須過越，先醉镜湖花。"]', '诗', 'shi', '', NULL, '送顧少府 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1114d88a-b837-45cc-a628-dcc193976081', '咸陽別李處士', '咸陽別李处士', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["古道自迢迢，咸陽離別橋。","越人聞水處，秦樹帶霜朝。","駐馬言難盡，分程望易遙。","秋前未相見，此意轉蕭條。"]', '["古道自迢迢，咸陽離別橋。","越人闻水处，秦樹带霜朝。","駐马言难尽，分程望易遙。","秋前未相见，此意轉蕭條。"]', '诗', 'shi', '', NULL, '咸陽別李處士 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2385716b-4311-4a91-98f8-2c1cc51f99d7', '寄流人', '寄流人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["毒草不曾枯，長添客健無。","霧開蠻市合，船散海城孤。","象跡頻藏齒，龍涎遠蔽珠。","家人秦地老，泣對日南圖。"]', '["毒草不曾枯，长添客健無。","霧开蠻市合，船散海城孤。","象跡頻藏齒，龙涎远蔽珠。","家人秦地老，泣对日南圖。"]', '诗', 'shi', '', NULL, '寄流人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507228b0-2eb8-475a-afa7-5bbc1dbcda4b', '華頂道者', '华頂道者', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["仙人掌中住，生有上天期。","已廢燒丹處，猶多種杏時。","養龍於淺水，寄鶴在高枝。","得道復無事，相逢盡日棊。"]', '["仙人掌中住，生有上天期。","已廢燒丹处，猶多種杏时。","養龙於淺水，寄鹤在高枝。","得道复無事，相逢尽日棊。"]', '诗', 'shi', '', NULL, '華頂道者 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc964a8-833a-4adf-9adf-d985da800e8c', '酬從叔聽夜泉見寄', '酬從叔听夜泉见寄', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["夢罷更開戶，寒泉聲隔雲。","共誰尋最遠，獨自坐偏聞。","巖際和風滴，溪中泛月分。","豈知當此夜，流念到江濆。"]', '["梦罷更开戶，寒泉声隔云。","共誰尋最远，独自坐偏闻。","巖際和风滴，溪中泛月分。","豈知當此夜，流念到江濆。"]', '诗', 'shi', '', NULL, '酬從叔聽夜泉見寄 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5510573a-ce2d-4938-ae21-bb674098d3d5', '和李用夫栽小松', '和李用夫栽小松', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["移來未換葉，已勝在空山。","靜對心標直，遙吟境助閑。","影侵殘雪際，聲透小窗間。","即聳凌空幹，翛翛豈易攀。"]', '["移来未換葉，已勝在空山。","静对心標直，遙吟境助闲。","影侵殘雪際，声透小窗间。","即聳凌空幹，翛翛豈易攀。"]', '诗', 'shi', '', NULL, '和李用夫栽小松 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b52cce3-491c-4aa1-9cd4-0b1792cbc08f', '哭南流人', '哭南流人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["遙見南來使，江頭哭問君。","臨終時有雪，旅葬處無雲。","官庫空收劒，蠻僧共起墳。","知名人尚少，誰爲錄遺文。"]', '["遙见南来使，江头哭问君。","臨終时有雪，旅葬处無云。","官庫空收劒，蠻僧共起墳。","知名人尚少，誰爲錄遺文。"]', '诗', 'shi', '', NULL, '哭南流人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e23fe8-91c1-46fa-9d60-38262377c348', '經李白墓', '經李白墓', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["夜郎歸未老，醉死此江邊。","葬闕官家禮，詩殘樂府篇。","遊魂應到蜀，小碣豈旌賢。","身沒猶何罪，遺墳野火燃。"]', '["夜郎归未老，醉死此江邊。","葬闕官家禮，诗殘乐府篇。","游魂應到蜀，小碣豈旌賢。","身沒猶何罪，遺墳野火燃。"]', '诗', 'shi', '', NULL, '經李白墓 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91948ae7-8f38-4502-aef0-c2ff582c1307', '春夜樊川竹亭陪諸同年讌', '春夜樊川竹亭陪諸同年讌', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["相知皆是舊，每恨獨遊頻。","幸此同芳夕，寧辭倒醉身。","燈光遙映燭，萼粉暗飄茵。","明月分歸騎，重來更幾春。"]', '["相知皆是旧，每恨独游頻。","幸此同芳夕，寧辞倒醉身。","灯光遙映燭，萼粉暗飄茵。","明月分归騎，重来更幾春。"]', '诗', 'shi', '', NULL, '春夜樊川竹亭陪諸同年讌 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b4f310-d1bb-4568-a9f4-d2ae3a72bb97', '送僧', '送僧', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["靈山巡未徧，不作住持心。","逢寺暫投宿，是山皆獨尋。","有時過靜界，在處想空林。","從小即行脚，出家來至今。"]', '["靈山巡未徧，不作住持心。","逢寺暫投宿，是山皆独尋。","有时過静界，在处想空林。","從小即行脚，出家来至今。"]', '诗', 'shi', '', NULL, '送僧 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c309771b-e84b-4edf-b949-00a2acd530a2', '送蘇處士歸西山', '送蘇处士归西山', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["南遊何所爲，一篋又空歸。","守道安清世，無心換白衣。","深林蟬噪暮，絕頂客來稀。","早晚重相見，論持更及微。"]', '["南游何所爲，一篋又空归。","守道安清世，無心換白衣。","深林蟬噪暮，絕頂客来稀。","早晚重相见，論持更及微。"]', '诗', 'shi', '', NULL, '送蘇處士歸西山 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3b873e-061f-4ed3-877a-8a6f6e743c04', '遊爛柯山', '游爛柯山', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["步步出塵氛，溪山別是春。","壇邊時過鶴，碁處寂無人。","訪古碑多缺，探幽路不真。","翻疑歸去晚，清世累移晨。"]', '["步步出塵氛，溪山別是春。","壇邊时過鹤，碁处寂無人。","訪古碑多缺，探幽路不真。","翻疑归去晚，清世累移晨。"]', '诗', 'shi', '', NULL, '遊爛柯山 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12396b57-e35d-4e9f-bff4-5e36bf5579af', '送友人之永嘉', '送友人之永嘉', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["長貧知不易，去計擬何逃。","相對人愁別，經過幾處勞。","城連沙岫遠，山斷夏雲高。","猶想成詩處，秋燈半照濤。"]', '["长貧知不易，去計擬何逃。","相对人愁別，經過幾处勞。","城連沙岫远，山斷夏云高。","猶想成诗处，秋灯半照濤。"]', '诗', 'shi', '', NULL, '送友人之永嘉 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299e6f45-a91e-4790-ad6c-5472640d6f40', '巴中逢故人', '巴中逢故人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["勞思空積歲，偶會更無由。","以分難相捨，將行且暫留。","路歧何處極，江峽半猨愁。","到此分南北，離懷豈易收。"]', '["勞思空積歲，偶會更無由。","以分难相捨，將行且暫留。","路歧何处極，江峽半猨愁。","到此分南北，離懷豈易收。"]', '诗', 'shi', '', NULL, '巴中逢故人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502399a1-79a3-4cda-9482-ac4052479b0c', '送歸江州友人初下第', '送归江州友人初下第', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["名高不俟召，收採獻君門。","偶屈應緣數，他人盡爲冤。","新春城外路，舊隱水邊村。","歸去無勞久，知君更待論。"]', '["名高不俟召，收採獻君门。","偶屈應緣數，他人尽爲冤。","新春城外路，旧隐水邊村。","归去無勞久，知君更待論。"]', '诗', 'shi', '', NULL, '送歸江州友人初下第 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2af79e-69f3-4aa9-8857-9f25d75d8517', '舜城懷古', '舜城懷古', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["禪禹遜堯聰，巍巍盛此中。","四隅咸啓聖，萬古賴成功。","道德去彌遠，山河勢不窮。","停車一再拜，帝業即今同。"]', '["禪禹遜堯聰，巍巍盛此中。","四隅咸啓聖，万古賴成功。","道德去彌远，山河勢不窮。","停车一再拜，帝業即今同。"]', '诗', 'shi', '', NULL, '舜城懷古 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b4779dc-84b7-41d9-80b9-f7fd0393594f', '送劉道士之成都嚴真觀', '送劉道士之成都嚴真观', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["嚴君名不朽，道出二經中。","歸去精誠懇，還應夢寐通。","池臺鏡定月，松檜雨餘風。","想對靈玄憶，人間戀若空。"]', '["嚴君名不朽，道出二經中。","归去精誠懇，還應梦寐通。","池台镜定月，松檜雨餘风。","想对靈玄憶，人间戀若空。"]', '诗', 'shi', '', NULL, '送劉道士之成都嚴真觀 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2efaf05d-7f64-478a-9f78-788ce38571be', '漢南遇友人', '漢南遇友人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["此身西復東，何計此相逢。","夢盡吳越水，恨深襄漢鐘。","積雲開去路，曙雪疊前峰。","誰即知非舊，憐君忽見容。"]', '["此身西复东，何計此相逢。","梦尽吳越水，恨深襄漢鐘。","積云开去路，曙雪叠前峰。","誰即知非旧，怜君忽见容。"]', '诗', 'shi', '', NULL, '漢南遇友人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861662ba-6bea-4ab0-aee0-c3fc5b7ffa87', '遊頭陀寺上方', '游头陀寺上方', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["高步陟崔嵬，吟閑路惜迴。","寺知何代有，僧見梵天來。","暮靄連沙積，餘霞徧檻開。","更期招靜者，長嘯上南臺。"]', '["高步陟崔嵬，吟闲路惜迴。","寺知何代有，僧见梵天来。","暮靄連沙積，餘霞徧檻开。","更期招静者，长嘯上南台。"]', '诗', 'shi', '', NULL, '遊頭陀寺上方 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64072fd7-4160-4f35-ae20-bb2feafab57d', '送友人遊河東', '送友人游河东', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["停車曉燭前，一語幾潸然。","路去干戈日，鄉遙饑饉年。","湖波晴見鴈，槐驛晚無蟬。","莫縱經時住，東南書信偏。"]', '["停车晓燭前，一語幾潸然。","路去干戈日，乡遙饑饉年。","湖波晴见鴈，槐驛晚無蟬。","莫縱經时住，东南书信偏。"]', '诗', 'shi', '', NULL, '送友人遊河東 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b16e389-f436-4b74-9de0-fd935f949050', '中秋夜懷', '中秋夜懷', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["趨馳早晚休，一歲又殘秋。","若只如今日，何難至白頭。","滄波歸處遠，旅食尚邊愁。","賴見前賢說，窮通不自由。"]', '["趨驰早晚休，一歲又殘秋。","若只如今日，何难至白头。","滄波归处远，旅食尚邊愁。","賴见前賢说，窮通不自由。"]', '诗', 'shi', '', NULL, '中秋夜懷 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601ffbb9-84ed-43a8-8032-2defdabdf700', '寄富春孫路處士', '寄富春孫路处士', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["平生醉與吟，誰是見君心。","上國一歸去，滄江閑至今。","鐘繁秋寺近，峰闊晚濤深。","疎放長如此，何人長得尋。"]', '["平生醉與吟，誰是见君心。","上国一归去，滄江闲至今。","鐘繁秋寺近，峰闊晚濤深。","疎放长如此，何人长得尋。"]', '诗', 'shi', '', NULL, '寄富春孫路處士 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902a9264-d23b-412d-83a9-704718ac5bf5', '送客歸新羅', '送客归新羅', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["君家滄海外，一別見何因。","風土雖知敎，程途自致貧。","浸天波色晚，橫笛鳥行春。","明發千檣下，應無更遠人。"]', '["君家滄海外，一別见何因。","风土雖知敎，程途自致貧。","浸天波色晚，橫笛鸟行春。","明發千檣下，應無更远人。"]', '诗', 'shi', '', NULL, '送客歸新羅 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c54aeaa6-1efe-466c-ab63-67ac67c0dcb5', '杭州江亭留題登眺', '杭州江亭留題登眺', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["處處日馳銷，憑軒夕似朝。","漁翁閑鼓櫂，沙鳥戲迎潮。","樹間津亭密，城連塢寺遙。","因誰報隱者，向此得耕樵。"]', '["处处日驰銷，憑軒夕似朝。","漁翁闲鼓櫂，沙鸟戲迎潮。","樹间津亭密，城連塢寺遙。","因誰報隐者，向此得耕樵。"]', '诗', 'shi', '', NULL, '杭州江亭留題登眺 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6bf1111-0b2a-4a7e-b77a-703fcce54421', '荆州夜與友親相遇', '荆州夜與友親相遇', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["山海兩分歧，停舟偶似期。","別來何限意，相見却無辭。","坐永神凝夢，愁繁鬢欲絲。","趨名易遲晚，此去莫經時。"]', '["山海兩分歧，停舟偶似期。","別来何限意，相见却無辞。","坐永神凝梦，愁繁鬢欲絲。","趨名易遲晚，此去莫經时。"]', '诗', 'shi', '', NULL, '荆州夜與友親相遇 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af79ba0-43f1-4521-b2ef-c0255a662a60', '送友人遊邊', '送友人游邊', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["方春到帝京，有戀有愁幷。","萬里江海思，半年沙塞程。","綠陰斜向驛，殘照遠侵城。","自可資新課，還期振盛名。"]', '["方春到帝京，有戀有愁幷。","万里江海思，半年沙塞程。","綠陰斜向驛，殘照远侵城。","自可資新課，還期振盛名。"]', '诗', 'shi', '', NULL, '送友人遊邊 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb044b6c-7e78-4f73-a96d-b48dc1e88180', '題贈宣州亢拾遺', '題贈宣州亢拾遺', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["傳騎一何催，山門晝未開。","高人終避世，聖主不遺才。","坐次欹臨水，門中獨舉杯。","誰爲旦夕侶，深寺數僧來。"]', '["傳騎一何催，山门晝未开。","高人終避世，聖主不遺才。","坐次欹臨水，门中独舉杯。","誰爲旦夕侶，深寺數僧来。"]', '诗', 'shi', '', NULL, '題贈宣州亢拾遺 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb47d2a-a2ef-4d05-86af-411062a64ce3', '姚氏池亭', '姚氏池亭', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["池館饒嘉致，幽人愜所閑。","篠風能動浪，岸樹不遮山。","嘯檻魚驚後，眠窗鶴語間。","何須說廬阜，深處更躋攀。"]', '["池館饒嘉致，幽人愜所闲。","篠风能动浪，岸樹不遮山。","嘯檻鱼驚後，眠窗鹤語间。","何須说廬阜，深处更躋攀。"]', '诗', 'shi', '', NULL, '姚氏池亭 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6cbfa8-7b51-4e99-b66a-1a4c22ad1905', '送友人之江南', '送友人之江南', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["東南路苦辛，去路見無因。","萬里此相送，故交誰更親。","日浮汀草綠，煙霽海山春。","握手無別贈，爲予書札頻。"]', '["东南路苦辛，去路见無因。","万里此相送，故交誰更親。","日浮汀草綠，煙霽海山春。","握手無別贈，爲予书札頻。"]', '诗', 'shi', '', NULL, '送友人之江南 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf25dbb3-393f-4e20-b695-2b84739ebcc6', '彭蠡湖春望', '彭蠡湖春望', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["湖亭東極望，遠棹不須迴。","遍草新湖落，連天衆鴈來。","蘆洲殘照盡，雲障積煙開。","更想鴟夷子，扁舟安在哉。"]', '["湖亭东極望，远棹不須迴。","遍草新湖落，連天衆鴈来。","蘆洲殘照尽，云障積煙开。","更想鴟夷子，扁舟安在哉。"]', '诗', 'shi', '', NULL, '彭蠡湖春望 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235f0368-5280-4c62-b023-2fbf34feb7ff', '聞友人會裴明府縣樓', '闻友人會裴明府縣楼', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["閑閣雨吹塵，陶家揖上賓。","湖山萬疊翠，門樹一行春。","景遍歸簷燕，歌喧已醉身。","登臨興不足，喜有數來因。"]', '["闲閣雨吹塵，陶家揖上賓。","湖山万叠翠，门樹一行春。","景遍归簷燕，歌喧已醉身。","登臨兴不足，喜有數来因。"]', '诗', 'shi', '', NULL, '聞友人會裴明府縣樓 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390721dd-7011-48fd-872b-0ba53414ea40', '歸家山行', '归家山行', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["獻賦才何拙，經時不恥歸。","能知此意是，甘取衆人非。","遍隴耕無圃，緣溪釣有磯。","此懷難自遣，期在振儒衣。"]', '["獻賦才何拙，經时不恥归。","能知此意是，甘取衆人非。","遍隴耕無圃，緣溪釣有磯。","此懷难自遣，期在振儒衣。"]', '诗', 'shi', '', NULL, '歸家山行 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8aa741-f668-4ba0-93c9-72834ac716e7', '長安書懷呈知己', '长安书懷呈知己', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["江湖歸不易，京邑計長貧。","獨夜有知己，論心無故人。","一燈愁裏夢，九陌病中春。","爲問清平日，無門致出身。"]', '["江湖归不易，京邑計长貧。","独夜有知己，論心無故人。","一灯愁裏梦，九陌病中春。","爲问清平日，無门致出身。"]', '诗', 'shi', '', NULL, '長安書懷呈知己 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83de3039-2230-419f-94dc-45877f46bbe0', '聞蟬', '闻蟬', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["動葉復驚神，聲聲斷續勻。","坐來同聽者，俱是未歸人。","一櫂三湘浪，單車二蜀塵。","傷秋各有日，千可念因循。"]', '["动葉复驚神，声声斷續勻。","坐来同听者，俱是未归人。","一櫂三湘浪，單车二蜀塵。","傷秋各有日，千可念因循。"]', '诗', 'shi', '', NULL, '聞蟬 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50068d17-bdbe-4786-9aca-0f49e6128ea3', '李處土道院南樓', '李处土道院南楼', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["霜晚復秋殘，樓明近遠山。","滿壺邀我醉，一榻爲僧閑。","樹簇孤汀眇，帆欹積浪間。","從容更南望，殊欲外人寰。"]', '["霜晚复秋殘，楼明近远山。","满壺邀我醉，一榻爲僧闲。","樹簇孤汀眇，帆欹積浪间。","從容更南望，殊欲外人寰。"]', '诗', 'shi', '', NULL, '李處土道院南樓 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2bf1b0d-2d78-48d2-a559-c06af9290677', '送顧非熊及第歸茅山', '送顧非熊及第归茅山', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["吟詩三十載，成此一名難。","自有恩門入，全無帝里歡。","湖光愁裏碧，巖景夢中寒。","到後松杉月，何人共曉看。"]', '["吟诗三十載，成此一名难。","自有恩门入，全無帝里歡。","湖光愁裏碧，巖景梦中寒。","到後松杉月，何人共晓看。"]', '诗', 'shi', '', NULL, '送顧非熊及第歸茅山 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('442bbfd9-4716-4663-a397-c07d46173ad5', '春日題李中丞樊川別墅', '春日題李中丞樊川別墅', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["心知受恩地，到此亦裴回。","上路移時立，中軒隔宿來。","川光通沼沚，寺影帶樓臺。","無限成蹊樹，花多向客開。"]', '["心知受恩地，到此亦裴回。","上路移时立，中軒隔宿来。","川光通沼沚，寺影带楼台。","無限成蹊樹，花多向客开。"]', '诗', 'shi', '', NULL, '春日題李中丞樊川別墅 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5cfac6-11fb-48b4-b305-2829e2e13b07', '龍州與韓將軍夜會', '龙州與韓將軍夜會', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["庭綠草纖纖，邊州白露沾。","別歌緣劒起，客淚是愁添。","見月鵲啼樹，避風雲滿簾。","將軍盡尊酒，樓上賦星占。"]', '["庭綠草纖纖，邊州白露沾。","別歌緣劒起，客泪是愁添。","见月鵲啼樹，避风云满簾。","將軍尽尊酒，楼上賦星占。"]', '诗', 'shi', '', NULL, '龍州與韓將軍夜會 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090be84b-e0a2-4df5-9e93-8e4c57a5cec0', '途中逢友人', '途中逢友人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["長大有南北，山川各所之。","相逢孤館夜，共憶少年時。","爛醉百花酒，狂題幾首詩。","來朝又分袂，後會鬢應絲。"]', '["长大有南北，山川各所之。","相逢孤館夜，共憶少年时。","爛醉百花酒，狂題幾首诗。","来朝又分袂，後會鬢應絲。"]', '诗', 'shi', '', NULL, '途中逢友人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1683147a-c311-4559-a028-df40e7550af7', '送友人下第歸襄陽', '送友人下第归襄陽', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["失意已春殘，歸愁與別難。","山分關路細，江遶夜城寒。","草色連晴坂，鼉聲離曉灘。","差池是秋賦，何以暫懷安。"]', '["失意已春殘，归愁與別难。","山分关路細，江遶夜城寒。","草色連晴坂，鼉声離晓灘。","差池是秋賦，何以暫懷安。"]', '诗', 'shi', '', NULL, '送友人下第歸襄陽 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff397716-b8c2-403f-b5a7-35986d16c06f', '宿山寺', '宿山寺', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["栗葉重重覆翠微，黃昏溪上語人稀。","月明古寺客初到，風度閑門僧未歸。","山果經霜多自落，水螢穿竹不停飛。","中宵能得幾時睡，又被鐘聲催著衣。"]', '["栗葉重重覆翠微，黄昏溪上語人稀。","月明古寺客初到，风度闲门僧未归。","山果經霜多自落，水螢穿竹不停飞。","中宵能得幾时睡，又被鐘声催著衣。"]', '诗', 'shi', '', NULL, '宿山寺 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa36a1b-f03c-4ee0-a259-8c349ae36f45', '病鶴', '病鹤', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["青雲有意力猶微，豈料低回得所依。","幸念翅因風雨困，豈敎身陷稻粱肥。","曾遊碧落寧無侶，見有清池不忍飛。","縱使他年引仙駕，主人恩在亦應歸。"]', '["青云有意力猶微，豈料低回得所依。","幸念翅因风雨困，豈敎身陷稻粱肥。","曾游碧落寧無侶，见有清池不忍飞。","縱使他年引仙駕，主人恩在亦應归。"]', '诗', 'shi', '', NULL, '病鶴 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732bc4e3-3bdd-4938-b47a-d2483bb266de', '夢仙', '梦仙', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["昨宵魂夢到仙津，得見蓬山不死人。","雲葉許裁成野服，玉漿敎喫潤愁身。","紅樓近月宜寒水，綠杏搖風占古春。","次第引看行未徧，浮光牽入世間塵。"]', '["昨宵魂梦到仙津，得见蓬山不死人。","云葉許裁成野服，玉漿敎喫潤愁身。","紅楼近月宜寒水，綠杏搖风占古春。","次第引看行未徧，浮光牽入世间塵。"]', '诗', 'shi', '', NULL, '夢仙 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f889e1-3648-4911-aadf-44158e6b2469', '古扇', '古扇', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["昨日裁成奪夏威，忽逢秋節便相違。","寒塵妬盡秦王女，涼殿恩隨漢主妃。","似月舊臨紅粉面，有風休動麝香衣。","千年蕭瑟關人事，莫語當時掩淚歸。"]', '["昨日裁成奪夏威，忽逢秋節便相違。","寒塵妬尽秦王女，涼殿恩隨漢主妃。","似月旧臨紅粉面，有风休动麝香衣。","千年蕭瑟关人事，莫語當时掩泪归。"]', '诗', 'shi', '', NULL, '古扇 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64de9e1f-855a-4c5d-a8f2-867ed06a0f64', '涇州聽張處士彈琴', '涇州听張处士彈琴', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["邊州獨夜正思鄉，君又彈琴在客堂。","髣髴不離燈影外，似聞流水到瀟湘。"]', '["邊州独夜正思乡，君又彈琴在客堂。","髣髴不離灯影外，似闻流水到瀟湘。"]', '诗', 'shi', '', NULL, '涇州聽張處士彈琴 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9821bf-f1e8-4952-92db-4eefbbc51d37', '贈別', '贈別', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["魚在深泉鳥在雲，從來只得影相親。","他時縱有逢君處，應作人間白髮身。"]', '["鱼在深泉鸟在云，從来只得影相親。","他时縱有逢君处，應作人间白髮身。"]', '诗', 'shi', '', NULL, '贈別 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd40b0e7-0e87-47d4-b49b-3869f1b04050', '對鱠', '对鱠', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["行到鱸魚鄉裏時，鱠盤如雪怕風吹。","猶憐醉裏江南路，馬上垂鞭學釣時。"]', '["行到鱸鱼乡裏时，鱠盤如雪怕风吹。","猶怜醉裏江南路，马上垂鞭学釣时。"]', '诗', 'shi', '', NULL, '對鱠 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd11ab77-cdc3-45f4-9cf9-767ea00098d3', '憶朝陽峰前居', '憶朝陽峰前居', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["每憶閑眠處，朝陽最上峰。","溪僧來自遠，林路出無蹤。","敗褐黏苔徧，新題出石重。","霞光侵曙發，嵐翠近秋濃。","健羨機能破，安危道不逢。","雪殘猨到閣，庭午鶴離松。","此地虛爲別，人間久未容。","何時無一事，却去養疎慵。"]', '["每憶闲眠处，朝陽最上峰。","溪僧来自远，林路出無蹤。","敗褐黏苔徧，新題出石重。","霞光侵曙發，嵐翠近秋濃。","健羨機能破，安危道不逢。","雪殘猨到閣，庭午鹤離松。","此地虛爲別，人间久未容。","何时無一事，却去養疎慵。"]', '诗', 'shi', '', NULL, '憶朝陽峰前居 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4042129d-6751-457e-9daf-d4622425ec33', '暮上瞿唐峽', '暮上瞿唐峽', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["自古艱難地，孤舟旦暮程。","獨愁空託命，省已是輕生。","有樹皆相倚，無巖不倒傾。","蛟螭波數怒，鬼怪火潛明。","履道知無負，離心自要驚。","何年面骨肉，細話苦辛行。"]', '["自古艱难地，孤舟旦暮程。","独愁空託命，省已是轻生。","有樹皆相倚，無巖不倒傾。","蛟螭波數怒，鬼怪火潛明。","履道知無負，離心自要驚。","何年面骨肉，細話苦辛行。"]', '诗', 'shi', '', NULL, '暮上瞿唐峽 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04732e49-34a7-4aaa-bff2-28fd510611d4', '和李中丞醉中期王徵君月夜同遊滻水舊居', '和李中丞醉中期王徵君月夜同游滻水旧居', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["醉後情俱遠，難忘素滻間。","照花深處月，當戶舊時山。","事想同清話，歡期一破顏。","風流還愛竹，此夜尚思閑。"]', '["醉後情俱远，难忘素滻间。","照花深处月，當戶旧时山。","事想同清話，歡期一破顏。","风流還愛竹，此夜尚思闲。"]', '诗', 'shi', '', NULL, '和李中丞醉中期王徵君月夜同遊滻水舊居 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6a6ca28-f855-499d-a11d-1dc886025960', '濁水求珠', '濁水求珠', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["靈魄自沉浮，從來任濁流。","願從深處得，不向暗中投。","圓月時堪惜，滄波路可求。","沙尋龍窟遠，泥訪蚌津幽。","是寶終知貴，唯恩且用酬。","如能在公掌，的不負明眸。"]', '["靈魄自沉浮，從来任濁流。","願從深处得，不向暗中投。","圓月时堪惜，滄波路可求。","沙尋龙窟远，泥訪蚌津幽。","是寶終知貴，唯恩且用酬。","如能在公掌，的不負明眸。"]', '诗', 'shi', '', NULL, '濁水求珠 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04c401f-69e1-476d-9e0c-c1d43e32c830', '江村夜泊', '江村夜泊', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["日落江路黑，前村人語稀。","幾家深樹裏，一火夜漁歸。"]', '["日落江路黑，前村人語稀。","幾家深樹裏，一火夜漁归。"]', '诗', 'shi', '', NULL, '江村夜泊 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e21be8-7f59-4b62-a6bd-9d3bace83510', '落第後歸覲喜逢僧再陽', '落第後归覲喜逢僧再陽', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["相逢須強笑，人世別離頻。","去曉長侵月，歸鄉動隔春。","見僧心暫靜，從俗事多屯。","宇宙詩名小，山河客路新。","翠桐猶入爨，青鏡未辭塵。","逸足常思驥，隨羣且退鱗。","宴乖紅杏寺，愁在綠楊津。","羞病難爲藥，開眉嬾顧人。"]', '["相逢須強笑，人世別離頻。","去晓长侵月，归乡动隔春。","见僧心暫静，從俗事多屯。","宇宙诗名小，山河客路新。","翠桐猶入爨，青镜未辞塵。","逸足常思驥，隨羣且退鱗。","宴乖紅杏寺，愁在綠楊津。","羞病难爲藥，开眉嬾顧人。"]', '诗', 'shi', '', NULL, '落第後歸覲喜逢僧再陽 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ff3802-4992-441c-9cff-96cebd964b09', '送越僧元瑞', '送越僧元瑞', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["靜中無伴侶，今亦獨隨緣。","昨夜離空室，焚香淨去船。"]', '["静中無伴侶，今亦独隨緣。","昨夜離空室，焚香淨去船。"]', '诗', 'shi', '', NULL, '送越僧元瑞 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8de168-6e01-4b32-b467-7cf2dfc6eea1', '舊宮人', '旧宮人', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["自出先皇玉殿中，衣裳不更染深紅。","宮釵折盡垂空鬢，內扇穿多減半風。","桃熟亦曾君手賜，酒闌猶候妾歌終。","如今還向城邊住，御水東流意不通。"]', '["自出先皇玉殿中，衣裳不更染深紅。","宮釵折尽垂空鬢，內扇穿多減半风。","桃熟亦曾君手賜，酒闌猶候妾歌終。","如今還向城邊住，御水东流意不通。"]', '诗', 'shi', '', NULL, '舊宮人 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('640ea6c7-e3ad-49b0-90d0-2fb02ab5f3b7', '夢游仙', '梦游仙', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["夢遊飛上天家樓，珠箔當風挂玉鉤。","鸚鵡隔簾呼再拜，水仙移鏡嬾梳頭。","丹霞不是人間曉，碧樹仍逢岫外秋。","將謂便長於此地，雞聲入耳所堪愁。"]', '["梦游飞上天家楼，珠箔當风挂玉鉤。","鸚鵡隔簾呼再拜，水仙移镜嬾梳头。","丹霞不是人间晓，碧樹仍逢岫外秋。","將謂便长於此地，雞声入耳所堪愁。"]', '诗', 'shi', '', NULL, '夢游仙 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce85db9-5233-452c-a542-cb2dfe3b4187', '送宮人入道', '送宮人入道', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["願隨仙女董雙成，王母前頭作伴行。","初戴玉冠多悞拜，欲辭金殿別稱名。","將敲碧落新齋磬，却進昭陽舊賜箏。","旦暮焚香繞壇上，步虛猶作按歌聲。"]', '["願隨仙女董雙成，王母前头作伴行。","初戴玉冠多悞拜，欲辞金殿別稱名。","將敲碧落新斋磬，却進昭陽旧賜箏。","旦暮焚香繞壇上，步虛猶作按歌声。"]', '诗', 'shi', '', NULL, '送宮人入道 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e29cad57-2131-4c70-a665-685a81ce8286', '長安退將', '长安退將', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["塞外衝沙損眼明，歸來養病住秦京。","上高樓閣看星坐，著白衣裳把劒行。","常說老身思鬬將，最悲無力制蕃營。","翠眉紅臉和回鶻，惆悵中原不用兵。"]', '["塞外衝沙損眼明，归来養病住秦京。","上高楼閣看星坐，著白衣裳把劒行。","常说老身思鬬將，最悲無力制蕃營。","翠眉紅臉和回鶻，惆悵中原不用兵。"]', '诗', 'shi', '', NULL, '長安退將 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5b350a-6de2-446f-ae56-942b9ab97465', '遙裝夜', '遙裝夜', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["卷席貧拋壁下牀，且鋪他處對燈光。","欲行千里從今夜，猶惜殘春發故鄉。","蚊蚋已生團扇急，衣裳未了剪刀忙。","誰知更有芙蓉浦，南去令人愁思長。"]', '["卷席貧拋壁下牀，且鋪他处对灯光。","欲行千里從今夜，猶惜殘春發故乡。","蚊蚋已生團扇急，衣裳未了剪刀忙。","誰知更有芙蓉浦，南去令人愁思长。"]', '诗', 'shi', '', NULL, '遙裝夜 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835f8cf3-a6c4-42d1-aa06-84ca834bed4a', '送苗七求職', '送苗七求職', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["相逢未得三回笑，風送離情入剪刀。","客路最能銷日月，夢魂空自畏波濤。","獨眠秋夜琴聲急，未拜軍城劒色高。","去去緣多山與海，鶴身寧肯爲飛勞。"]', '["相逢未得三回笑，风送離情入剪刀。","客路最能銷日月，梦魂空自畏波濤。","独眠秋夜琴声急，未拜軍城劒色高。","去去緣多山與海，鹤身寧肯爲飞勞。"]', '诗', 'shi', '', NULL, '送苗七求職 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae971825-5e3c-4e3a-b9a7-01df4ab7dd31', '山行', '山行', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["青櫪林深亦有人，一渠流水數家分。","山當日午回峰影，草帶泥痕過鹿羣。","蒸茗氣從茅舍出，繰絲聲隔竹籬聞。","行逢賣藥歸來客，不惜相隨入島雲。"]', '["青櫪林深亦有人，一渠流水數家分。","山當日午回峰影，草带泥痕過鹿羣。","蒸茗氣從茅舍出，繰絲声隔竹籬闻。","行逢賣藥归来客，不惜相隨入島云。"]', '诗', 'shi', '', NULL, '山行 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eccfe47-1fb9-4e1f-9040-826c26c57a11', '題永忻寺影堂', '題永忻寺影堂', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["不遇修寺日，無錢入影堂。","故來空禮拜，臨去重添香。","僧得名難近，燈傳火已長。","發心依止後，借住有鄰房。"]', '["不遇修寺日，無錢入影堂。","故来空禮拜，臨去重添香。","僧得名难近，灯傳火已长。","發心依止後，借住有鄰房。"]', '诗', 'shi', '', NULL, '題永忻寺影堂 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6adf15-e83c-419f-85ae-0a274d353d00', '獻令狐相公時相公郊壇行事回', '獻令狐相公时相公郊壇行事回', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["鶚在卿雲冰在壺，代天才業本訏謨。","榮同伊陟傳朱戶，秀比王商入畫圖。","昨夜星辰回劒履，前年風月滿江湖。","不知機務時多暇，還許詩家屬和無。"]', '["鶚在卿云冰在壺，代天才業本訏謨。","榮同伊陟傳朱戶，秀比王商入畫圖。","昨夜星辰回劒履，前年风月满江湖。","不知機務时多暇，還許诗家屬和無。"]', '诗', 'shi', '', NULL, '獻令狐相公時相公郊壇行事回 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e07a5b-1b22-40f9-9594-5dedd335bc3f', '句', '句', '657ade8f-f7a7-4440-9c51-4ceab3ab5142', '唐', '["佳人背江坐，眉際列煙樹。","馬蹄沒青莎，船跡成空波。","春風吹兩意，何意更相值。","更望會稽何處是，沙連竹箭白鷴羣。"]', '["佳人背江坐，眉際列煙樹。","马蹄沒青莎，船跡成空波。","春风吹兩意，何意更相值。","更望會稽何处是，沙連竹箭白鷴羣。"]', '诗', 'shi', '', NULL, '句 項斯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2f5bd6f-76a1-4d3f-b5d7-81d81b6c6190', '校獵曲', '校獵曲', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["楚子畋郊野，布罟籠天涯。","浮雲張作羅，萬草結成罝。","意在絕飛鳥，臂弓腰鏌鎁。","遠將射句踐，次欲誅夫差。","壯志一朝盡，他□□繁華。","當時能獵賢，保國兼保家。"]', '["楚子畋郊野，布罟籠天涯。","浮云張作羅，万草結成罝。","意在絕飞鸟，臂弓腰鏌鎁。","远將射句踐，次欲誅夫差。","壯志一朝尽，他□□繁华。","當时能獵賢，保国兼保家。"]', '诗', 'shi', '', NULL, '校獵曲 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d53571e8-f7e5-4870-9d07-90948ff0eb0b', '蠻家', '蠻家', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["領得賣珠錢，還歸銅柱邊。","看兒調小象，打鼓放新船。","醉後眠神樹，耕時語瘴煙。","又逢衰蹇老，相問莫知年。"]', '["領得賣珠錢，還归銅柱邊。","看兒調小象，打鼓放新船。","醉後眠神樹，耕时語瘴煙。","又逢衰蹇老，相问莫知年。"]', '诗', 'shi', '', NULL, '蠻家 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acb3a7b-8835-4ab5-bdfd-00eae745a8b7', '春思', '春思', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["初日照楊柳，玉樓含翠陰。","啼春獨鳥思，望遠佳人心。","幽怨貯瑤瑟，韶光凝碧林。","所思曾不見，芳草意空深。"]', '["初日照楊柳，玉楼含翠陰。","啼春独鸟思，望远佳人心。","幽怨貯瑤瑟，韶光凝碧林。","所思曾不见，芳草意空深。"]', '诗', 'shi', '', NULL, '春思 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453d179f-84bc-4fa6-af4a-e6f9e52fff4b', '送從叔赴南海幕', '送從叔赴南海幕', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["洞庭秋色起，哀狖更難聞。","身往海邊郡，帆懸天際雲。","炎州羅翠鳥，瘴嶺控蠻軍。","信息來非易，堪悲此路分。"]', '["洞庭秋色起，哀狖更难闻。","身往海邊郡，帆懸天際云。","炎州羅翠鸟，瘴嶺控蠻軍。","信息来非易，堪悲此路分。"]', '诗', 'shi', '', NULL, '送從叔赴南海幕 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47a6094-5e94-4794-b15f-32f21f51a47d', '江行留別', '江行留別', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["吳楚半秋色，渡江逢葦花。","雲侵帆影盡，風逼雁行斜。","返照開嵐翠，寒潮蕩浦沙。","余將何所往，海嶠擬營家。"]', '["吳楚半秋色，渡江逢葦花。","云侵帆影尽，风逼雁行斜。","返照开嵐翠，寒潮蕩浦沙。","余將何所往，海嶠擬營家。"]', '诗', 'shi', '', NULL, '江行留別 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7ad1fe-4b03-4e4a-8b03-c1ae0841c11b', '將別寄友人', '將別寄友人', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["帝鄉歸未得，辛苦事羇遊。","別館一尊酒，客程千里秋。","霜風紅葉寺，夜雨白蘋洲。","長恐此時淚，不禁和恨流。"]', '["帝乡归未得，辛苦事羇游。","別館一尊酒，客程千里秋。","霜风紅葉寺，夜雨白蘋洲。","长恐此时泪，不禁和恨流。"]', '诗', 'shi', '', NULL, '將別寄友人 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f34408-9464-490f-97af-b340c25f444c', '客行', '客行', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["路岐長不盡，客恨杳難通。","蘆荻晚汀雨，柳花南浦風。","亂鐘嘶馬急，殘日半帆紅。","却羨漁樵侶，閑歌落照中。"]', '["路岐长不尽，客恨杳难通。","蘆荻晚汀雨，柳花南浦风。","亂鐘嘶马急，殘日半帆紅。","却羨漁樵侶，闲歌落照中。"]', '诗', 'shi', '', NULL, '客行 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f122f8-e54c-4cb3-a85e-3e6f59e8a21e', '過野叟居', '過野叟居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["野人閑種樹，樹老野人前。","居止白雲內，漁樵滄海邊。","呼兒採山藥，放犢飲溪泉。","自著養生論，無煩憂暮年。"]', '["野人闲種樹，樹老野人前。","居止白云內，漁樵滄海邊。","呼兒採山藥，放犢饮溪泉。","自著養生論，無煩憂暮年。"]', '诗', 'shi', '', NULL, '過野叟居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7af4048-bb6f-486f-bab0-9023e34fa2d2', '答光州王使君', '答光州王使君', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["信來淮上郡，楚岫入秦雲。","自顧爲儒者，何由答使君。","蛻風蟬半失，阻雨鴈頻聞。","欲識平生分，他時別紀勳。"]', '["信来淮上郡，楚岫入秦云。","自顧爲儒者，何由答使君。","蛻风蟬半失，阻雨鴈頻闻。","欲識平生分，他时別紀勳。"]', '诗', 'shi', '', NULL, '答光州王使君 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9e384d-5088-483a-919c-f4f5454affe0', '下第再過崔邵池陽居', '下第再過崔邵池陽居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["豈無故鄉路，路遠未成歸。","關內相知少，海邊來信稀。","離雲空石穴，芳草偃郊扉。","謝子一留宿，此心聊息機。"]', '["豈無故乡路，路远未成归。","关內相知少，海邊来信稀。","離云空石穴，芳草偃郊扉。","謝子一留宿，此心聊息機。"]', '诗', 'shi', '', NULL, '下第再過崔邵池陽居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24b560e1-a417-40f9-a8be-211c6021cecf', '夕次淮口', '夕次淮口', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["天涯秋光盡，木末羣鳥還。","夜久遊子息，月明岐路閑。","風生淮水上，帆落楚雲間。","此意竟誰見，行行非故關。"]', '["天涯秋光尽，木末羣鸟還。","夜久游子息，月明岐路闲。","风生淮水上，帆落楚云间。","此意竟誰见，行行非故关。"]', '诗', 'shi', '', NULL, '夕次淮口 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e33eb70-be70-480a-85c3-6c072697ebde', '落日悵望', '落日悵望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["孤雲與歸鳥，千里片時間。","念我一何滯，辭家久未還。","微陽下喬木，遠色隱秋山。","臨水不敢照，恐驚平昔顏。"]', '["孤云與归鸟，千里片时间。","念我一何滯，辞家久未還。","微陽下喬木，远色隐秋山。","臨水不敢照，恐驚平昔顏。"]', '诗', 'shi', '', NULL, '落日悵望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661348cc-8aa7-480e-8638-4c5604571e19', '早發故山作', '早發故山作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["雲門夾峭石，石路蔭長松。","谷響猨相應，山深水復重。","餐霞人不見，採藥客猶逢。","獨宿靈潭側，時聞岳頂鐘。"]', '["云门夾峭石，石路蔭长松。","谷响猨相應，山深水复重。","餐霞人不见，採藥客猶逢。","独宿靈潭側，时闻岳頂鐘。"]', '诗', 'shi', '', NULL, '早發故山作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065859f2-1939-4142-8755-51c8b7b3d977', '下第別郜扶', '下第別郜扶', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["窮途別故人，京洛泣風塵。","在世即應老，他鄉又欲春。","平生空志學，晚歲拙謀身。","靜話歸休計，唯將海上親。"]', '["窮途別故人，京洛泣风塵。","在世即應老，他乡又欲春。","平生空志学，晚歲拙謀身。","静話归休計，唯將海上親。"]', '诗', 'shi', '', NULL, '下第別郜扶 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4f111b-6ab4-4457-9021-8c216f44ddf7', '寄終南真空禪師', '寄終南真空禪師', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["閑想白雲外，了然清淨僧。","松門山半寺，夜雨佛前燈。","此境可長住，浮生自不能。","一從林下別，瀑布幾成冰。"]', '["闲想白云外，了然清淨僧。","松门山半寺，夜雨佛前灯。","此境可长住，浮生自不能。","一從林下別，瀑布幾成冰。"]', '诗', 'shi', '', NULL, '寄終南真空禪師 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c9a9f7-1393-45dd-a112-4e508ca991f1', '長安寓居寄贈賈島', '长安寓居寄贈賈島', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["歲暮見華髮，平生志半空。","孤雲不我棄，歸隱與誰同。","枉道紫宸謁，妨栽丹桂叢。","何如隨野鹿，棲止石巖中。"]', '["歲暮见华髮，平生志半空。","孤云不我棄，归隐與誰同。","枉道紫宸謁，妨栽丹桂叢。","何如隨野鹿，棲止石巖中。"]', '诗', 'shi', '', NULL, '長安寓居寄贈賈島 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ecaa7b-6657-4be0-9b30-9188b5101bc0', '秋郊夕望', '秋郊夕望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["度鳥向棲急，陰蟲逢夜多。","餘霞媚秋漢，迥月濯滄波。","蔓草將萎絕，流年其奈何。","耿然搖落思，獨酌不成歌。"]', '["度鸟向棲急，陰蟲逢夜多。","餘霞媚秋漢，迥月濯滄波。","蔓草將萎絕，流年其奈何。","耿然搖落思，独酌不成歌。"]', '诗', 'shi', '', NULL, '秋郊夕望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d76270-8cab-4d68-be4a-24361f28956d', '贈越客', '贈越客', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["故國波濤隔，明時已久留。","獻書雙闕晚，看月五陵秋。","南棹何時返，長江憶共遊。","遙知釣船畔，相望在汀洲。"]', '["故国波濤隔，明时已久留。","獻书雙闕晚，看月五陵秋。","南棹何时返，长江憶共游。","遙知釣船畔，相望在汀洲。"]', '诗', 'shi', '', NULL, '贈越客 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2029bd3-9e7f-4474-b8ac-4467bbd31bc1', '送顧非熊下第歸江南', '送顧非熊下第归江南', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["無成西別秦，返駕江南春。","草際楚田鴈，舟中吳苑人。","殘雲挂絕島，迥樹入通津。","想到長洲日，門前多白蘋。"]', '["無成西別秦，返駕江南春。","草際楚田鴈，舟中吳苑人。","殘云挂絕島，迥樹入通津。","想到长洲日，门前多白蘋。"]', '诗', 'shi', '', NULL, '送顧非熊下第歸江南 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eedeb49c-b0d2-4d96-b93e-9e0bf4a766c1', '汧上勸舊友', '汧上勸旧友', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["斗酒故人同，長歌起北風。","斜陽高壘閉，秋角暮山空。","鴈叫寒流上，螢飛薄霧中。","坐來生白髮，況復久從戎。"]', '["斗酒故人同，长歌起北风。","斜陽高壘閉，秋角暮山空。","鴈叫寒流上，螢飞薄霧中。","坐来生白髮，況复久從戎。"]', '诗', 'shi', '', NULL, '汧上勸舊友 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b765fc21-7f05-4b97-891a-25ffc37d3511', '送狄參軍赴杭州', '送狄參軍赴杭州', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["新官非次受，聖主寵前勳。","關雪發車晚，風濤挂席聞。","海門山疊翠，湖岸郡藏雲。","執簡從公後，髯參豈勝君。"]', '["新官非次受，聖主寵前勳。","关雪發车晚，风濤挂席闻。","海门山叠翠，湖岸郡藏云。","執簡從公後，髯參豈勝君。"]', '诗', 'shi', '', NULL, '送狄參軍赴杭州 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b78cdf-ce0e-4587-9114-f72b16b7cd40', '過故人所遷新居', '過故人所遷新居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金馬詔何晚，茂陵居近修。","客來雲雨散，鳥下梧桐秋。","迥漢銜天闕，遙泉響御溝。","坐看涼月上，爲子一淹留。"]', '["金马詔何晚，茂陵居近修。","客来云雨散，鸟下梧桐秋。","迥漢銜天闕，遙泉响御溝。","坐看涼月上，爲子一淹留。"]', '诗', 'shi', '', NULL, '過故人所遷新居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5697cb42-4a36-43f5-9d62-60253b5d653c', '落照', '落照', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["照曜天山外，飛鴉幾共過。","微紅拂秋漢，片白透長波。","影促寒汀薄，光殘古木多。","金霞與雲氣，散漫復相和。"]', '["照曜天山外，飞鴉幾共過。","微紅拂秋漢，片白透长波。","影促寒汀薄，光殘古木多。","金霞與云氣，散漫复相和。"]', '诗', 'shi', '', NULL, '落照 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85dba45f-3495-4d23-9398-9d6091c63a3c', '宿崔邵池陽別墅', '宿崔邵池陽別墅', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["楊柳色已改，郊原日復低。","煙生寒渚上，霞散亂山西。","待月人相對，驚風鴈不齊。","此心君莫問，舊國去將迷。"]', '["楊柳色已改，郊原日复低。","煙生寒渚上，霞散亂山西。","待月人相对，驚风鴈不齊。","此心君莫问，旧国去將迷。"]', '诗', 'shi', '', NULL, '宿崔邵池陽別墅 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7456691c-636e-46d7-9093-edc778b0a7ea', '楚江懷古三首 一', '楚江懷古三首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["露氣寒光集，微陽下楚丘。","猨啼洞庭樹，人在木蘭舟。","廣澤生明月，蒼山夾亂流。","雲中君不降，竟夕自悲秋。"]', '["露氣寒光集，微陽下楚丘。","猨啼洞庭樹，人在木蘭舟。","廣澤生明月，蒼山夾亂流。","云中君不降，竟夕自悲秋。"]', '诗', 'shi', '', NULL, '楚江懷古三首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14060d28-d860-41d2-9583-27873f1e0ac8', '楚江懷古三首 二', '楚江懷古三首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["驚鳥去無際，寒蛩鳴我傍。","蘆洲生早霧，蘭隰下微霜。","列宿分窮野，空流注大荒。","看山候明月，聊自整雲裝。"]', '["驚鸟去無際，寒蛩鳴我傍。","蘆洲生早霧，蘭隰下微霜。","列宿分窮野，空流注大荒。","看山候明月，聊自整云裝。"]', '诗', 'shi', '', NULL, '楚江懷古三首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c18e0b-fd4a-42b5-a4fa-866ac8d74d54', '楚江懷古三首 三', '楚江懷古三首 三', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["野風吹蕙帶，驟雨滴蘭橈。","屈宋魂冥寞，江山思寂寥。","陰霓侵晚景，海樹入迴潮。","欲折寒芳薦，明神詎可招。"]', '["野风吹蕙带，驟雨滴蘭橈。","屈宋魂冥寞，江山思寂寥。","陰霓侵晚景，海樹入迴潮。","欲折寒芳薦，明神詎可招。"]', '诗', 'shi', '', NULL, '楚江懷古三首 三 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852bd050-0f74-4c5a-93b5-39818ffee6b8', '遠水', '远水', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["蕩漾空沙際，虛明入遠天。","秋光照不極，鳥影去無邊。","勢引長雲斷，波輕片雪連。","汀洲杳難到，萬古覆蒼煙。"]', '["蕩漾空沙際，虛明入远天。","秋光照不極，鸟影去無邊。","勢引长云斷，波轻片雪連。","汀洲杳难到，万古覆蒼煙。"]', '诗', 'shi', '', NULL, '遠水 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bf1f91-98aa-4db7-8c64-2332247d7e3d', '夕發邠寧寄從弟', '夕發邠寧寄從弟', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["半酣走馬別，別後鎖邊城。","日落月未上，鳥棲人獨行。","方馳故國戀，復愴長年情。","入夜不能息，何當閑此生。"]', '["半酣走马別，別後鎖邊城。","日落月未上，鸟棲人独行。","方驰故国戀，复愴长年情。","入夜不能息，何當闲此生。"]', '诗', 'shi', '', NULL, '夕發邠寧寄從弟 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccacc633-6b9d-4ce4-905f-8bcd247b2d4c', '贈別北客', '贈別北客', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["君生遊俠地，感激氣何高。","飲盡玉壺酒，贈留金錯刀。","鴈關飛霰雪，鯨海落雲濤。","決去如征鳥，離心空自勞。"]', '["君生游俠地，感激氣何高。","饮尽玉壺酒，贈留金錯刀。","鴈关飞霰雪，鯨海落云濤。","決去如征鸟，離心空自勞。"]', '诗', 'shi', '', NULL, '贈別北客 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ec62d2-e652-45e4-a44d-d9a5b7266a2e', '夜下湘中', '夜下湘中', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["洞庭人夜別，孤棹下湘中。","露洗寒山遍，波搖楚月空。","密林飛暗狖，廣澤發鳴鴻。","行值揚帆者，江分又不同。"]', '["洞庭人夜別，孤棹下湘中。","露洗寒山遍，波搖楚月空。","密林飞暗狖，廣澤發鳴鴻。","行值揚帆者，江分又不同。"]', '诗', 'shi', '', NULL, '夜下湘中 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76dd45a3-abc7-4553-9279-5c89ecd63a4a', '送呂郎中牧東海郡', '送呂郎中牧东海郡', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["假道經淮泗，檣烏集隼旟。","蕪城沙菼接，波島石林疎。","海鶴空庭下，夷人遠岸居。","山鄉足遺老，佇聽薦賢書。"]', '["假道經淮泗，檣烏集隼旟。","蕪城沙菼接，波島石林疎。","海鹤空庭下，夷人远岸居。","山乡足遺老，佇听薦賢书。"]', '诗', 'shi', '', NULL, '送呂郎中牧東海郡 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf70cef-b268-4021-81e3-904421bc703d', '山行偶作', '山行偶作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["緣危路忽窮，投宿值樵翁。","鳥下山含暝，蟬鳴露滴空。","石門斜月入，雲竇暗泉通。","寂寞生幽思，心疑舊隱同。"]', '["緣危路忽窮，投宿值樵翁。","鸟下山含暝，蟬鳴露滴空。","石门斜月入，云竇暗泉通。","寂寞生幽思，心疑旧隐同。"]', '诗', 'shi', '', NULL, '山行偶作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad24d16d-abc1-4cf1-be80-0cea602bd5df', '巴江夜猨', '巴江夜猨', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["日飲巴江水，還啼巴岸邊。","秋聲巫峽斷，夜影楚雲連。","露滴青楓樹，山空明月天。","誰知泊船者，聽此不能眠。"]', '["日饮巴江水，還啼巴岸邊。","秋声巫峽斷，夜影楚云連。","露滴青楓樹，山空明月天。","誰知泊船者，听此不能眠。"]', '诗', 'shi', '', NULL, '巴江夜猨 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ca3358-9db8-496f-8bd9-b09c8e80f758', '送田使君牧蔡州', '送田使君牧蔡州', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["主意思政理，牧人官不輕。","樹多淮右地，山遠汝南城。","望稼周田隔，登樓楚月生。","懸知蔣亭下，渚鶴伴閑行。"]', '["主意思政理，牧人官不轻。","樹多淮右地，山远汝南城。","望稼周田隔，登楼楚月生。","懸知蔣亭下，渚鹤伴闲行。"]', '诗', 'shi', '', NULL, '送田使君牧蔡州 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a989d3-4a9d-488e-8050-fcee599678e0', '雀臺怨', '雀台怨', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["魏宮歌舞地，蝶戲鳥還鳴。","玉座人難到，銅臺雨滴平。","西陵樹不見，漳浦草空生。","萬恨盡埋此，徒懸千載名。"]', '["魏宮歌舞地，蝶戲鸟還鳴。","玉座人难到，銅台雨滴平。","西陵樹不见，漳浦草空生。","万恨尽埋此，徒懸千載名。"]', '诗', 'shi', '', NULL, '雀臺怨 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bb8811-902f-45ed-bbde-517f8c5a1604', '早發故園', '早發故园', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["語別在中夜，登車離故鄉。","曙鐘寒出岳，殘月迥凝霜。","風柳條多折，沙雲氣盡黃。","行逢海西鴈，零落不成行。"]', '["語別在中夜，登车離故乡。","曙鐘寒出岳，殘月迥凝霜。","风柳條多折，沙云氣尽黄。","行逢海西鴈，零落不成行。"]', '诗', 'shi', '', NULL, '早發故園 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff62c61-f702-4f28-bb22-9c520856f7b1', '贈別江客', '贈別江客', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["湘中有岑穴，君去挂帆過。","露細蒹葭廣，潮迴島嶼多。","汀洲延夕照，楓葉墜寒波。","應使同漁者，生涯許釣歌。"]', '["湘中有岑穴，君去挂帆過。","露細蒹葭廣，潮迴島嶼多。","汀洲延夕照，楓葉墜寒波。","應使同漁者，生涯許釣歌。"]', '诗', 'shi', '', NULL, '贈別江客 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b5f02d-7e7b-460c-bd53-f25b6d12ec4f', '宿翠微寺', '宿翠微寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["處處松陰滿，樵開一逕通。","鳥歸雲壑靜，僧語石樓空。","積翠含微月，遙泉韻細風。","經行心不厭，憶在故山中。"]', '["处处松陰满，樵开一逕通。","鸟归云壑静，僧語石楼空。","積翠含微月，遙泉韻細风。","經行心不厭，憶在故山中。"]', '诗', 'shi', '', NULL, '宿翠微寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806a5f89-fd88-43ea-a54d-3b277fec0e11', '霽後寄白閣僧', '霽後寄白閣僧', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["蒼翠霾高雪，西峯鳥外看。","久披山衲壞，孤坐石牀寒。","盥手水泉滴，燃燈夜燒殘。","終期老雲嶠，煮藥伴中餐。"]', '["蒼翠霾高雪，西峯鸟外看。","久披山衲壞，孤坐石牀寒。","盥手水泉滴，燃灯夜燒殘。","終期老云嶠，煮藥伴中餐。"]', '诗', 'shi', '', NULL, '霽後寄白閣僧 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44880738-1f0a-4992-9999-c31b69fa03b1', '送僧歸金山寺', '送僧归金山寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金陵山色裏，蟬急向秋分。","迥寺橫洲島，歸僧渡水雲。","夕陽依岸盡，清磬隔潮聞。","遙想禪林下，鑪香帶月焚。"]', '["金陵山色裏，蟬急向秋分。","迥寺橫洲島，归僧渡水云。","夕陽依岸尽，清磬隔潮闻。","遙想禪林下，鑪香带月焚。"]', '诗', 'shi', '', NULL, '送僧歸金山寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af77225-ddfd-43f8-9ec8-9851edfdd917', '新秋雨霽宿王處士東郊', '新秋雨霽宿王处士东郊', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["夕陽逢一雨，夜木洗清陰。","露氣竹窗靜，秋光雲月深。","煎嘗靈藥味，話及故山心。","得意兩不寐，微風生玉琴。"]', '["夕陽逢一雨，夜木洗清陰。","露氣竹窗静，秋光云月深。","煎嘗靈藥味，話及故山心。","得意兩不寐，微风生玉琴。"]', '诗', 'shi', '', NULL, '新秋雨霽宿王處士東郊 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac46ba9-d263-4cc8-8ce3-d10e628ae8f7', '關山曲二首 一', '关山曲二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金甲耀兜鍪，黃金拂紫騮。","叛羌旗下戮，陷壁夜中收。","霜霰戎衣月，關河磧氣秋。","箭瘡殊未合，更遣擊蘭州。"]', '["金甲耀兜鍪，黄金拂紫騮。","叛羌旗下戮，陷壁夜中收。","霜霰戎衣月，关河磧氣秋。","箭瘡殊未合，更遣擊蘭州。"]', '诗', 'shi', '', NULL, '關山曲二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d872554a-70da-46eb-9163-3d7c3302574b', '關山曲二首 二', '关山曲二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["火發龍山北，中宵易左賢。","勒兵臨漢水，驚鴈散胡天。","木落防河急，軍孤受敵偏。","猶聞漢皇怒，按劒待開邊。"]', '["火發龙山北，中宵易左賢。","勒兵臨漢水，驚鴈散胡天。","木落防河急，軍孤受敵偏。","猶闻漢皇怒，按劒待开邊。"]', '诗', 'shi', '', NULL, '關山曲二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8598ad58-dc4d-4ad2-8ba5-f8df27723ceb', '塞下曲二首 一', '塞下曲二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["旌旗倒北風，霜霰逐南鴻。","夜救龍城急，朝焚虜帳空。","骨銷金鏃在，鬢改玉關中。","却想羲軒氏，無人尚戰功。"]', '["旌旗倒北风，霜霰逐南鴻。","夜救龙城急，朝焚虜帳空。","骨銷金鏃在，鬢改玉关中。","却想羲軒氏，無人尚戰功。"]', '诗', 'shi', '', NULL, '塞下曲二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc94d1ca-e86f-4766-b699-35a8728ec558', '塞下曲二首 二', '塞下曲二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["廣漠雲凝慘，日斜飛霰生。","燒山搜猛獸，伏道擊迴兵。","風折旗竿曲，沙埋樹杪平。","黃雲飛旦夕，偏奏苦寒聲。"]', '["廣漠云凝慘，日斜飞霰生。","燒山搜猛獸，伏道擊迴兵。","风折旗竿曲，沙埋樹杪平。","黄云飞旦夕，偏奏苦寒声。"]', '诗', 'shi', '', NULL, '塞下曲二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aad4e66-9af4-458c-8126-8f2998deff3c', '廣陵曲', '廣陵曲', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["葱蘢桂樹枝，高繫黃金羈。","葉隱青蛾翠，花飄白玉墀。","上鳴間關鳥，下醉遊俠兒。","煬帝國已破，此中都不知。"]', '["葱蘢桂樹枝，高繫黄金羈。","葉隐青蛾翠，花飄白玉墀。","上鳴间关鸟，下醉游俠兒。","煬帝国已破，此中都不知。"]', '诗', 'shi', '', NULL, '廣陵曲 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ddf9bdd-fa07-4f3c-897e-d6428fb97147', '送人遊蜀', '送人游蜀', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["別離楊柳陌，迢遰蜀門行。","若聽清猨後，應多白髮生。","虹霓侵棧道，風雨雜江聲。","過盡愁人處，煙花是錦城。"]', '["別離楊柳陌，迢遰蜀门行。","若听清猨後，應多白髮生。","虹霓侵棧道，风雨杂江声。","過尽愁人处，煙花是錦城。"]', '诗', 'shi', '', NULL, '送人遊蜀 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deef2684-e928-48a8-8cb7-078c85be5500', '宿無可上人房', '宿無可上人房', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["稀逢息心侶，細話遠山期。","河漢秋深夜，杉梧露滴時。","風傳林磬響，月掩草堂遲。","坐臥禪心在，浮生皆不知。"]', '["稀逢息心侶，細話远山期。","河漢秋深夜，杉梧露滴时。","风傳林磬响，月掩草堂遲。","坐臥禪心在，浮生皆不知。"]', '诗', 'shi', '', NULL, '宿無可上人房 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae2c08a-704a-4475-8b4b-55ed39167cc5', '旅次夏州', '旅次夏州', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["嘶馬發相續，行次夏王臺。","鎖郡雲陰暮，鳴笳燒色來。","霜繁邊上宿，鬢改磧中迴。","悵望胡沙曉，驚蓬朔吹催。"]', '["嘶马發相續，行次夏王台。","鎖郡云陰暮，鳴笳燒色来。","霜繁邊上宿，鬢改磧中迴。","悵望胡沙晓，驚蓬朔吹催。"]', '诗', 'shi', '', NULL, '旅次夏州 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d907ab0-fa98-4704-aa08-7eca8c296e99', '同莊秀才宿鎮星觀', '同莊秀才宿鎮星观', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["的的星河落，霑苔復灑松。","濕光微泛草，石翠澹搖峰。","野觀雲和月，秋城漏間鐘。","知君親此境，九陌少相逢。"]', '["的的星河落，霑苔复灑松。","濕光微泛草，石翠澹搖峰。","野观云和月，秋城漏间鐘。","知君親此境，九陌少相逢。"]', '诗', 'shi', '', NULL, '同莊秀才宿鎮星觀 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26234f56-e269-46e5-bcf0-25b3b422a3dd', '鸛雀樓晴望', '鸛雀楼晴望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["堯女樓西望，人懷太古時。","海波通禹鑿，山木閉虞祠。","鳥道殘虹挂，龍潭返照移。","行雲如可馭，萬里赴心期。"]', '["堯女楼西望，人懷太古时。","海波通禹鑿，山木閉虞祠。","鸟道殘虹挂，龙潭返照移。","行云如可馭，万里赴心期。"]', '诗', 'shi', '', NULL, '鸛雀樓晴望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e634c0e4-9ad6-41e2-abc5-af3b7cff023a', '贈淮南將', '贈淮南將', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["何事淮南將，功高業未成。","風濤辭海郡，雷雨鎮山營。","度磧黃雲起，防秋白髮生。","密機曾制敵，憂國更論兵。","塞色侵旗動，寒光鎖甲明。","自憐心有作，獨立望專征。"]', '["何事淮南將，功高業未成。","风濤辞海郡，雷雨鎮山營。","度磧黄云起，防秋白髮生。","密機曾制敵，憂国更論兵。","塞色侵旗动，寒光鎖甲明。","自怜心有作，独立望專征。"]', '诗', 'shi', '', NULL, '贈淮南將 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2534da75-79ec-4db7-aac5-8d53c77b034c', '寄賈島', '寄賈島', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["海上不同來，關中俱久住。","尋思別山日，老盡經行樹。","志業人未聞，時光鳥空度。","風悲漢苑秋，雨滴秦城暮。","佩玉與鏘金，非親亦非故。","朱顏枉自毀，明代空相遇。","歲晏各能歸，心知舊歧路。"]', '["海上不同来，关中俱久住。","尋思別山日，老尽經行樹。","志業人未闻，时光鸟空度。","风悲漢苑秋，雨滴秦城暮。","佩玉與鏘金，非親亦非故。","朱顏枉自毀，明代空相遇。","歲晏各能归，心知旧歧路。"]', '诗', 'shi', '', NULL, '寄賈島 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d426ea6f-3c1c-4b61-b192-e42e9f8c1fca', '湘川弔舜', '湘川弔舜', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["伊予生好古，弔舜蒼梧間。","白日坐將沒，遊波凝不還。","九疑雲動影，曠野竹成班。","鴈集蒹葭渚，猨啼霧露山。","南風吹早恨，瑤瑟怨長閑。","元化誰能問，天門恨久關。"]', '["伊予生好古，弔舜蒼梧间。","白日坐將沒，游波凝不還。","九疑云动影，曠野竹成班。","鴈集蒹葭渚，猨啼霧露山。","南风吹早恨，瑤瑟怨长闲。","元化誰能问，天门恨久关。"]', '诗', 'shi', '', NULL, '湘川弔舜 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1ea0d2-c758-4407-aa9d-1d64f5d16179', '送僧歸閩中舊寺', '送僧归閩中旧寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["寺隔海山遙，帆前落葉飄。","斷猨通楚塞，驚鷺出蘭橈。","星月浮波島，煙蘿渡石橋。","鐘聲催野飯，秋色落寒潮。","舊社人多老，閑房樹半凋。","空林容病士，歲晚待相招。"]', '["寺隔海山遙，帆前落葉飄。","斷猨通楚塞，驚鷺出蘭橈。","星月浮波島，煙蘿渡石橋。","鐘声催野飯，秋色落寒潮。","旧社人多老，闲房樹半凋。","空林容病士，歲晚待相招。"]', '诗', 'shi', '', NULL, '送僧歸閩中舊寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e9af2a-ed90-4b8a-8fcf-b5fc625e3c37', '寄遠', '寄远', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["坐想親愛遠，行嗟天地闊。","積疹甘毀顏，沈憂更銷骨。","迢迢遊子心，望望歸雲沒。","喬木非故里，高樓共明月。","夜深秋風多，聞鴈來天末。"]', '["坐想親愛远，行嗟天地闊。","積疹甘毀顏，沈憂更銷骨。","迢迢游子心，望望归云沒。","喬木非故里，高楼共明月。","夜深秋风多，闻鴈来天末。"]', '诗', 'shi', '', NULL, '寄遠 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6675ac9-39c0-4304-b969-baac79305652', '經咸陽北原', '經咸陽北原', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["秦山曾共轉，秦雲自舒卷。","古來爭雄圖，到此多不返。","野狖穴孤墳，農人耕廢苑。","川長波又逝，日與歲俱晚。","夜入咸陽中，悲吞不能飯。"]', '["秦山曾共轉，秦云自舒卷。","古来爭雄圖，到此多不返。","野狖穴孤墳，農人耕廢苑。","川长波又逝，日與歲俱晚。","夜入咸陽中，悲吞不能飯。"]', '诗', 'shi', '', NULL, '經咸陽北原 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086e8a34-4c65-42b7-ba57-818cd4eec743', '冬日寄洛中楊少尹', '冬日寄洛中楊少尹', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["黃河岸柳衰，城下渡流澌。","年長從公懶，天寒入府遲。","家山望幾遍，魏闕赴何時。","懷古心誰識，應多謁舜祠。"]', '["黄河岸柳衰，城下渡流澌。","年长從公懶，天寒入府遲。","家山望幾遍，魏闕赴何时。","懷古心誰識，應多謁舜祠。"]', '诗', 'shi', '', NULL, '冬日寄洛中楊少尹 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92609c38-144c-4924-a521-04d872bffc32', '浙江夜宿', '浙江夜宿', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["落帆人更起，露草滿汀洲。","遠狖啼荒嶠，孤螢溺漫流。","積陰開片月，爽氣集高秋。","去去胡爲戀，搴芳時一遊。"]', '["落帆人更起，露草满汀洲。","远狖啼荒嶠，孤螢溺漫流。","積陰开片月，爽氣集高秋。","去去胡爲戀，搴芳时一游。"]', '诗', 'shi', '', NULL, '浙江夜宿 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7455f507-16a8-41a1-bce9-03b1082ccda0', '寄西岳白石僧', '寄西岳白石僧', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["挂錫中峯上，經行踏石梯。","雲房出定後，岳月在池西。","峭壁殘霞照，欹松積雪齊。","年年著山屐，曾得到招提。"]', '["挂錫中峯上，經行踏石梯。","云房出定後，岳月在池西。","峭壁殘霞照，欹松積雪齊。","年年著山屐，曾得到招提。"]', '诗', 'shi', '', NULL, '寄西岳白石僧 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('843f8896-5eb7-41a9-9576-88902fe09012', '同州冬日陪吳常侍閑宴', '同州冬日陪吳常侍闲宴', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["中天白雲散，集客郡齋時。","陶性聊飛爵，看山忽罷碁。","雪花凝始散，木葉脫無遺。","靜理良多暇，招邀愜所思。"]', '["中天白云散，集客郡斋时。","陶性聊飞爵，看山忽罷碁。","雪花凝始散，木葉脫無遺。","静理良多暇，招邀愜所思。"]', '诗', 'shi', '', NULL, '同州冬日陪吳常侍閑宴 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30297498-3d72-4c4f-8bd2-9449f7f36bbb', '答鄜畤友人同宿見示', '答鄜畤友人同宿见示', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["爲客自堪悲，風塵日滿衣。","承明無計入，舊隱但懷歸。","雪積孤城暗，燈殘曉角微。","相逢喜同宿，此地故人稀。"]', '["爲客自堪悲，风塵日满衣。","承明無計入，旧隐但懷归。","雪積孤城暗，灯殘晓角微。","相逢喜同宿，此地故人稀。"]', '诗', 'shi', '', NULL, '答鄜畤友人同宿見示 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae75abb-8776-4845-8e1c-5a931512d0c2', '題僧禪院', '題僧禪院', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["虛室焚香久，禪心悟幾生。","濾泉侵月起，掃徑避蟲行。","樹隔前朝在，苔滋廢渚平。","我來風雨夜，像設一燈明。"]', '["虛室焚香久，禪心悟幾生。","濾泉侵月起，掃徑避蟲行。","樹隔前朝在，苔滋廢渚平。","我来风雨夜，像設一灯明。"]', '诗', 'shi', '', NULL, '題僧禪院 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df661cd7-e2ae-4eb1-ae64-c9ba97f336f8', '懷故山寄賈島', '懷故山寄賈島', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["心偶羨明代，學詩觀國風。","自從來闕下，未勝在山中。","丹桂日應老，白雲居久空。","誰能謝詩去，聊與此生同。"]', '["心偶羨明代，学诗观国风。","自從来闕下，未勝在山中。","丹桂日應老，白云居久空。","誰能謝诗去，聊與此生同。"]', '诗', 'shi', '', NULL, '懷故山寄賈島 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2f04c30-149d-4b2b-bce1-1334adf84739', '灞上秋居', '灞上秋居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["灞原風雨定，晚見鴈行頻。","落葉他鄉樹，寒燈獨夜人。","空園白露滴，孤壁野僧隣。","寄臥郊扉久，何門致此身。"]', '["灞原风雨定，晚见鴈行頻。","落葉他乡樹，寒灯独夜人。","空园白露滴，孤壁野僧隣。","寄臥郊扉久，何门致此身。"]', '诗', 'shi', '', NULL, '灞上秋居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bede7d9c-23e5-419e-8761-f4128f5e8cd3', '寄崇德里居作', '寄崇德里居作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["掃君園林地，澤我清涼襟。","高鳥雲路晚，孤蟬楊柳深。","風微漢宮漏，月迥秦城砧。","光景坐如此，徒懷經濟心。"]', '["掃君园林地，澤我清涼襟。","高鸟云路晚，孤蟬楊柳深。","风微漢宮漏，月迥秦城砧。","光景坐如此，徒懷經濟心。"]', '诗', 'shi', '', NULL, '寄崇德里居作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba193e4c-434a-4057-93d0-00094454e20d', '河梁別', '河梁別', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["河梁送別者，行哭半非親。","此路足征客，胡天多殺人。","金罍照離思，寶瑟凝殘春。","早晚期相見，垂楊凋復新。"]', '["河梁送別者，行哭半非親。","此路足征客，胡天多殺人。","金罍照離思，寶瑟凝殘春。","早晚期相见，垂楊凋复新。"]', '诗', 'shi', '', NULL, '河梁別 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62635725-cef0-4e25-a9ab-3e4ea864f082', '留別定襄盧軍事', '留別定襄盧軍事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["行行與君別，路在鴈門西。","秋色見邊草，軍聲聞戍鼙。","酣歌擊寶劒，躍馬上金堤。","歸去咸陽里，平生志不迷。"]', '["行行與君別，路在鴈门西。","秋色见邊草，軍声闻戍鼙。","酣歌擊寶劒，躍马上金堤。","归去咸陽里，平生志不迷。"]', '诗', 'shi', '', NULL, '留別定襄盧軍事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e56099-81a7-4c9f-a636-4f6e9695a03c', '送杜秀才東遊', '送杜秀才东游', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["羇遊年復長，去日值秋殘。","草出函關白，雲藏野渡寒。","鴻多霜雪重，山廣道途難。","心事何人識，斗牛應數看。"]', '["羇游年复长，去日值秋殘。","草出函关白，云藏野渡寒。","鴻多霜雪重，山廣道途难。","心事何人識，斗牛應數看。"]', '诗', 'shi', '', NULL, '送杜秀才東遊 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61066a0-f58e-4839-9d66-ebc90d9cee92', '懷黃頗', '懷黄頗', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["有客南浮去，平生與我同。","炎州結遙思，芳杜採應空。","秦鴈歸侵月，湘猿戲褭楓。","期君翼明代，未可戀山中。"]', '["有客南浮去，平生與我同。","炎州結遙思，芳杜採應空。","秦鴈归侵月，湘猿戲褭楓。","期君翼明代，未可戀山中。"]', '诗', 'shi', '', NULL, '懷黃頗 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a2486ef-b0b1-4503-a349-f24baf1f4504', '隴上獨望', '隴上独望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["斜日挂邊樹，蕭蕭獨望間。","陰雲藏漢壘，飛火照胡山。","隴首行人絕，河源夕鳥還。","誰爲立勳者，可惜寶刀閑。"]', '["斜日挂邊樹，蕭蕭独望间。","陰云藏漢壘，飞火照胡山。","隴首行人絕，河源夕鸟還。","誰爲立勳者，可惜寶刀闲。"]', '诗', 'shi', '', NULL, '隴上獨望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9c734b-00ef-4d46-b30a-79ff6770c7aa', '長安書懷', '长安书懷', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["岐路今如此，還堪慟哭頻。","關中成久客，海上老諸親。","谷口田應廢，鄉山草又春。","年年銷壯志，空作獻書人。"]', '["岐路今如此，還堪慟哭頻。","关中成久客，海上老諸親。","谷口田應廢，乡山草又春。","年年銷壯志，空作獻书人。"]', '诗', 'shi', '', NULL, '長安書懷 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9202065-0811-4720-87a3-d288cde39cbb', '邯鄲驛樓作', '邯鄲驛楼作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["蕪沒叢臺久，清漳廢御溝。","蟬鳴河外樹，人在驛西樓。","雲燒天中赤，山當日落秋。","近郊經戰後，處處骨成丘。"]', '["蕪沒叢台久，清漳廢御溝。","蟬鳴河外樹，人在驛西楼。","云燒天中赤，山當日落秋。","近郊經戰後，处处骨成丘。"]', '诗', 'shi', '', NULL, '邯鄲驛樓作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a258323a-855d-4b7b-a742-a593f8e9fc0f', '別家後次飛狐西即事', '別家後次飞狐西即事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["遠歸從此別，親愛失天涯。","去國頻迴首，方秋不在家。","鳴蛩聞塞路，冷鴈背龍沙。","西次桑乾曲，洲中見荻花。"]', '["远归從此別，親愛失天涯。","去国頻迴首，方秋不在家。","鳴蛩闻塞路，冷鴈背龙沙。","西次桑乾曲，洲中见荻花。"]', '诗', 'shi', '', NULL, '別家後次飛狐西即事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939b6cc6-63cf-4c88-a5bf-7396fac69fb1', '題青龍寺鏡公房', '題青龙寺镜公房', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["一室意何有，閑門爲我開。","爐香寒自滅，履雪飯初迴。","窗迥孤山入，燈殘片月來。","禪心方此地，不必訪天台。"]', '["一室意何有，闲门爲我开。","爐香寒自滅，履雪飯初迴。","窗迥孤山入，灯殘片月来。","禪心方此地，不必訪天台。"]', '诗', 'shi', '', NULL, '題青龍寺鏡公房 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e88cd12-cf15-4c60-8963-1fa3ea435686', '邊城獨望', '邊城独望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["聊憑危堞望，倍起異鄉情。","霜落蒹葭白，山昏霧露生。","河灘胡鴈下，戎壘漢鼙驚。","獨樹殘秋色，狂歌淚滿纓。"]', '["聊憑危堞望，倍起異乡情。","霜落蒹葭白，山昏霧露生。","河灘胡鴈下，戎壘漢鼙驚。","独樹殘秋色，狂歌泪满纓。"]', '诗', 'shi', '', NULL, '邊城獨望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('279e6dda-6843-424b-a68e-1ad2e59a7797', '江亭贈別', '江亭贈別', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["長亭晚送君，秋色渡江濆。","衰柳風難定，寒濤雪不分。","猨聲離楚峽，帆影入湘雲。","獨泛扁舟夜，山鐘可臥聞。"]', '["长亭晚送君，秋色渡江濆。","衰柳风难定，寒濤雪不分。","猨声離楚峽，帆影入湘云。","独泛扁舟夜，山鐘可臥闻。"]', '诗', 'shi', '', NULL, '江亭贈別 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7794bcc-a10d-44bd-8449-ec3b3c9e85d6', '旅次寄賈島兼簡無可上人', '旅次寄賈島兼簡無可上人', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["相思邊草長，迴望水連空。","鴈過當行次，蟬鳴復客中。","壯年看即改，羸病計多同。","儻宿林中寺，深憑問遠公。"]', '["相思邊草长，迴望水連空。","鴈過當行次，蟬鳴复客中。","壯年看即改，羸病計多同。","儻宿林中寺，深憑问远公。"]', '诗', 'shi', '', NULL, '旅次寄賈島兼簡無可上人 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c9c014-b1ce-489f-b2de-dcee4c988068', '寄剡中友人', '寄剡中友人', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["故人今在剡，秋草意如何。","嶺暮雲霞雜，潮迴島嶼多。","沃洲僧幾訪，天姥客誰過。","歲晚偏相憶，風生隔楚波。"]', '["故人今在剡，秋草意如何。","嶺暮云霞杂，潮迴島嶼多。","沃洲僧幾訪，天姥客誰過。","歲晚偏相憶，风生隔楚波。"]', '诗', 'shi', '', NULL, '寄剡中友人 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('356c72c3-d3f4-47a9-90cc-ae4c49338879', '送國子韋丞', '送国子韋丞', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["臨水獨相送，歸期千里間。","雲迴逢過雨，路轉入連山。","一騎行芳草，新蟬發故關。","遙聆茂陵下，夜啓竹扉閑。"]', '["臨水独相送，归期千里间。","云迴逢過雨，路轉入連山。","一騎行芳草，新蟬發故关。","遙聆茂陵下，夜啓竹扉闲。"]', '诗', 'shi', '', NULL, '送國子韋丞 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda8e5ce-0f45-4baf-bb9f-7804005368b5', '題吳發原南居', '題吳發原南居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["閑居誰厭僻，門掩漢祠前。","山色夏雲映，樹陰幽草連。","晴光分渚曲，綠氣冒原田。","何日遠遊罷，高枝已噪蟬。"]', '["闲居誰厭僻，门掩漢祠前。","山色夏云映，樹陰幽草連。","晴光分渚曲，綠氣冒原田。","何日远游罷，高枝已噪蟬。"]', '诗', 'shi', '', NULL, '題吳發原南居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4562dfc-b136-4ff9-bb53-0488eaab0424', '雒中寒夜姚侍御宅懷賈島', '雒中寒夜姚侍御宅懷賈島', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["夜木動寒色，雒陽城闕深。","如何異鄉思，更抱故人心。","微月關山遠，閑堦霜霰侵。","誰知石門路，待與子同尋。"]', '["夜木动寒色，雒陽城闕深。","如何異乡思，更抱故人心。","微月关山远，闲堦霜霰侵。","誰知石门路，待與子同尋。"]', '诗', 'shi', '', NULL, '雒中寒夜姚侍御宅懷賈島 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d388030f-5bd5-46ee-b93c-b5b997351958', '征婦歎', '征婦歎', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["稚子在我抱，送君登遠道。","稚子今已行，念君上邊城。","蓬根既無定，蓬子焉用生。","但見請防胡，不聞言罷兵。","及老能得歸，少者還長征。"]', '["稚子在我抱，送君登远道。","稚子今已行，念君上邊城。","蓬根既無定，蓬子焉用生。","但见請防胡，不闻言罷兵。","及老能得归，少者還长征。"]', '诗', 'shi', '', NULL, '征婦歎 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1fce4c-ec2a-43db-b972-4f362dab2f6b', '山中寄姚合員外', '山中寄姚合員外', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["朝與城闕別，暮同麋鹿歸。","鳥鳴松觀靜，人過石橋稀。","木葉搖山翠，泉痕入澗扉。","敢招仙署客，暫此拂朝衣。"]', '["朝與城闕別，暮同麋鹿归。","鸟鳴松观静，人過石橋稀。","木葉搖山翠，泉痕入澗扉。","敢招仙署客，暫此拂朝衣。"]', '诗', 'shi', '', NULL, '山中寄姚合員外 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4247d5db-dacb-45f3-b2ef-c7eeb47fedfd', '中秋月', '中秋月', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["陰魄出海上，望之增苦吟。","冷搜驪頷重，寒徹蚌胎深。","皓氣籠諸夏，清光射萬岑。","悠然天地內，皎潔一般心。"]', '["陰魄出海上，望之增苦吟。","冷搜驪頷重，寒徹蚌胎深。","皓氣籠諸夏，清光射万岑。","悠然天地內，皎潔一般心。"]', '诗', 'shi', '', NULL, '中秋月 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfad3ed-9a51-4112-942e-1e84207fdf2c', '下第寄友人', '下第寄友人', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金門君待問，石室我思歸。","聖主尊黃屋，何人薦白衣。","年來御溝柳，贈別雨霏霏。"]', '["金门君待问，石室我思归。","聖主尊黄屋，何人薦白衣。","年来御溝柳，贈別雨霏霏。"]', '诗', 'shi', '', NULL, '下第寄友人 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6179b631-87ba-4a6b-8f1f-a5f5b9b66253', '寄廣州楊參軍', '寄廣州楊參軍', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["南方春景好，念子緩歸心。","身方脫野服，冠未繫朝簪。","足恣平生賞，無虞外役侵。","汀洲觀鳥戲，向月和猨吟。","稅駕楚山廣，揚帆湘水深。","採奇搜石穴，懷勝即楓林。","悵望極霞際，流情墮海陰。","前朝杳難問，歎息灑鳴琴。"]', '["南方春景好，念子緩归心。","身方脫野服，冠未繫朝簪。","足恣平生賞，無虞外役侵。","汀洲观鸟戲，向月和猨吟。","稅駕楚山廣，揚帆湘水深。","採奇搜石穴，懷勝即楓林。","悵望極霞際，流情墮海陰。","前朝杳难问，歎息灑鳴琴。"]', '诗', 'shi', '', NULL, '寄廣州楊參軍 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee559b10-0d79-414b-9900-aec0a51bc417', '離夜二首 一', '離夜二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["東征遼水迥，北近單于臺。","戎衣挂寶劍，玉筯銜金杯。","紅燭暗將滅，翠蛾終不開。"]', '["东征遼水迥，北近單于台。","戎衣挂寶劍，玉筯銜金杯。","紅燭暗將滅，翠蛾終不开。"]', '诗', 'shi', '', NULL, '離夜二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdf690a-332d-4017-8ac3-59c9d42e8cba', '離夜二首 二', '離夜二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["凝夜照離色，恐聞啼晚鴉。","前年營鴈塞，明月戍龍沙。","曾與五陵子，休裝孤劍花。"]', '["凝夜照離色，恐闻啼晚鴉。","前年營鴈塞，明月戍龙沙。","曾與五陵子，休裝孤劍花。"]', '诗', 'shi', '', NULL, '離夜二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b4e2e7-8425-45ce-9f77-0e9673355628', '荅太原從軍楊員外送別', '荅太原從軍楊員外送別', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["君將海月珮，贈之光我行。","見知言不淺，懷報意非輕。","反照臨歧思，中年未達情。","河梁人送別，秋漢鴈相鳴。","衰柳搖邊吹，寒雲冒古城。","西遊還獻賦，應許託平生。"]', '["君將海月珮，贈之光我行。","见知言不淺，懷報意非轻。","反照臨歧思，中年未達情。","河梁人送別，秋漢鴈相鳴。","衰柳搖邊吹，寒云冒古城。","西游還獻賦，應許託平生。"]', '诗', 'shi', '', NULL, '荅太原從軍楊員外送別 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32012d9-fa61-47bf-868c-25128f31aa7c', '送從叔重赴海南從事', '送從叔重赴海南從事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["又從連帥請，還作嶺南行。","窮海何時到，孤帆累月程。","亂蟬吟暮色，哀狖落秋聲。","晚路潮波起，寒葭霧雨生。","沙埋銅柱沒，山簇瘴雲平。","念此別離苦，其如宗從情。"]', '["又從連帥請，還作嶺南行。","窮海何时到，孤帆累月程。","亂蟬吟暮色，哀狖落秋声。","晚路潮波起，寒葭霧雨生。","沙埋銅柱沒，山簇瘴云平。","念此別離苦，其如宗從情。"]', '诗', 'shi', '', NULL, '送從叔重赴海南從事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5806fc77-b49c-404e-aa91-46d6d92b6e74', '送韓校書江西從事', '送韓校书江西從事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["出關寒色盡，雲夢草生新。","鴈背岳陽雨，客行江上春。","遙程隨水闊，枉路倒帆頻。","夕照臨孤館，朝霞發廣津。","湖山潮半隔，郡壁岸斜鄰。","自此鍾陵道，裁書有故人。"]', '["出关寒色尽，云梦草生新。","鴈背岳陽雨，客行江上春。","遙程隨水闊，枉路倒帆頻。","夕照臨孤館，朝霞發廣津。","湖山潮半隔，郡壁岸斜鄰。","自此鍾陵道，裁书有故人。"]', '诗', 'shi', '', NULL, '送韓校書江西從事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26b953b-531d-40fd-9bdc-e5e923b3bf93', '送顧少府之永康', '送顧少府之永康', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["婺女星邊去，春生即有花。","寒關雲復雪，古渡草連沙。","宿次吳江晚，行侵日徼斜。","官傳梅福政，縣顧赤松家。","燒起明山翠，潮迴動海霞。","清高宜閱此，莫歎近天涯。"]', '["婺女星邊去，春生即有花。","寒关云复雪，古渡草連沙。","宿次吳江晚，行侵日徼斜。","官傳梅福政，縣顧赤松家。","燒起明山翠，潮迴动海霞。","清高宜閱此，莫歎近天涯。"]', '诗', 'shi', '', NULL, '送顧少府之永康 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a81fe39-ec68-40ed-984f-f42c648f2070', '幽上留別令狐侍郎', '幽上留別令狐侍郎', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["自別丘中隱，頻年哭路岐。","辛勤今若是，少壯豈多時。","露滴陰蟲苦，秋聲遠客悲。","晚營嚴鼓角，紅葉拂旌旗。","北闕虛延望，西林久見思。","川流寒水急，雲返故山遲。","落照遊人去，長空獨鳥隨。","不堪風景隔，忠信寡相知。"]', '["自別丘中隐，頻年哭路岐。","辛勤今若是，少壯豈多时。","露滴陰蟲苦，秋声远客悲。","晚營嚴鼓角，紅葉拂旌旗。","北闕虛延望，西林久见思。","川流寒水急，云返故山遲。","落照游人去，长空独鸟隨。","不堪风景隔，忠信寡相知。"]', '诗', 'shi', '', NULL, '幽上留別令狐侍郎 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccc2a03-4704-4b2a-86c1-645d3a669a46', '襄陽席上呈于司空', '襄陽席上呈于司空', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["花枝臨水復臨堤，也照清江也照泥。","寄語東君好擡舉，夜來曾伴鳳皇棲。"]', '["花枝臨水复臨堤，也照清江也照泥。","寄語东君好擡舉，夜来曾伴鳳皇棲。"]', '诗', 'shi', '', NULL, '襄陽席上呈于司空 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc8f53e-b4e1-4486-b61e-da66829bcab0', '宿裴氏谿居懷厲玄先輩', '宿裴氏谿居懷厲玄先輩', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["樹下孤石坐，草間微有霜。","同人不同北，雲鳥自南翔。","迢遰夜山色，清泠泉月光。","西風耿離抱，江海遙相望。"]', '["樹下孤石坐，草间微有霜。","同人不同北，云鸟自南翔。","迢遰夜山色，清泠泉月光。","西风耿離抱，江海遙相望。"]', '诗', 'shi', '', NULL, '宿裴氏谿居懷厲玄先輩 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62f2092-d6e9-4a7e-97a4-0baa12311aea', '集宿姚殿中宅期僧無可不至', '集宿姚殿中宅期僧無可不至', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["殿中日相命，開尊話舊時。","餘鐘催鳥絕，積雪阻僧期。","林靜寒光遠，天陰曙色遲。","今夕復何夕，人謁去難追。"]', '["殿中日相命，开尊話旧时。","餘鐘催鸟絕，積雪阻僧期。","林静寒光远，天陰曙色遲。","今夕复何夕，人謁去难追。"]', '诗', 'shi', '', NULL, '集宿姚殿中宅期僧無可不至 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a63f6a41-deed-45ca-821f-8be30d583663', '宿賈島原居', '宿賈島原居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["寒鴈過原急，渚邊秋色深。","煙霞向海島，風雨宿園林。","俱住明時願，同懷故國心。","未能先隱跡，聊此一相尋。"]', '["寒鴈過原急，渚邊秋色深。","煙霞向海島，风雨宿园林。","俱住明时願，同懷故国心。","未能先隐跡，聊此一相尋。"]', '诗', 'shi', '', NULL, '宿賈島原居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53c4ba8-1bdd-4c32-b18b-33bc14cef2fc', '贈別空公', '贈別空公', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["雲門秋却入，微徑久無人。","後夜中峰月，空林百衲身。","寂寥寒磬盡，盥漱瀑泉新。","履跡誰相見，松風掃石塵。"]', '["云门秋却入，微徑久無人。","後夜中峰月，空林百衲身。","寂寥寒磬尽，盥漱瀑泉新。","履跡誰相见，松风掃石塵。"]', '诗', 'shi', '', NULL, '贈別空公 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d6dc34-ddcf-479d-975d-7159a00da2b9', '府試觀開元皇帝東封圖', '府試观开元皇帝东封圖', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["儼若翠華舉，登封圖乍開。","冕旒明主立，冠劍侍臣陪。","跡類飛仙去，光同拜日來。","粉痕疑檢玉，黛色訝生苔。","挂壁雲將起，陵風仗若迴。","何年復東幸，魯叟望悠哉。"]', '["儼若翠华舉，登封圖乍开。","冕旒明主立，冠劍侍臣陪。","跡類飞仙去，光同拜日来。","粉痕疑檢玉，黛色訝生苔。","挂壁云將起，陵风仗若迴。","何年复东幸，魯叟望悠哉。"]', '诗', 'shi', '', NULL, '府試觀開元皇帝東封圖 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ae6b9f-7099-436e-be20-5f4138618b06', '府試水始冰', '府試水始冰', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["南池寒色動，北陸歲陰生。","薄薄流澌聚，灕灕翠瀲平。","暗霑霜稍厚，迴照日還輕。","乳竇懸殘滴，湘流減恨聲。","即堪金井貯，會映玉壺清。","潔白心雖識，空期飲此明。"]', '["南池寒色动，北陸歲陰生。","薄薄流澌聚，灕灕翠瀲平。","暗霑霜稍厚，迴照日還轻。","乳竇懸殘滴，湘流減恨声。","即堪金井貯，會映玉壺清。","潔白心雖識，空期饮此明。"]', '诗', 'shi', '', NULL, '府試水始冰 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c936a0-921f-4f13-9111-74d1a6e3ec3b', '邊館逢賀秀才', '邊館逢賀秀才', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["貧病無疎我與君，不知何事久離羣。","鹿裘共弊同爲客，龍闕將移擬獻文。","空館夕陽鴉繞樹，荒城寒色鴈和雲。","不堪吟斷邊笳曉，葉落東西客又分。"]', '["貧病無疎我與君，不知何事久離羣。","鹿裘共弊同爲客，龙闕將移擬獻文。","空館夕陽鴉繞樹，荒城寒色鴈和云。","不堪吟斷邊笳晓，葉落东西客又分。"]', '诗', 'shi', '', NULL, '邊館逢賀秀才 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d6db57-35ee-4c52-916a-285bcb559547', '宿王屋天壇', '宿王屋天壇', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["星斗半沈蒼翠色，紅霞遠照海濤分。","折松曉拂天壇雪，投簡寒窺玉洞雲。","絕頂醮迴人不見，深林磬度鳥應聞。","未知誰與傳金籙，獨向仙祠拜老君。"]', '["星斗半沈蒼翠色，紅霞远照海濤分。","折松晓拂天壇雪，投簡寒窺玉洞云。","絕頂醮迴人不见，深林磬度鸟應闻。","未知誰與傳金籙，独向仙祠拜老君。"]', '诗', 'shi', '', NULL, '宿王屋天壇 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ac3614-9bbd-4089-8ce3-79ed3046b7ae', '岐陽逢曲陽故人話舊', '岐陽逢曲陽故人話旧', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["異地還相見，平生問可知。","壯年俱欲暮，往事盡堪悲。","道路頻艱阻，親朋久別離。","解兵逃白刃，謁帝值明時。","淹疾生涯故，因官事業移。","雞鳴關月落，鴈度朔風吹。","客淚翻岐下，鄉心落海湄。","積愁何計遣，滿酌浣相思。"]', '["異地還相见，平生问可知。","壯年俱欲暮，往事尽堪悲。","道路頻艱阻，親朋久別離。","解兵逃白刃，謁帝值明时。","淹疾生涯故，因官事業移。","雞鳴关月落，鴈度朔风吹。","客泪翻岐下，乡心落海湄。","積愁何計遣，满酌浣相思。"]', '诗', 'shi', '', NULL, '岐陽逢曲陽故人話舊 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae0a460-1c44-40ff-885a-b26bc78cd4cc', '贈禪僧', '贈禪僧', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["弟子人天遍，童年在沃洲。","開禪山木長，浣衲海沙秋。","振錫搖汀月，持瓶接瀑流。","赤城何日上，鄙願從師遊。"]', '["弟子人天遍，童年在沃洲。","开禪山木长，浣衲海沙秋。","振錫搖汀月，持瓶接瀑流。","赤城何日上，鄙願從師游。"]', '诗', 'shi', '', NULL, '贈禪僧 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f809aab-bb40-410e-b6e2-e29c265d1d96', '題廬山寺', '題廬山寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["白茅爲屋宇編荆，數處堦墀石疊成。","東谷笑言西谷響，下方雲雨上方晴。","鼠驚樵客緣蒼壁，猨戲山頭撼紫檉。","別有一條投澗水，竹筒斜引入茶鐺。"]', '["白茅爲屋宇編荆，數处堦墀石叠成。","东谷笑言西谷响，下方云雨上方晴。","鼠驚樵客緣蒼壁，猨戲山头撼紫檉。","別有一條投澗水，竹筒斜引入茶鐺。"]', '诗', 'shi', '', NULL, '題廬山寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d181bfc0-594e-4fbd-b409-a37f59b16ed9', '題石甕寺', '題石甕寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["僧室並皇宮，雲門輦路同。","渭分雙闕北，山迥五陵東。","修綆懸林表，深泉汲洞中。","人煙窺垤蟻，鴛瓦拂冥鴻。","蘚壁松生峭，龕燈月照空。","稀逢息心侶，獨禮竺乾公。"]', '["僧室並皇宮，云门輦路同。","渭分雙闕北，山迥五陵东。","修綆懸林表，深泉汲洞中。","人煙窺垤蟻，鴛瓦拂冥鴻。","蘚壁松生峭，龕灯月照空。","稀逢息心侶，独禮竺乾公。"]', '诗', 'shi', '', NULL, '題石甕寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b62761-8a49-49bf-bbe9-a57ecf9c5e93', '謁仙觀二首 一', '謁仙观二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["我生求羽化，齋沐造仙居。","葛蔓沒丹井，石函盛道書。","寒松多偃側，靈洞遍清虛。","一就泉西飲，雲中採藥蔬。"]', '["我生求羽化，斋沐造仙居。","葛蔓沒丹井，石函盛道书。","寒松多偃側，靈洞遍清虛。","一就泉西饮，云中採藥蔬。"]', '诗', 'shi', '', NULL, '謁仙觀二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aac20f2-2745-4d74-8010-3b85c5feb87c', '謁仙觀二首 二', '謁仙观二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["山空蕙氣香，乳管折雲房。","願值壺中客，親傳肘後方。","三更禮星斗，寸匕服丹霜。","默坐樹陰下，仙經橫石牀。"]', '["山空蕙氣香，乳管折云房。","願值壺中客，親傳肘後方。","三更禮星斗，寸匕服丹霜。","默坐樹陰下，仙經橫石牀。"]', '诗', 'shi', '', NULL, '謁仙觀二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ecf0c47-b59c-46ea-8360-1402ac4719c8', '送朴山人歸新羅', '送朴山人归新羅', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["浩渺行無極，揚帆但信風。","雲山過海半，鄉樹入舟中。","波定遙天出，沙平遠岸窮。","離心寄何處，目斷曙霞東。"]', '["浩渺行無極，揚帆但信风。","云山過海半，乡樹入舟中。","波定遙天出，沙平远岸窮。","離心寄何处，目斷曙霞东。"]', '诗', 'shi', '', NULL, '送朴山人歸新羅 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca6fcbc-49f0-4230-b3b2-710c35a33b40', '題靜住寺欽用上人房', '題静住寺欽用上人房', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["寺近朝天路，多聞玉珮音。","鑒人開慧眼，歸鳥息禪心。","磬接星河曙，窗連夏木深。","此中能宴坐，何必在雲林。"]', '["寺近朝天路，多闻玉珮音。","鑒人开慧眼，归鸟息禪心。","磬接星河曙，窗連夏木深。","此中能宴坐，何必在云林。"]', '诗', 'shi', '', NULL, '題靜住寺欽用上人房 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6495376c-1138-4097-8fd3-e037bd4db046', '贈楊先輩', '贈楊先輩', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["平生閑放久，野鹿許爲羣。","居止鄰西岳，軒窗度白雲。","齋心飯松子，話道接茅君。","漢主思清淨，休書諫獵文。"]', '["平生闲放久，野鹿許爲羣。","居止鄰西岳，軒窗度白云。","斋心飯松子，話道接茅君。","漢主思清淨，休书諫獵文。"]', '诗', 'shi', '', NULL, '贈楊先輩 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9cd411-987b-44eb-acf1-488bb7d71913', '詶李景章先輩', '詶李景章先輩', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["平生詩句忝多同，不得陪君奉至公。","金鏑自宜先中鵠，鉛刀甘且學雕蟲。","鶯啼細柳臨關路，燕接飛花遶漢宮。","九陌芳菲人競賞，此時心在別離中。"]', '["平生诗句忝多同，不得陪君奉至公。","金鏑自宜先中鵠，鉛刀甘且学雕蟲。","鶯啼細柳臨关路，燕接飞花遶漢宮。","九陌芳菲人競賞，此时心在別離中。"]', '诗', 'shi', '', NULL, '詶李景章先輩 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab77b05-8e8a-49e0-9eca-e04ed814f349', '贈祠部令狐郎中', '贈祠部令狐郎中', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["官初執憲稱雄才，省轉爲郎雅望催。","待制松陰移玉殿，分宵露氣靜天臺。","算棋默向孤雲坐，隨鶴閑窮片水迴。","忽憶十年相識日，小儒新自海邊來。"]', '["官初執憲稱雄才，省轉爲郎雅望催。","待制松陰移玉殿，分宵露氣静天台。","算棋默向孤云坐，隨鹤闲窮片水迴。","忽憶十年相識日，小儒新自海邊来。"]', '诗', 'shi', '', NULL, '贈祠部令狐郎中 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f86a601-d9f1-4d68-a5a7-ec774381689d', '送冊東夷王使', '送冊东夷王使', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["越海傳金冊，華夷禮命行。","片帆秋色動，萬里信潮生。","日映孤舟出，沙連絕島明。","翳空翻大鳥，飛雪灑長鯨。","舊鬢迴應改，遐荒夢易驚。","何當理風檝，天外問來程。"]', '["越海傳金冊，华夷禮命行。","片帆秋色动，万里信潮生。","日映孤舟出，沙連絕島明。","翳空翻大鸟，飞雪灑长鯨。","旧鬢迴應改，遐荒梦易驚。","何當理风檝，天外问来程。"]', '诗', 'shi', '', NULL, '送冊東夷王使 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297cbd21-9366-4641-aa8e-09db9f8340dd', '送武陵王將軍', '送武陵王將軍', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["河外今無事，將軍有戰名。","艱難長劍缺，功業少年成。","曉仗親雲陛，寒宵突禁營。","朱旗身外色，玉漏耳邊聲。","開閤談賓至，調弓過鴈驚。","爲儒多不達，見學請長纓。"]', '["河外今無事，將軍有戰名。","艱难长劍缺，功業少年成。","晓仗親云陛，寒宵突禁營。","朱旗身外色，玉漏耳邊声。","开閤談賓至，調弓過鴈驚。","爲儒多不達，见学請长纓。"]', '诗', 'shi', '', NULL, '送武陵王將軍 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb2071b-98be-48f5-9e1a-27abb9a6c105', '贈鄠縣尉李先輩二首 一', '贈鄠縣尉李先輩二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["同人家鄠杜，相見罷官時。","野坐苔生石，荒居菊入籬。","聽蟬臨水久，送鶴背山遲。","未擬還城闕，溪僧別有期。"]', '["同人家鄠杜，相见罷官时。","野坐苔生石，荒居菊入籬。","听蟬臨水久，送鹤背山遲。","未擬還城闕，溪僧別有期。"]', '诗', 'shi', '', NULL, '贈鄠縣尉李先輩二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d563208-d740-47d5-be78-f8f280fec7d7', '贈鄠縣尉李先輩二首 二', '贈鄠縣尉李先輩二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["休官不到闕，求靜匪營他。","種藥唯愁晚，看雲肯厭多。","渚邊逢鷺下，林表伴僧過。","閑檢仙方試，松花酒自和。"]', '["休官不到闕，求静匪營他。","種藥唯愁晚，看云肯厭多。","渚邊逢鷺下，林表伴僧過。","闲檢仙方試，松花酒自和。"]', '诗', 'shi', '', NULL, '贈鄠縣尉李先輩二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c52ce05-5950-473e-99d1-ae8955260476', '邊將', '邊將', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["玉榼酒頻傾，論功笑李陵。","紅韁跑駿馬，金鏃掣秋鷹。","塞迥連天雪，河深徹底冰。","誰言提一劍，勤苦事中興。"]', '["玉榼酒頻傾，論功笑李陵。","紅韁跑駿马，金鏃掣秋鷹。","塞迥連天雪，河深徹底冰。","誰言提一劍，勤苦事中兴。"]', '诗', 'shi', '', NULL, '邊將 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e73ec8cc-adc7-48de-8cd5-8780f364700c', '下第別令狐員外', '下第別令狐員外', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["論文期雨夜，飲酒及芳晨。","坐歎百花發，潛驚雙鬢新。","舊交多得路，別業遠仍貧。","便欲辭知己，歸耕海上春。"]', '["論文期雨夜，饮酒及芳晨。","坐歎百花發，潛驚雙鬢新。","旧交多得路，別業远仍貧。","便欲辞知己，归耕海上春。"]', '诗', 'shi', '', NULL, '下第別令狐員外 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c60bea3-e1a5-4699-9e53-47c30466ff69', '送春坊董正字浙右歸覲', '送春坊董正字浙右归覲', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["去覲毘陵日，秋殘建業中。","莎垂石城古，山闊海門空。","灌木寒檣遠，層波皓月同。","何當復讎校，春集少陽宮。"]', '["去覲毘陵日，秋殘建業中。","莎垂石城古，山闊海门空。","灌木寒檣远，層波皓月同。","何當复讎校，春集少陽宮。"]', '诗', 'shi', '', NULL, '送春坊董正字浙右歸覲 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06489b9-825b-411c-a9c8-db2879c6a1fc', '送和北虜使', '送和北虜使', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["路始陰山北，迢迢雨雪天。","長城人過少，沙磧馬難前。","日入流沙際，陰生瀚海邊。","刀鐶向月動，旌纛冒霜懸。","逐獸孤圍合，交兵一箭傳。","穹廬移斥候，烽火絕祁連。","漢將行持節，胡兒坐控弦。","明妃的迴面，南送使君旋。"]', '["路始陰山北，迢迢雨雪天。","长城人過少，沙磧马难前。","日入流沙際，陰生瀚海邊。","刀鐶向月动，旌纛冒霜懸。","逐獸孤圍合，交兵一箭傳。","穹廬移斥候，烽火絕祁連。","漢將行持節，胡兒坐控弦。","明妃的迴面，南送使君旋。"]', '诗', 'shi', '', NULL, '送和北虜使 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdf339e-637f-459e-8af0-e44f02b63b64', '攄情留別幷州從事', '攄情留別幷州從事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["淺學長自鄙，謬承賢達知。","才希漢主召，玉任楚人疑。","年長慙漂泊，恩深惜別離。","秋光獨鳥過，暝色一蟬悲。","鶴髮生何速，龍門上苦遲。","彫蟲羞朗鑒，干祿貴明時。","故國誠難返，青雲致未期。","空將感激淚，一自灑臨岐。"]', '["淺学长自鄙，謬承賢達知。","才希漢主召，玉任楚人疑。","年长慙漂泊，恩深惜別離。","秋光独鸟過，暝色一蟬悲。","鹤髮生何速，龙门上苦遲。","彫蟲羞朗鑒，干祿貴明时。","故国誠难返，青云致未期。","空將感激泪，一自灑臨岐。"]', '诗', 'shi', '', NULL, '攄情留別幷州從事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c01aeef-3da0-47dd-be5b-534bccf3c16b', '酬田卿送西遊', '酬田卿送西游', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["華堂開翠簟，惜別玉壺深。","客去當煩暑，蟬鳴復此心。","廢城喬木在，古道濁河侵。","莫慮西遊遠，西關絕隴陰。"]', '["华堂开翠簟，惜別玉壺深。","客去當煩暑，蟬鳴复此心。","廢城喬木在，古道濁河侵。","莫慮西游远，西关絕隴陰。"]', '诗', 'shi', '', NULL, '酬田卿送西遊 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc28968-a609-46bf-ac05-885400bcebe7', '雪中送青州薛評事', '雪中送青州薛評事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["臘景不可犯，從戎難自由。","憐君急王事，走馬赴邊州。","岳雪明日觀，海雲冒營丘。","慙無斗酒瀉，敢望御重裘。"]', '["臘景不可犯，從戎难自由。","怜君急王事，走马赴邊州。","岳雪明日观，海云冒營丘。","慙無斗酒瀉，敢望御重裘。"]', '诗', 'shi', '', NULL, '雪中送青州薛評事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7033db17-9311-4be0-8ffa-7bdc0f50baba', '哭京兆龐尹', '哭京兆龐尹', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["神州喪賢尹，父老泣關中。","未盡羣生願，纔留及物功。","清光沈皎月，素業振遺風。","履跡莓苔掩，珂聲紫陌空。","從來受知者，會葬漢陵東。"]', '["神州喪賢尹，父老泣关中。","未尽羣生願，纔留及物功。","清光沈皎月，素業振遺风。","履跡莓苔掩，珂声紫陌空。","從来受知者，會葬漢陵东。"]', '诗', 'shi', '', NULL, '哭京兆龐尹 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba671863-b442-47ef-9a31-acb4ade9b978', '路傍樹', '路傍樹', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["古樹何人種，清陰減昔時。","莓苔根半露，風雨節偏危。","蟲蠹心將穴，蟬催葉向衰。","樵童不須翦，聊起邵公思。"]', '["古樹何人種，清陰減昔时。","莓苔根半露，风雨節偏危。","蟲蠹心將穴，蟬催葉向衰。","樵童不須翦，聊起邵公思。"]', '诗', 'shi', '', NULL, '路傍樹 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0905485-1254-442f-8c90-e4d01de58576', '送客南遊', '送客南游', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["擬卜何山隱，高秋指岳陽。","葦乾雲夢色，橘熟洞庭香。","疎雨殘虹影，[囘]雲背鳥行。","靈均如可問，一爲哭清湘。"]', '["擬卜何山隐，高秋指岳陽。","葦乾云梦色，橘熟洞庭香。","疎雨殘虹影，[囘]云背鸟行。","靈均如可问，一爲哭清湘。"]', '诗', 'shi', '', NULL, '送客南遊 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73dd12a7-48d8-4b9e-bcac-c07270847304', '寄襄陽王公子', '寄襄陽王公子', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["君馬勒金羈，君家貯玉笄。","白雲登峴首，碧樹醉銅鞮。","澤廣荆州北，山多漢水西。","鹿門知不隱，芳草自萋萋。"]', '["君马勒金羈，君家貯玉笄。","白云登峴首，碧樹醉銅鞮。","澤廣荆州北，山多漢水西。","鹿门知不隐，芳草自萋萋。"]', '诗', 'shi', '', NULL, '寄襄陽王公子 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33236907-df1c-4890-984a-099367f1b306', '集宿姚侍御宅懷永樂宰殷侍御', '集宿姚侍御宅懷永乐宰殷侍御', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["石田虞芮接，種樹白雲陰。","穴閉神踪古，河流禹鑿深。","樵人應滿郭，僊鳥幾巢林。","此會偏相語，曾供雪夜吟。"]', '["石田虞芮接，種樹白云陰。","穴閉神踪古，河流禹鑿深。","樵人應满郭，僊鸟幾巢林。","此會偏相語，曾供雪夜吟。"]', '诗', 'shi', '', NULL, '集宿姚侍御宅懷永樂宰殷侍御 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72586e99-f113-4d0d-9f16-6015c4e7da47', '易水懷古', '易水懷古', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["荆卿西去不復返，易水東流無盡期。","落日蕭條薊城北，黃沙白草任風吹。"]', '["荆卿西去不复返，易水东流無尽期。","落日蕭條薊城北，黄沙白草任风吹。"]', '诗', 'shi', '', NULL, '易水懷古 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f0943a-4211-41e1-b830-a3b493048f96', '送僧二首 一', '送僧二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["親在平陽憶久歸，洪河雨漲出關遲。","獨過舊寺人稀識，一一杉松老別時。"]', '["親在平陽憶久归，洪河雨漲出关遲。","独過旧寺人稀識，一一杉松老別时。"]', '诗', 'shi', '', NULL, '送僧二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9a8218-f54a-4008-938c-002aaad1b9fd', '送僧二首 二', '送僧二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["龕中破衲自持行，樹下禪牀坐一生。","來往白雲知歲久，滿山猨鳥會經聲。"]', '["龕中破衲自持行，樹下禪牀坐一生。","来往白云知歲久，满山猨鸟會經声。"]', '诗', 'shi', '', NULL, '送僧二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9620643-8eb0-4c7f-a1aa-8745bc45eb06', '贈友人邊遊回', '贈友人邊游回', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["遊子新從絕塞回，自言曾上李陵臺。","尊前語盡北風起，秋色蕭條胡鴈來。"]', '["游子新從絕塞回，自言曾上李陵台。","尊前語尽北风起，秋色蕭條胡鴈来。"]', '诗', 'shi', '', NULL, '贈友人邊遊回 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2bf42b8-beac-4e81-b1d6-adbc14ab743e', '山中作', '山中作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["屐齒無泥竹策輕，莓苔梯滑夜難行。","獨開石室松門裏，月照前山空水聲。"]', '["屐齒無泥竹策轻，莓苔梯滑夜难行。","独开石室松门裏，月照前山空水声。"]', '诗', 'shi', '', NULL, '山中作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff3e644-c094-47b7-a546-4d33d9c7fa4f', '出塞詞', '出塞词', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金帶連環束戰袍，馬頭衝雪度臨洮。","卷旗夜劫單于帳，亂斫胡兒缺寶刀。"]', '["金带連环束戰袍，马头衝雪度臨洮。","卷旗夜劫單于帳，亂斫胡兒缺寶刀。"]', '诗', 'shi', '', NULL, '出塞詞 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2ea763-c109-4e41-ad3b-915d801055f4', '寄雲臺觀田秀才', '寄云台观田秀才', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["雲壓松枝拂石窗，幽人獨坐鶴成雙。","晚來漱齒敲冰渚，閑讀仙書倚翠幢。"]', '["云壓松枝拂石窗，幽人独坐鹤成雙。","晚来漱齒敲冰渚，闲读仙书倚翠幢。"]', '诗', 'shi', '', NULL, '寄雲臺觀田秀才 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6e544d-649b-417e-92d7-fd47cb420bde', '邊上送楊侍御鞫獄回', '邊上送楊侍御鞫獄回', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["獄成冤雪晚雲開，豸角威清塞鴈回。","飛將送迎遙避馬，離亭不敢勸金杯。"]', '["獄成冤雪晚云开，豸角威清塞鴈回。","飞將送迎遙避马，離亭不敢勸金杯。"]', '诗', 'shi', '', NULL, '邊上送楊侍御鞫獄回 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81908fe0-1542-4285-979b-4e9797387df3', '射鵰騎', '射鵰騎', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["蕃面將軍著鼠裘，酣歌衝雪在邊州。","獵過黑山猶走馬，寒鵰射落不回頭。"]', '["蕃面將軍著鼠裘，酣歌衝雪在邊州。","獵過黑山猶走马，寒鵰射落不回头。"]', '诗', 'shi', '', NULL, '射鵰騎 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40d606c-4c5f-4217-a0e4-939aee655c0a', '高司馬移竹', '高司马移竹', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["叢居堂下幸君移，翠掩燈窗露葉垂。","莫羨孤生在山者，無人看著拂雲枝。"]', '["叢居堂下幸君移，翠掩灯窗露葉垂。","莫羨孤生在山者，無人看著拂云枝。"]', '诗', 'shi', '', NULL, '高司馬移竹 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45213ee8-2745-4f4b-b0d5-d1a0add85c13', '贈前蔚州崔使君', '贈前蔚州崔使君', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["戰回脫劍綰銅魚，塞鴈迎風避隼旟。","欲識前時爲郡政，校成上下考新書。"]', '["戰回脫劍綰銅鱼，塞鴈迎风避隼旟。","欲識前时爲郡政，校成上下考新书。"]', '诗', 'shi', '', NULL, '贈前蔚州崔使君 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15343da-3f7e-4d97-8df0-6d9a5b567a40', '秋思二首 一', '秋思二首 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["萬木秋霖後，孤山夕照餘。","田園無歲計，寒近憶樵漁。"]', '["万木秋霖後，孤山夕照餘。","田园無歲計，寒近憶樵漁。"]', '诗', 'shi', '', NULL, '秋思二首 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a78a67-b2f7-4074-9bd9-6b1ddf0ac5a5', '秋思二首 二', '秋思二首 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["亭樹霜霰滿，野塘鳧鳥多。","蕙蘭不可折，楚老徒悲歌。"]', '["亭樹霜霰满，野塘鳧鸟多。","蕙蘭不可折，楚老徒悲歌。"]', '诗', 'shi', '', NULL, '秋思二首 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51479f73-6ab6-4dc2-8390-7133e7f759ce', '黃神谷紀事', '黄神谷紀事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["霹靂振秋岳，折松橫洞門。","雲龍忽變化，但覺玉潭昏。"]', '["霹靂振秋岳，折松橫洞门。","云龙忽变化，但覺玉潭昏。"]', '诗', 'shi', '', NULL, '黃神谷紀事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4617b59b-f075-4028-866b-7af90fadeecf', '過亡友墓', '過亡友墓', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["憶昨送君葬，今看墳樹高。","尋思後期者，只是益生勞。"]', '["憶昨送君葬，今看墳樹高。","尋思後期者，只是益生勞。"]', '诗', 'shi', '', NULL, '過亡友墓 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8ca915-d8a4-4468-bfb3-2a657e5551d4', '聞瀑布冰折', '闻瀑布冰折', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["萬仞冰峭折，寒聲投白雲。","光搖山月墮，我向石牀聞。"]', '["万仞冰峭折，寒声投白云。","光搖山月墮，我向石牀闻。"]', '诗', 'shi', '', NULL, '聞瀑布冰折 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d5c1773-a552-4415-8c5a-c303a7f13260', '贈道者', '贈道者', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["深居白雲穴，靜注赤松經。","往往龍潭上，焚香禮斗星。"]', '["深居白云穴，静注赤松經。","往往龙潭上，焚香禮斗星。"]', '诗', 'shi', '', NULL, '贈道者 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f255769e-40bc-4dae-8868-4c9f526d13c3', '華下逢楊侍御', '华下逢楊侍御', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["巨靈掌上月，玉女盆中泉。","柱史息車看，孤雲心浩然。"]', '["巨靈掌上月，玉女盆中泉。","柱史息车看，孤云心浩然。"]', '诗', 'shi', '', NULL, '華下逢楊侍御 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbf73521-d156-4d4a-b7e3-cd4dd537e397', '新春聞赦', '新春闻赦', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["道在猜讒息，仁深疾苦除。","堯聰能下聽，湯網本來疎。"]', '["道在猜讒息，仁深疾苦除。","堯聰能下听，湯網本来疎。"]', '诗', 'shi', '', NULL, '新春聞赦 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b35417-c352-4fa4-9445-71a50c95ab96', '送李侍御福建從事', '送李侍御福建從事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["晉安來越國，蔓草故宮迷。","釣渚龍應在，琴臺鶴亂栖。","泛濤明月廣，邊海衆山齊。","賓府通蘭棹，蠻僧接石梯。","片雲和瘴濕，孤嶼映帆低。","上客多詩興，秋猨足夜啼。"]', '["晉安来越国，蔓草故宮迷。","釣渚龙應在，琴台鹤亂栖。","泛濤明月廣，邊海衆山齊。","賓府通蘭棹，蠻僧接石梯。","片云和瘴濕，孤嶼映帆低。","上客多诗兴，秋猨足夜啼。"]', '诗', 'shi', '', NULL, '送李侍御福建從事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7cd263-55f4-478f-83b8-662be9bb3b77', '酬刑部姚郎中', '酬刑部姚郎中', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["路岐人不見，尚得記心中。","月憶瀟湘渚，春生蘭杜叢。","鳥啼花半落，人散爵方空。","所贈誠難荅，泠然一雅風。"]', '["路岐人不见，尚得記心中。","月憶瀟湘渚，春生蘭杜叢。","鸟啼花半落，人散爵方空。","所贈誠难荅，泠然一雅风。"]', '诗', 'shi', '', NULL, '酬刑部姚郎中 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3154fb8-f95e-47b4-87ab-43e9226c839a', '送柳秀才往連州看弟', '送柳秀才往連州看弟', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["離人非逆旅，有弟謫連州。","楚雨霑猨暮，湘雲拂鴈秋。","蒹葭行廣澤，星月棹寒流。","何處江關鏁，風濤阻客愁。"]', '["離人非逆旅，有弟謫連州。","楚雨霑猨暮，湘云拂鴈秋。","蒹葭行廣澤，星月棹寒流。","何处江关鏁，风濤阻客愁。"]', '诗', 'shi', '', NULL, '送柳秀才往連州看弟 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('542782c9-0673-4ef0-a910-0c7f8a199235', '晚眺有懷', '晚眺有懷', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["點點抱離念，曠懷成怨歌。","高臺試延望，落照在寒波。","此地芳草歇，舊山喬木多。","悠然暮天際，但見鳥相過。"]', '["点点抱離念，曠懷成怨歌。","高台試延望，落照在寒波。","此地芳草歇，旧山喬木多。","悠然暮天際，但见鸟相過。"]', '诗', 'shi', '', NULL, '晚眺有懷 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('905a0b01-43d6-456b-b995-954ec7f80019', '山中興作', '山中兴作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["高高丹桂枝，嫋嫋女蘿衣。","密葉浮雲過，幽陰暮鳥歸。","月和風翠動，花落瀑泉飛。","欲翦蘭爲佩，中林露未晞。"]', '["高高丹桂枝，嫋嫋女蘿衣。","密葉浮云過，幽陰暮鸟归。","月和风翠动，花落瀑泉飞。","欲翦蘭爲佩，中林露未晞。"]', '诗', 'shi', '', NULL, '山中興作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fed9dc4-aa57-4e1f-b52e-dcbc21f243fe', '送皇甫協律淮南從事', '送皇甫協律淮南從事', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["辟書丞相草，招作廣陵行。","隋柳疎淮岸，汀洲接海城。","楚檣經雨泊，煙月隔潮生。","誰與同尊俎，雞鸞集虎營。"]', '["辟书丞相草，招作廣陵行。","隋柳疎淮岸，汀洲接海城。","楚檣經雨泊，煙月隔潮生。","誰與同尊俎，雞鸾集虎營。"]', '诗', 'shi', '', NULL, '送皇甫協律淮南從事 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068e4250-c47a-41f8-b17e-26ba19c1bf15', '別靈武令狐校書', '別靈武令狐校书', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["北風吹別思，落月度關河。","樹隱流沙短，山平近塞多。","鴈池戎馬飲，鵰帳戍人過。","莫慮行軍苦，華夷道正和。"]', '["北风吹別思，落月度关河。","樹隐流沙短，山平近塞多。","鴈池戎马饮，鵰帳戍人過。","莫慮行軍苦，华夷道正和。"]', '诗', 'shi', '', NULL, '別靈武令狐校書 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('378b1f62-ef1a-445d-bd6c-bc1f67e41847', '田氏南樓對月', '田氏南楼对月', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["主人同露坐，明月在高臺。","咽咽陰蟲叫，蕭蕭寒鴈來。","影搖疎木落，魄轉曙鐘開。","幸免丹霞映，清光溢酒杯。"]', '["主人同露坐，明月在高台。","咽咽陰蟲叫，蕭蕭寒鴈来。","影搖疎木落，魄轉曙鐘开。","幸免丹霞映，清光溢酒杯。"]', '诗', 'shi', '', NULL, '田氏南樓對月 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f54aaba-e725-497f-bd5b-1d0cf1f330e1', '送宗密上人', '送宗密上人', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["門前九陌塵，石上定中身。","近放遼天鶴，曾爲南岳人。","臘高松葉換，雪盡茗芽新。","一自傳香後，名山願卜鄰。"]', '["门前九陌塵，石上定中身。","近放遼天鹤，曾爲南岳人。","臘高松葉換，雪尽茗芽新。","一自傳香後，名山願卜鄰。"]', '诗', 'shi', '', NULL, '送宗密上人 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c54d25a-9dce-4e90-8fb8-01be81bedc6a', '白鹿原晚望', '白鹿原晚望', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["滻曲鴈飛下，秦原人葬回。","丘墳與城闕，草樹共塵埃。"]', '["滻曲鴈飞下，秦原人葬回。","丘墳與城闕，草樹共塵埃。"]', '诗', 'shi', '', NULL, '白鹿原晚望 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f11cda90-cfcb-43fe-91a9-701992c91c1d', '失意書懷呈知己', '失意书懷呈知己', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["直道何由啓聖君，非才誰敢議論文。","心存黃籙兼丹訣，家憶青山與白雲。","麋鹿幽栖閑可近，鴛鸞高舉勢宜分。","微生不學劉琨輩，劍刃相交擬立勳。"]', '["直道何由啓聖君，非才誰敢議論文。","心存黄籙兼丹訣，家憶青山與白云。","麋鹿幽栖闲可近，鴛鸾高舉勢宜分。","微生不学劉琨輩，劍刃相交擬立勳。"]', '诗', 'shi', '', NULL, '失意書懷呈知己 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6248d782-091d-4134-b106-06597a3c7d59', '春日尋滻川王處士', '春日尋滻川王处士', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["碧草徑微斷，白雲扉晚開。","罷琴松韻發，鑒水月光來。","宿鳥排花動，樵童澆竹迴。","與君同露坐，澗石拂青苔。"]', '["碧草徑微斷，白云扉晚开。","罷琴松韻發，鑒水月光来。","宿鸟排花动，樵童澆竹迴。","與君同露坐，澗石拂青苔。"]', '诗', 'shi', '', NULL, '春日尋滻川王處士 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03b58aa-ea77-4312-a387-519917d8a083', '宿陽臺觀', '宿陽台观', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["玉洞仙何在，爐香客自焚。","醮壇圍古木，石磬響寒雲。","曙月孤霞映，懸流峭壁分。","心知人世隔，坐與鶴爲羣。"]', '["玉洞仙何在，爐香客自焚。","醮壇圍古木，石磬响寒云。","曙月孤霞映，懸流峭壁分。","心知人世隔，坐與鹤爲羣。"]', '诗', 'shi', '', NULL, '宿陽臺觀 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715a9521-1779-4728-a918-065dd7d8d84c', '寄金州姚使君員外', '寄金州姚使君員外', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["老懷清淨化，乞去守洵陽。","廢井人應滿，空林虎自藏。","迸泉疎石竇，殘雨發椒香。","山缺通巴峽，江流帶楚檣。","憂農生野思，禱廟結雲裝。","覆局松移影，聽琴月墮光。","鳥鳴開郡印，僧去置禪牀。","罷貢金休鑿，凌寒笋更長。","退公披鶴氅，高步隔鵷行。","相見朱門內，麾幢拂曙霜。"]', '["老懷清淨化，乞去守洵陽。","廢井人應满，空林虎自藏。","迸泉疎石竇，殘雨發椒香。","山缺通巴峽，江流带楚檣。","憂農生野思，禱廟結云裝。","覆局松移影，听琴月墮光。","鸟鳴开郡印，僧去置禪牀。","罷貢金休鑿，凌寒笋更长。","退公披鹤氅，高步隔鵷行。","相见朱门內，麾幢拂曙霜。"]', '诗', 'shi', '', NULL, '寄金州姚使君員外 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc307d0-81b0-45c6-b403-113a1ec032de', '中秋夜坐有懷', '中秋夜坐有懷', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["秋光動河漢，耿耿曙難分。","墮露垂叢藥，殘星間薄雲。","心懸赤城嶠，志向紫陽君。","鴈過海風起，蕭蕭時獨聞。"]', '["秋光动河漢，耿耿曙难分。","墮露垂叢藥，殘星间薄云。","心懸赤城嶠，志向紫陽君。","鴈過海风起，蕭蕭时独闻。"]', '诗', 'shi', '', NULL, '中秋夜坐有懷 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe31d82-d0ed-48cf-9bf2-c9a601bffd4c', '題鏡湖野老所居', '題镜湖野老所居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["湖裏尋君去，樵風往返吹。","樹喧巢鳥出，路細葑田移。","漚苧成魚網，枯根是酒巵。","老年唯自適，生事任羣兒。"]', '["湖裏尋君去，樵风往返吹。","樹喧巢鸟出，路細葑田移。","漚苧成鱼網，枯根是酒巵。","老年唯自適，生事任羣兒。"]', '诗', 'shi', '', NULL, '題鏡湖野老所居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcd3d59-79c6-4ad3-8dad-4d26c961bd2a', '題女道士居', '題女道士居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["不餌住雲溪，休丹罷藥畦。","杏花虛結子，石髓任成泥。","掃地青牛臥，栽松白鶴棲。","共知仙女麗，莫是阮郎妻。"]', '["不餌住云溪，休丹罷藥畦。","杏花虛結子，石髓任成泥。","掃地青牛臥，栽松白鹤棲。","共知仙女丽，莫是阮郎妻。"]', '诗', 'shi', '', NULL, '題女道士居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f5452c-5d30-49e3-b28e-4c9d5cb4e6a1', '送王道士', '送王道士', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["真人俄整舃，雙鶴屢飛翔。","恐入壺中住，須傳肘後方。","霓裳雲氣潤，石徑朮苗香。","一去何時見，仙家日月長。"]', '["真人俄整舃，雙鹤屢飞翔。","恐入壺中住，須傳肘後方。","霓裳云氣潤，石徑朮苗香。","一去何时见，仙家日月长。"]', '诗', 'shi', '', NULL, '送王道士 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a349aca9-49e5-4bd0-8c56-700071dbf895', '送道友入天台山作', '送道友入天台山作', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["却憶天台去，移居海島空。","觀寒琪樹碧，雪淺石橋通。","漱齒飛泉外，餐霞早境中。","終期赤城裏，披氅與君同。"]', '["却憶天台去，移居海島空。","观寒琪樹碧，雪淺石橋通。","漱齒飞泉外，餐霞早境中。","終期赤城裏，披氅與君同。"]', '诗', 'shi', '', NULL, '送道友入天台山作 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43db82d6-e467-4b63-91a9-9939bee76503', '題章野人山居', '題章野人山居', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["帶郭茅亭詩興饒，回看一曲倚危橋。","門前山色能深淺，壁上湖光自動搖。","閑花散落填書帙，戲鳥低飛礙柳條。","向此隱來經幾載，如今已是漢家朝。"]', '["带郭茅亭诗兴饒，回看一曲倚危橋。","门前山色能深淺，壁上湖光自动搖。","闲花散落填书帙，戲鸟低飞礙柳條。","向此隐来經幾載，如今已是漢家朝。"]', '诗', 'shi', '', NULL, '題章野人山居 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c6e5b7-c9ec-41a6-b869-13c8ebe13c01', '江中遇客', '江中遇客', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["危石江中起，孤雲嶺上還。","相逢皆得意，何處是鄉關。"]', '["危石江中起，孤云嶺上還。","相逢皆得意，何处是乡关。"]', '诗', 'shi', '', NULL, '江中遇客 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6396ec5b-ee20-4102-9463-2ca22d911c63', '期王鍊師不至', '期王鍊師不至', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["黃精蒸罷洗瓊桮，林下從留石上苔。","昨日圍棋未終局，多乘白鶴下山來。"]', '["黄精蒸罷洗瓊桮，林下從留石上苔。","昨日圍棋未終局，多乘白鹤下山来。"]', '诗', 'shi', '', NULL, '期王鍊師不至 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266e348a-964f-46f7-8c49-cef4ffa6b79c', '秋日送僧志幽歸山寺', '秋日送僧志幽归山寺', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["禪室繩牀在翠微，松間荷笠一僧歸。","磬聲寂歷宜秋夜，手冷燈前自衲衣。"]', '["禪室繩牀在翠微，松间荷笠一僧归。","磬声寂歷宜秋夜，手冷灯前自衲衣。"]', '诗', 'shi', '', NULL, '秋日送僧志幽歸山寺 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1deddf71-9ab1-41e2-bb7e-2b86d0400cdf', '句', '句', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["申胥任向秦庭哭，靳尚終貽楚國憂。"]', '["申胥任向秦庭哭，靳尚終貽楚国憂。"]', '诗', 'shi', '', NULL, '句 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f11dd0a-0bac-48a1-89a4-dcf9902c2fa0', '寄宜陽兄弟', '寄宜陽兄弟', '604a9e8d-adb5-4be4-98f9-279027e94e9d', '唐', '["六年雁序恨分離，詔下今朝遇已知。","上國皇風初喜日，御堦恩渥屬身時。","內庭再考稱文異，聖主宣名獎藝奇。","故里仙才若相問，一春攀得兩重枝。"]', '["六年雁序恨分離，詔下今朝遇已知。","上国皇风初喜日，御堦恩渥屬身时。","內庭再考稱文異，聖主宣名獎藝奇。","故里仙才若相问，一春攀得兩重枝。"]', '诗', 'shi', '', NULL, '寄宜陽兄弟 易重 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('414118c2-6629-400b-aaba-8ffc9453926e', '發蕙風館遇陰不見九華山有作', '發蕙风館遇陰不见九华山有作', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["我來淮陰城，千江萬山無不經。","山青水碧千萬丈，奇峯急派何縱橫。","又聞九華山，山頂連青冥。","太白有逸韻，使我西南行。","一步一攀策，前行正雞鳴。","陰雲冉冉忽飛起，千里萬里危崢嶸。","譬如天之有日蝕，使我昏沈猶不明。","人家敲鏡救不得，光陰却屬貪狼星。","恨亦不能通，言亦不足聽。","長鞭揮馬出門去，是以九華爲不平。"]', '["我来淮陰城，千江万山無不經。","山青水碧千万丈，奇峯急派何縱橫。","又闻九华山，山頂連青冥。","太白有逸韻，使我西南行。","一步一攀策，前行正雞鳴。","陰云冉冉忽飞起，千里万里危崢嶸。","譬如天之有日蝕，使我昏沈猶不明。","人家敲镜救不得，光陰却屬貪狼星。","恨亦不能通，言亦不足听。","长鞭揮马出门去，是以九华爲不平。"]', '诗', 'shi', '', NULL, '發蕙風館遇陰不見九華山有作 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4be2d7d-dce0-47e0-8992-25e62b961e52', '寄浙右舊幕僚', '寄浙右旧幕僚', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["由來惡舌駟難追，自古無媒謗所歸。","勾踐豈能容范蠡，李斯何暇救韓非。","巨拳豈爲雞揮肋，強弩那因鼠發機。","慚愧故人同鮑叔，此心江柳尚依依。"]', '["由来惡舌駟难追，自古無媒謗所归。","勾踐豈能容范蠡，李斯何暇救韓非。","巨拳豈爲雞揮肋，強弩那因鼠發機。","慚愧故人同鲍叔，此心江柳尚依依。"]', '诗', 'shi', '', NULL, '寄浙右舊幕僚 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb0b2cc-f676-4942-91f2-cb82478d8c00', '壯士吟', '壯士吟', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["壯士何曾悲，悲即無回期。","如何易水上，未歌淚先垂。"]', '["壯士何曾悲，悲即無回期。","如何易水上，未歌泪先垂。"]', '诗', 'shi', '', NULL, '壯士吟 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192e875f-5fd2-470d-985e-95d5fef52e5b', '徐波渡', '徐波渡', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["曉月千重樹，春煙十里溪。","過來還過去，此路不知迷。"]', '["晓月千重樹，春煙十里溪。","過来還過去，此路不知迷。"]', '诗', 'shi', '', NULL, '徐波渡 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f6476e-dcd2-45e5-be2a-71f958e24e4d', '題嘉祥驛', '題嘉祥驛', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["樹頂煙微綠，山根菊暗香。","何人獨鞭馬，落日上嘉祥。"]', '["樹頂煙微綠，山根菊暗香。","何人独鞭马，落日上嘉祥。"]', '诗', 'shi', '', NULL, '題嘉祥驛 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a4a2505-e835-4946-8276-1ae297ba945e', '懷鄭洎', '懷鄭洎', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["風蘭舞幽香，雨葉墮寒滴。","美人來不來，前山看向夕。"]', '["风蘭舞幽香，雨葉墮寒滴。","美人来不来，前山看向夕。"]', '诗', 'shi', '', NULL, '懷鄭洎 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1229a5-ca4f-4d22-b5cb-a2c383d36991', '長信宮', '长信宮', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["君恩已盡欲何歸，猶有殘香在舞衣。","自恨身輕不如燕，春來還遶御簾飛。"]', '["君恩已尽欲何归，猶有殘香在舞衣。","自恨身轻不如燕，春来還遶御簾飞。"]', '诗', 'shi', '', NULL, '長信宮 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('671f5b4e-e27b-4e17-ab4e-066751b75352', '閨情', '閨情', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["山上有山歸不得，湘江暮雨鷓鴣飛。","蘼蕪亦是王孫草，莫送春香入客衣。"]', '["山上有山归不得，湘江暮雨鷓鴣飞。","蘼蕪亦是王孫草，莫送春香入客衣。"]', '诗', 'shi', '', NULL, '閨情 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e0613e-c047-4459-ba18-fd2802efaa9e', '蓮塘', '蓮塘', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["脉脉低回殷袖遮，臉橫秋水髻盤鴉。","蓮莖有刺不成折，盡日岸傍空看花。"]', '["脉脉低回殷袖遮，臉橫秋水髻盤鴉。","蓮莖有刺不成折，尽日岸傍空看花。"]', '诗', 'shi', '', NULL, '蓮塘 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844b3841-0c34-4d9d-bb8a-07377c4fada7', '還淮卻寄睢陽', '還淮卻寄睢陽', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["梁王池苑已蒼然，滿樹斜陽極浦煙。","盡日回頭看不見，兩行愁淚上南船。"]', '["梁王池苑已蒼然，满樹斜陽極浦煙。","尽日回头看不见，兩行愁泪上南船。"]', '诗', 'shi', '', NULL, '還淮卻寄睢陽 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ffa045-4377-47bf-8807-be1e7cc9ae1e', '烏江', '烏江', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["中分豈是無遺策，百戰空勞不逝騅。","大葉固非人事及，烏江亭長又何知。"]', '["中分豈是無遺策，百戰空勞不逝騅。","大葉固非人事及，烏江亭长又何知。"]', '诗', 'shi', '', NULL, '烏江 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5580c982-d27d-40fb-9cee-c20e2bdda267', '新安故關', '新安故关', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["漢帝英雄重武材，崇山險處鑿門開。","如今更有將軍否，移取潼關向北來。"]', '["漢帝英雄重武材，崇山險处鑿门开。","如今更有將軍否，移取潼关向北来。"]', '诗', 'shi', '', NULL, '新安故關 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bdfa91e-4971-4068-94cd-a87e05bfd694', '廣陵城', '廣陵城', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["紅遶高臺綠遶城，城邊春草傍牆生。","隋家不向此中盡，汴水應無東去聲。"]', '["紅遶高台綠遶城，城邊春草傍牆生。","隋家不向此中尽，汴水應無东去声。"]', '诗', 'shi', '', NULL, '廣陵城 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7331f5-925d-4b37-b7a2-f94827e2a98f', '過驪山', '過驪山', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["冷日微煙渭水愁，華清宮樹不勝秋。","霓裳一曲千門鎖，白盡梨園弟子頭。"]', '["冷日微煙渭水愁，华清宮樹不勝秋。","霓裳一曲千门鎖，白尽梨园弟子头。"]', '诗', 'shi', '', NULL, '過驪山 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77078680-2880-4934-9607-edff104b8de5', '吳故宮', '吳故宮', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["越女歌長君且聽，芙蓉香滿水邊城。","豈知一日終非主，猶自如今有怨聲。"]', '["越女歌长君且听，芙蓉香满水邊城。","豈知一日終非主，猶自如今有怨声。"]', '诗', 'shi', '', NULL, '吳故宮 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57affaa2-5723-42fc-8d4c-a6d765f7b969', '蘭昌宮', '蘭昌宮', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["宮門兩片掩埃塵，牆上無花草不春。","誰見當時禁中事，阿嬌解佩與何人。"]', '["宮门兩片掩埃塵，牆上無花草不春。","誰见當时禁中事，阿嬌解佩與何人。"]', '诗', 'shi', '', NULL, '蘭昌宮 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad61312c-2a93-4404-9c5d-91f075e3bc0d', '宮人斜', '宮人斜', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["雲慘煙愁苑路斜，路傍丘冢盡宮娃。","茂陵不是同歸處，空寄香魂著野花。"]', '["云慘煙愁苑路斜，路傍丘冢尽宮娃。","茂陵不是同归处，空寄香魂著野花。"]', '诗', 'shi', '', NULL, '宮人斜 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119e2206-6703-49ed-ae95-8c717e0da2d0', '句', '句', '5493340d-ccc1-40b5-838a-9af644991e48', '唐', '["天地有時饒一擲，江山無主任平分。"]', '["天地有时饒一擲，江山無主任平分。"]', '诗', 'shi', '', NULL, '句 孟遲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad2ae20-cd1f-4f41-bfa4-0bbfba170b64', '和于興宗登越王樓詩', '和于兴宗登越王楼诗', '540ee676-e749-4d6c-8377-619cbec06f5d', '唐', '["謝眺題詩處，危樓壓郡城。","雨餘江水碧，雲斷雪山明。","錦繡來仙境，風光入帝京。","恨無青玉案，何以報高情。"]', '["謝眺題诗处，危楼壓郡城。","雨餘江水碧，云斷雪山明。","錦繡来仙境，风光入帝京。","恨無青玉案，何以報高情。"]', '诗', 'shi', '', NULL, '和于興宗登越王樓詩 王鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624fbc66-a644-47d9-9c1c-40b049cf0730', '謁梓潼張惡子廟', '謁梓潼張惡子廟', '540ee676-e749-4d6c-8377-619cbec06f5d', '唐', '["盛唐聖主解青萍，欲振新封濟順名。","夜雨龍拋三尺匣，春雲鳳入九重城。","劒門喜氣隨雷動，玉壘韶光待賊平。","惟報關東諸將相，柱天功業賴陰兵。"]', '["盛唐聖主解青萍，欲振新封濟順名。","夜雨龙拋三尺匣，春云鳳入九重城。","劒门喜氣隨雷动，玉壘韶光待賊平。","惟報关东諸將相，柱天功業賴陰兵。"]', '诗', 'shi', '', NULL, '謁梓潼張惡子廟 王鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96c0fe1-5315-4eae-9b61-3465e28ac073', '罷都統守鎮滑州作', '罷都統守鎮滑州作', '540ee676-e749-4d6c-8377-619cbec06f5d', '唐', '["用軍何事敢遷延，恩重才輕分使然。","黜詔已聞來闕下，檄書猶未遍軍前。","腰間盡解蘇秦印，波上虛迎范蠡船。","正會星辰扶北極，却驅戈甲鎮南燕。","三塵上相逢明主，九合諸侯媿昔賢。","看却中興扶大業，殺身無路好歸田。"]', '["用軍何事敢遷延，恩重才轻分使然。","黜詔已闻来闕下，檄书猶未遍軍前。","腰间尽解蘇秦印，波上虛迎范蠡船。","正會星辰扶北極，却驱戈甲鎮南燕。","三塵上相逢明主，九合諸侯媿昔賢。","看却中兴扶大業，殺身無路好归田。"]', '诗', 'shi', '', NULL, '罷都統守鎮滑州作 王鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ba9321-6bc3-4af7-9e0d-5b6ddab1a1ad', '句', '句', '540ee676-e749-4d6c-8377-619cbec06f5d', '唐', '["華表尚迷丁令鶴，竹坡猶認葛溪龍。"]', '["华表尚迷丁令鹤，竹坡猶認葛溪龙。"]', '诗', 'shi', '', NULL, '句 王鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ab5fa3-8132-4fba-94b6-cda1db4755dd', '中秋月直禁苑', '中秋月直禁苑', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["禁署方懷忝，綸闈已再加。","暫來西掖路，還整上清槎。","恍惚歸丹地，深嚴宿絳霞。","幽襟聊自適，閑弄紫薇花。"]', '["禁署方懷忝，綸闈已再加。","暫来西掖路，還整上清槎。","恍惚归丹地，深嚴宿絳霞。","幽襟聊自適，闲弄紫薇花。"]', '诗', 'shi', '', NULL, '中秋月直禁苑 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1567757f-34ad-40e6-8bf2-d2eb76454a2c', '麥穗兩岐', '麦穗兩岐', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["聖慮憂千畝，嘉苗薦兩岐。","如雲方表盛，成穗忽標奇。","瑞露縱橫滴，祥風左右吹。","謳歌連上苑，化日遍平陂。","史冊書堪重，丹青畫更宜。","願依連理樹，俱作萬年枝。"]', '["聖慮憂千畝，嘉苗薦兩岐。","如云方表盛，成穗忽標奇。","瑞露縱橫滴，祥风左右吹。","謳歌連上苑，化日遍平陂。","史冊书堪重，丹青畫更宜。","願依連理樹，俱作万年枝。"]', '诗', 'shi', '', NULL, '麥穗兩岐 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('729d87a8-7286-48e3-9b02-5032c4ef5d39', '五月一日紫宸候對時屬禁直穿內而行因書六韻', '五月一日紫宸候对时屬禁直穿內而行因书六韻', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["朱夏五更後，步廊三里餘。","有人從翰苑，穿入內中書。","漏響飄銀箭，燈光照玉除。","禁扉猶鏁鑰，宮妓已妝梳。","紫府遊應似，鈞天夢不如。","塵埃九重外，誰信在清虛。"]', '["朱夏五更後，步廊三里餘。","有人從翰苑，穿入內中书。","漏响飄銀箭，灯光照玉除。","禁扉猶鏁鑰，宮妓已妝梳。","紫府游應似，鈞天梦不如。","塵埃九重外，誰信在清虛。"]', '诗', 'shi', '', NULL, '五月一日紫宸候對時屬禁直穿內而行因書六韻 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a62c39-2698-4d68-842f-a9ff595faa85', '題緱山王子晉廟', '題緱山王子晉廟', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["有昔靈王子，吹笙遡泬㵳。","六宮攀不住，三島去相招。","亡國原陵古，賓天歲月遙。","無蹊窺海曲，有廟訪山椒。","石帳龍蛇拱，雲櫳彩翠銷。","露壇裝琬琰，真像寫松喬。","珠館青童宴，琳宮阿母朝。","氣輿仙女侍，天馬吏兵調。","湘妓紅絲瑟，秦郎白管簫。","西城要綽約，南嶽命嬌嬈。","句曲觴金洞，天台嘯石橋。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元寶籙饒。","霧垂鴉翅髮，冰束虎章腰。","鶴馭爭銜箭，龍妃合獻綃。","衣從星渚浣，丹就日宮燒。","物外花嘗滿，人間葉自凋。","望臺悲漢戾，閱水笑梁昭。","古殿香殘炧，荒堦柳長條。","幾曾期七日，無復降重霄。","嵩嶺連天漢，伊瀾入海潮。","何由得真訣，使我珮環飄。"]', '["有昔靈王子，吹笙遡泬㵳。","六宮攀不住，三島去相招。","亡国原陵古，賓天歲月遙。","無蹊窺海曲，有廟訪山椒。","石帳龙蛇拱，云櫳彩翠銷。","露壇裝琬琰，真像寫松喬。","珠館青童宴，琳宮阿母朝。","氣輿仙女侍，天马吏兵調。","湘妓紅絲瑟，秦郎白管簫。","西城要綽約，南嶽命嬌嬈。","句曲觴金洞，天台嘯石橋。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元寶籙饒。","霧垂鴉翅髮，冰束虎章腰。","鹤馭爭銜箭，龙妃合獻綃。","衣從星渚浣，丹就日宮燒。","物外花嘗满，人间葉自凋。","望台悲漢戾，閱水笑梁昭。","古殿香殘炧，荒堦柳长條。","幾曾期七日，無复降重霄。","嵩嶺連天漢，伊瀾入海潮。","何由得真訣，使我珮环飄。"]', '诗', 'shi', '', NULL, '題緱山王子晉廟 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f9d14e5-c2d4-45a1-beb2-752efa1e3db7', '初秋寓直三首 一', '初秋寓直三首 一', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["曉星獨挂結麟樓，三殿風高藥樹秋。","玉笛數聲飄不住，問人依約在東頭。"]', '["晓星独挂結麟楼，三殿风高藥樹秋。","玉笛數声飄不住，问人依約在东头。"]', '诗', 'shi', '', NULL, '初秋寓直三首 一 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dcc7b94-64da-4f67-92cb-c47a6d347b05', '初秋寓直三首 二', '初秋寓直三首 二', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["宿鳥翩翩落照微，石臺樓閣鎖重扉。","步廊無限金羈響，應是諸司扈從歸。"]', '["宿鸟翩翩落照微，石台楼閣鎖重扉。","步廊無限金羈响，應是諸司扈從归。"]', '诗', 'shi', '', NULL, '初秋寓直三首 二 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5311784-d491-40ae-bea2-0888c5dcf2d4', '初秋寓直三首 三', '初秋寓直三首 三', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["幽閣焚香萬慮凝，下簾胎息過禪僧。","玉堂分照無人後，消盡金盆一碗冰。"]', '["幽閣焚香万慮凝，下簾胎息過禪僧。","玉堂分照無人後，消尽金盆一碗冰。"]', '诗', 'shi', '', NULL, '初秋寓直三首 三 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919b77b2-59b8-4517-86e9-44e0218e539b', '夜景又作', '夜景又作', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["鈴絛無響閉珠宮，小閣涼添玉蘂風。","枕簟滿牀明月到，自疑身在五雲中。"]', '["鈴絛無响閉珠宮，小閣涼添玉蘂风。","枕簟满牀明月到，自疑身在五云中。"]', '诗', 'shi', '', NULL, '夜景又作 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fed06b-c500-4cdb-9336-32c87acd98ad', '杪秋夜直', '杪秋夜直', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["蘂宮裁詔與宵分，雖在青雲憶白雲。","待報君恩了歸去，山翁何急草移文。"]', '["蘂宮裁詔與宵分，雖在青云憶白云。","待報君恩了归去，山翁何急草移文。"]', '诗', 'shi', '', NULL, '杪秋夜直 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bfd7596-9288-4a38-9d0b-c77d6f9e1ef1', '禁直寄崔員外', '禁直寄崔員外', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["銀臺樓北蘂珠宮，敻與人間路不同。","在省五更春睡侶，早來分夢玉堂中。"]', '["銀台楼北蘂珠宮，敻與人间路不同。","在省五更春睡侶，早来分梦玉堂中。"]', '诗', 'shi', '', NULL, '禁直寄崔員外 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfba46c4-2a0b-467a-b108-68bcfe8248b7', '聞號', '闻號', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["陛兵偏近羽林營，夜靜仍傳禁號聲。","應笑執金雙闕下，近南猶隔兩重城。"]', '["陛兵偏近羽林營，夜静仍傳禁號声。","應笑執金雙闕下，近南猶隔兩重城。"]', '诗', 'shi', '', NULL, '聞號 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d85846-0705-4732-86bb-3e6c218800d5', '禁直和人飲酒', '禁直和人饮酒', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["卉醴陀花物外香，清濃標格勝椒漿。","我來尚有鈞天會，猶得金尊半日嘗。"]', '["卉醴陀花物外香，清濃標格勝椒漿。","我来尚有鈞天會，猶得金尊半日嘗。"]', '诗', 'shi', '', NULL, '禁直和人飲酒 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c301fb-8db1-4220-bded-7b13f121a7ec', '下直早出', '下直早出', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["諸司人盡馬蹄稀，紫帕雲竿九釘歸。","偏覺石臺清貴處，牓懸金字射晴暉。"]', '["諸司人尽马蹄稀，紫帕云竿九釘归。","偏覺石台清貴处，牓懸金字射晴暉。"]', '诗', 'shi', '', NULL, '下直早出 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52854c29-5ef8-45bd-9044-9966bcaad0a3', '金鑾坡上南望', '金鑾坡上南望', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["玉晨鐘韻上清虛，畫戟祥煙拱帝居。","極眼向南無限地，綠煙深處認中書。"]', '["玉晨鐘韻上清虛，畫戟祥煙拱帝居。","極眼向南無限地，綠煙深处認中书。"]', '诗', 'shi', '', NULL, '金鑾坡上南望 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b16580-163e-4807-9a76-846468bfe735', '酬隱珪舍人寄紅燭', '酬隐珪舍人寄紅燭', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["蜜炬殷紅畫不如，且將歸去照吾廬。","今來併得三般事，靈運詩篇逸少書。"]', '["蜜炬殷紅畫不如，且將归去照吾廬。","今来併得三般事，靈運诗篇逸少书。"]', '诗', 'shi', '', NULL, '酬隱珪舍人寄紅燭 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e75853a-bf7a-4d8d-b3e9-0537f4ed913a', '馬嵬坡', '马嵬坡', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["[玄]宗回馬楊妃死，雲雨雖亡日月新。","終是聖明天子事，景陽宮井又何人。"]', '["[玄]宗回马楊妃死，云雨雖亡日月新。","終是聖明天子事，景陽宮井又何人。"]', '诗', 'shi', '', NULL, '馬嵬坡 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e830e284-dfea-4a90-b604-bd1ae75431d9', '句', '句', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["圓明青[䭀]飯，光潤碧霞漿。","浴殿晴秋倘中謝，殘英猶可醉瓊杯。"]', '["圓明青[䭀]飯，光潤碧霞漿。","浴殿晴秋倘中謝，殘英猶可醉瓊杯。"]', '诗', 'shi', '', NULL, '句 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab33b7c-cb01-4ee4-8308-5cfd522caca4', '題九華山', '題九华山', '2cf5e5f1-22a3-4a62-b5cd-28fe72b7d874', '唐', '["憶聞九華山，尚在童稚年。","浮沈任名路，窺仰會無緣。","罷職池陽時，復遭迎送牽。","因茲契誠願，矚望枕席前。","況值春正濃，氣色無不全。","或如碧玉靜，或似青靄鮮。","或接白雲堆，或暎紅霞天。","呈姿既不一，變態何啻千。","巍峩本無動，崇峻性豈偏。","外景自隱隱，潛虛固幽玄。","我來暗凝情，務道志更堅。","色與山異性，性併山亦然。","境變山不動，性存形自遷。","自遷不阻俗，自定不失賢。","浮華與朱紫，安可迷心田。"]', '["憶闻九华山，尚在童稚年。","浮沈任名路，窺仰會無緣。","罷職池陽时，复遭迎送牽。","因茲契誠願，矚望枕席前。","況值春正濃，氣色無不全。","或如碧玉静，或似青靄鲜。","或接白云堆，或暎紅霞天。","呈姿既不一，变態何啻千。","巍峩本無动，崇峻性豈偏。","外景自隐隐，潛虛固幽玄。","我来暗凝情，務道志更堅。","色與山異性，性併山亦然。","境变山不动，性存形自遷。","自遷不阻俗，自定不失賢。","浮华與朱紫，安可迷心田。"]', '诗', 'shi', '', NULL, '題九華山 譚銖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10185486-fd2c-41df-8234-8326b619e1fe', '真娘墓', '真娘墓', '2cf5e5f1-22a3-4a62-b5cd-28fe72b7d874', '唐', '["武丘山下冢纍纍，松柏蕭條盡可悲。","何事世人偏重色，真娘墓上獨題詩。"]', '["武丘山下冢纍纍，松柏蕭條尽可悲。","何事世人偏重色，真娘墓上独題诗。"]', '诗', 'shi', '', NULL, '真娘墓 譚銖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dbf197-b9e1-4864-b9e3-f89c7ee53451', '望九華山', '望九华山', '817e9789-db67-4d14-8c9f-a6d19591a5bd', '唐', '["九華深翠落軒楹，迥眺澄江氣象明。","不遇陰霾孤岫隱，正當寒日衆峯呈。","坐觀風雪銷煩思，惜別煙嵐駐曉行。","得路歸山期早訣，夜來潛已告精誠。"]', '["九华深翠落軒楹，迥眺澄江氣象明。","不遇陰霾孤岫隐，正當寒日衆峯呈。","坐观风雪銷煩思，惜別煙嵐駐晓行。","得路归山期早訣，夜来潛已告精誠。"]', '诗', 'shi', '', NULL, '望九華山 盧嗣立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c442a7-b1e4-4871-bb55-9e18a63d8a4e', '應舉日寄兄弟', '應舉日寄兄弟', '83249688-94a2-4cc2-a30b-cb4e3be96818', '唐', '["廢刈鏡湖田，上書紫閣前。","愁人久委地，詩道未聞天。","不是燒金手，徒拋釣月船。","多慚兄弟意，不敢問林泉。"]', '["廢刈镜湖田，上书紫閣前。","愁人久委地，诗道未闻天。","不是燒金手，徒拋釣月船。","多慚兄弟意，不敢问林泉。"]', '诗', 'shi', '', NULL, '應舉日寄兄弟 朱可名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('510310a8-01b0-43a5-9622-4bc31edd5573', '河出榮光', '河出榮光', '7cb55372-edd6-4e54-862b-20b0ea76b0b0', '唐', '["引派崑山峻，朝宗海路長。","千齡逢聖主，五色瑞榮光。","隱暎浮中國，晶明助太陽。","坤維連浩漫，天漢接微茫。","丹闕清氛裏，函關紫氣旁。","位尊常守伯，道泰每呈祥。","習坎靈逾久，居卑德有常。","龍門如可涉，忠信是舟梁。"]', '["引派崑山峻，朝宗海路长。","千齡逢聖主，五色瑞榮光。","隐暎浮中国，晶明助太陽。","坤維連浩漫，天漢接微茫。","丹闕清氛裏，函关紫氣旁。","位尊常守伯，道泰每呈祥。","習坎靈逾久，居卑德有常。","龙门如可涉，忠信是舟梁。"]', '诗', 'shi', '', NULL, '河出榮光 張良器 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6662430-2909-49a2-9757-421d75ca0097', '新雪八韻', '新雪八韻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["大雪滿初晨，開門萬象新。","龍鍾雞未起，蕭索我何貧。","耀若花前境，清如物外身。","細飛斑戶牖，乾灑亂松筠。","正色凝高嶺，隨流助要津。","鼎消微是滓，車碾半和塵。","茶興留詩客，瓜情想戍人。","終篇本無字，誰別勝陽春。"]', '["大雪满初晨，开门万象新。","龙鍾雞未起，蕭索我何貧。","耀若花前境，清如物外身。","細飞斑戶牖，乾灑亂松筠。","正色凝高嶺，隨流助要津。","鼎消微是滓，车碾半和塵。","茶兴留诗客，瓜情想戍人。","終篇本無字，誰別勝陽春。"]', '诗', 'shi', '', NULL, '新雪八韻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afecc7e9-3aa7-4b8b-9d57-7c39827e28f6', '國學試風化下', '国学試风化下', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["霽闕露穹崇，含生仰聖聰。","英明高比日，聲敎下如風。","靜發宸居內，低來品物中。","南薰歌自溥，北極響皆通。","蘋末看無狀，人間覺有功。","因今委泥者，覩此忘途窮。"]', '["霽闕露穹崇，含生仰聖聰。","英明高比日，声敎下如风。","静發宸居內，低来品物中。","南薰歌自溥，北極响皆通。","蘋末看無狀，人间覺有功。","因今委泥者，覩此忘途窮。"]', '诗', 'shi', '', NULL, '國學試風化下 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77d2f6f6-15d2-4d1a-a3d3-e3a61f4cf506', '昇平詞十首 一', '昇平词十首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["瑞氣遶宮樓，皇居信上遊。","遠岡連聖祚，平地載神州。","會合皆重譯，潺湲近八流。","中興豈假問，據此自千秋。"]', '["瑞氣遶宮楼，皇居信上游。","远岡連聖祚，平地載神州。","會合皆重譯，潺湲近八流。","中兴豈假问，據此自千秋。"]', '诗', 'shi', '', NULL, '昇平詞十首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04088b46-d767-43b1-b8f0-2d14b5827c32', '昇平詞十首 二', '昇平词十首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["寥泬敞延英，朝班立位橫。","宣傳無草動，拜舞有衣聲。","鴛瓦霜消濕，蟲絲日照明。","辛勤自不到，遙見似前程。"]', '["寥泬敞延英，朝班立位橫。","宣傳無草动，拜舞有衣声。","鴛瓦霜消濕，蟲絲日照明。","辛勤自不到，遙见似前程。"]', '诗', 'shi', '', NULL, '昇平詞十首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('345f6e72-a85e-476f-8e7b-610983591bce', '昇平詞十首 三', '昇平词十首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["處處是歡心，時康歲已深。","不同三尺劒，應似五弦琴。","壽笑山猶盡，明嫌日有陰。","何當憐一物，亦遣斷愁吟。"]', '["处处是歡心，时康歲已深。","不同三尺劒，應似五弦琴。","壽笑山猶尽，明嫌日有陰。","何當怜一物，亦遣斷愁吟。"]', '诗', 'shi', '', NULL, '昇平詞十首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2764933-6410-42f9-936b-cb90fd947c55', '昇平詞十首 四', '昇平词十首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["曙質絕埃氛，彤庭列禁軍。","聖顏初對日，龍尾競緣雲。","佩響交成韻，簾陰暖帶紋。","逍遙豈有事，於此詠南薰。"]', '["曙質絕埃氛，彤庭列禁軍。","聖顏初对日，龙尾競緣云。","佩响交成韻，簾陰暖带紋。","逍遙豈有事，於此詠南薰。"]', '诗', 'shi', '', NULL, '昇平詞十首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3234c655-7b1b-4be7-bdc3-7f6c93106dae', '昇平詞十首 五', '昇平词十首 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一物至周天，洪纖盡晏然。","車書無異俗，甲子並豐年。","奇技皆歸朴，征夫亦服田。","君王故不有，台鼎合韋弦。"]', '["一物至周天，洪纖尽晏然。","车书無異俗，甲子並豐年。","奇技皆归朴，征夫亦服田。","君王故不有，台鼎合韋弦。"]', '诗', 'shi', '', NULL, '昇平詞十首 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7df6d8-f7cc-4476-b568-7fec18cc4cb7', '昇平詞十首 六', '昇平词十首 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["日日聽歌謠，區中盡祝堯。","蟲蝗初不害，夷狄近全銷。","史筆惟書瑞，天臺絕見妖。","因令匹夫志，轉欲事清朝。"]', '["日日听歌謠，區中尽祝堯。","蟲蝗初不害，夷狄近全銷。","史笔惟书瑞，天台絕见妖。","因令匹夫志，轉欲事清朝。"]', '诗', 'shi', '', NULL, '昇平詞十首 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72a9af5-ed08-4627-bf20-9ee339648f41', '昇平詞十首 七', '昇平词十首 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["品物盡昭蘇，神功復帝謨。","他時應有壽，當代且無虞。","賜曆通遐俗，移關入半胡。","鷦鷯一何幸，於此寄微軀。"]', '["品物尽昭蘇，神功复帝謨。","他时應有壽，當代且無虞。","賜曆通遐俗，移关入半胡。","鷦鷯一何幸，於此寄微軀。"]', '诗', 'shi', '', NULL, '昇平詞十首 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4063565-5be6-46b8-ab58-3d6802921d6e', '昇平詞十首 八', '昇平词十首 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["無戰復無私，堯時即此時。","焚香臨極早，待月卷簾遲。","端拱乾坤內，何言黈纊垂。","君看聖明驗，只此是神龜。"]', '["無戰复無私，堯时即此时。","焚香臨極早，待月卷簾遲。","端拱乾坤內，何言黈纊垂。","君看聖明驗，只此是神龟。"]', '诗', 'shi', '', NULL, '昇平詞十首 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc4435cb-a58b-43bc-bfa5-9cee777affe2', '昇平詞十首 九', '昇平词十首 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["旭日上清穹，明堂坐聖聰。","衣裳承瑞氣，冠冕蓋重瞳。","花木經宵露，旌旗入仗風。","何期於此地，見說是神工。"]', '["旭日上清穹，明堂坐聖聰。","衣裳承瑞氣，冠冕蓋重瞳。","花木經宵露，旌旗入仗风。","何期於此地，见说是神工。"]', '诗', 'shi', '', NULL, '昇平詞十首 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7c0225-506f-4c87-bda2-019cce9e19dd', '昇平詞十首 十', '昇平词十首 十', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["五帝三皇主，蕭曹魏邴臣。","文章惟返朴，戈甲盡生塵。","諫紙應無用，朝綱自有倫。","昇平不可記，所見是閑人。"]', '["五帝三皇主，蕭曹魏邴臣。","文章惟返朴，戈甲尽生塵。","諫紙應無用，朝綱自有倫。","昇平不可記，所见是闲人。"]', '诗', 'shi', '', NULL, '昇平詞十首 十 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b9eaa8-608b-47f3-ad36-c79c48f39ecb', '送馮溫往河外', '送馮溫往河外', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["琴劒事行裝，河關出北方。","秦音盡河內，魏畫自黎陽。","野日村苗熟，秋霜館葉黃。","風沙問船處，應得立清漳。"]', '["琴劒事行裝，河关出北方。","秦音尽河內，魏畫自黎陽。","野日村苗熟，秋霜館葉黄。","风沙问船处，應得立清漳。"]', '诗', 'shi', '', NULL, '送馮溫往河外 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b708fe60-6657-42e2-a55e-bbd2c42499a4', '送從兄之太原副使', '送從兄之太原副使', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["少載琴書去，須知暫佐軍。","初程見西嶽，盡室渡橫汾。","元日何州在，枯風宿館聞。","都門送行處，青紫騎紛紛。"]', '["少載琴书去，須知暫佐軍。","初程见西嶽，尽室渡橫汾。","元日何州在，枯风宿館闻。","都门送行处，青紫騎紛紛。"]', '诗', 'shi', '', NULL, '送從兄之太原副使 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8306e008-e7cb-4030-bdab-dc2a2472e0a2', '送馬戴書記之太原', '送马戴书記之太原', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一曲大河聲，全家幾日行。","從容長約夜，差互忽離城。","鎮北胡沙淺，途中霍嶽橫。","相逢莫已訊，詩雅負雄名。"]', '["一曲大河声，全家幾日行。","從容长約夜，差互忽離城。","鎮北胡沙淺，途中霍嶽橫。","相逢莫已訊，诗雅負雄名。"]', '诗', 'shi', '', NULL, '送馬戴書記之太原 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f31e8ab-68d8-4cac-8694-474587f59e78', '送友人出塞', '送友人出塞', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["榆關到不可，何況出榆關。","春草臨岐斷，邊樓帶日閑。","人歸穹帳外，鳥亂廢營間。","此地堪愁想，霜前作意還。"]', '["榆关到不可，何況出榆关。","春草臨岐斷，邊楼带日闲。","人归穹帳外，鸟亂廢營间。","此地堪愁想，霜前作意還。"]', '诗', 'shi', '', NULL, '送友人出塞 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77fcf781-bdb6-4825-a261-76f2a0623ff9', '送李溟出塞', '送李溟出塞', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["邊城官尚惡，況乃是羈遊。","別路應相憶，離亭更少留。","黃沙人外闊，飛雪馬前稠。","甚險穹廬宿，無爲過代州。"]', '["邊城官尚惡，況乃是羈游。","別路應相憶，離亭更少留。","黄沙人外闊，飞雪马前稠。","甚險穹廬宿，無爲過代州。"]', '诗', 'shi', '', NULL, '送李溟出塞 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028eb480-7fbe-4cde-95b5-61c1fa5683e3', '寄終南隱者', '寄終南隐者', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["海日東南出，應開嶺上扉。","掃壇花入篲，科竹露霑衣。","飯後嫌身重，茶中見鳥歸。","相思愛民者，難說與親違。"]', '["海日东南出，應开嶺上扉。","掃壇花入篲，科竹露霑衣。","飯後嫌身重，茶中见鸟归。","相思愛民者，难说與親違。"]', '诗', 'shi', '', NULL, '寄終南隱者 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ab0ba9-c087-4fa3-b75a-9754529fe829', '贈隱者', '贈隐者', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["自得高閑性，平生向北棲。","月潭雲影斷，山葉雨聲齊。","庭樹人書匝，欄花鳥坐低。","相留永不忘，經宿話丹梯。"]', '["自得高闲性，平生向北棲。","月潭云影斷，山葉雨声齊。","庭樹人书匝，欄花鸟坐低。","相留永不忘，經宿話丹梯。"]', '诗', 'shi', '', NULL, '贈隱者 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5a15ce-95bc-44b9-a3ba-6f44f73867ad', '惜春', '惜春', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["花開亦花落，時節暗中遷。","無計延春日，可能留少年。","小叢初散蝶，高柳即聞蟬。","繁豔歸何處，滿山啼杜鵑。"]', '["花开亦花落，时節暗中遷。","無計延春日，可能留少年。","小叢初散蝶，高柳即闻蟬。","繁豔归何处，满山啼杜鵑。"]', '诗', 'shi', '', NULL, '惜春 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d22aca8-9cd4-4177-a871-dc56d930c714', '送人自蘇州之長沙縣官', '送人自蘇州之长沙縣官', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["驅馬復乘流，何時發虎丘？","全家上南嶽，一尉事諸侯。","茶煮朝宗水，船停調角州。","炎方好將息，卑濕舊堪憂。"]', '["驱马复乘流，何时發虎丘？","全家上南嶽，一尉事諸侯。","茶煮朝宗水，船停調角州。","炎方好將息，卑濕旧堪憂。"]', '诗', 'shi', '', NULL, '送人自蘇州之長沙縣官 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8b60f4-8ffd-4a3b-b96a-4ea00f11f422', '早春歸山中舊居', '早春归山中旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["茫茫驅匹馬，歸處是荒榛。","猨跡破庭雪，鼠蹤生甑塵。","開門衝網斷，掃葉放苔勻。","爲惜詩情錯，應難致此身。"]', '["茫茫驱匹马，归处是荒榛。","猨跡破庭雪，鼠蹤生甑塵。","开门衝網斷，掃葉放苔勻。","爲惜诗情錯，應难致此身。"]', '诗', 'shi', '', NULL, '早春歸山中舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934120ad-883a-4701-9df6-097bfb08c20a', '麟中寓居寄蒲中友人', '麟中寓居寄蒲中友人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["蕭條秋雨地，獨院阻同羣。","一夜驚爲客，多年不見君。","邊心生落日，鄉思羨歸雲。","更在相思處，子規燈下聞。"]', '["蕭條秋雨地，独院阻同羣。","一夜驚爲客，多年不见君。","邊心生落日，乡思羨归云。","更在相思处，子規灯下闻。"]', '诗', 'shi', '', NULL, '麟中寓居寄蒲中友人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02096dd9-1734-4358-81f0-98ce21febd85', '關中送別', '关中送別', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一行千里外，幾事寸心間。","才子貧堪歎，男兒別是閑。","黃河淹華岳，白日照潼關。","若值鄉人問，終軍賤不還。"]', '["一行千里外，幾事寸心间。","才子貧堪歎，男兒別是闲。","黄河淹华岳，白日照潼关。","若值乡人问，終軍賤不還。"]', '诗', 'shi', '', NULL, '關中送別 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7094d6a-d2c4-47e9-b19d-d8d2f528e40a', '中秋夜寄李溟', '中秋夜寄李溟', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["滿魄斷埃氛，牽吟並舍聞。","一年唯此夜，到晚願無雲。","待賞從初出，看行過二分。","嚴城亦已閉，悔不預期君。"]', '["满魄斷埃氛，牽吟並舍闻。","一年唯此夜，到晚願無云。","待賞從初出，看行過二分。","嚴城亦已閉，悔不預期君。"]', '诗', 'shi', '', NULL, '中秋夜寄李溟 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8303cd6a-d38e-420a-98a4-ccd407ef8d73', '贈禪師', '贈禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["夢想青山寺，前年住此中。","夜堂吹竹雨，春地落花風。","舊句師曾見，清齋我亦同。","浮生蹇莫問，辛苦未成功。"]', '["梦想青山寺，前年住此中。","夜堂吹竹雨，春地落花风。","旧句師曾见，清斋我亦同。","浮生蹇莫问，辛苦未成功。"]', '诗', 'shi', '', NULL, '贈禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a2fe3c-057f-40e7-ace2-6a2513588589', '送禪僧', '送禪僧', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["寒空孤鳥度，落日一僧歸。","近寺路聞梵，出郊風滿衣。","步搖瓶浪起，盂戛磬聲微。","還坐棲禪所，荒山月照扉。"]', '["寒空孤鸟度，落日一僧归。","近寺路闻梵，出郊风满衣。","步搖瓶浪起，盂戛磬声微。","還坐棲禪所，荒山月照扉。"]', '诗', 'shi', '', NULL, '送禪僧 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b824656-b275-4123-8323-5e79d417dea0', '贈隱者', '贈隐者', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["門前雖有徑，絕向世間行。","薙草因逢藥，移花便得鶯。","甘貧原是道，苦學不爲名。","莫怪蒼髭晚，無機任世情。"]', '["门前雖有徑，絕向世间行。","薙草因逢藥，移花便得鶯。","甘貧原是道，苦学不爲名。","莫怪蒼髭晚，無機任世情。"]', '诗', 'shi', '', NULL, '贈隱者 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac7ed6a-cbc8-464f-894d-3fe8da56063b', '冬日送僧歸吳中舊居', '冬日送僧归吳中旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["去掃冬林下，閑持未徧經。","爲山低鑿牖，容月廣開庭。","舊葉雲千里，生涯水一瓶。","還應覓新句，看雪倚禪扃。"]', '["去掃冬林下，闲持未徧經。","爲山低鑿牖，容月廣开庭。","旧葉云千里，生涯水一瓶。","還應覓新句，看雪倚禪扃。"]', '诗', 'shi', '', NULL, '冬日送僧歸吳中舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71ef698-2204-4c30-9ee2-f9dcebb80ed4', '恭禧皇太后挽歌詞三首 一', '恭禧皇太后挽歌词三首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["八月曾殊選，三星固異儀。","祔陵經灞滻，歸賵雜華夷。","旌去題新諡，宮存鏁素幃。","重泉應不恨，生見太平時。"]', '["八月曾殊選，三星固異儀。","祔陵經灞滻，归賵杂华夷。","旌去題新諡，宮存鏁素幃。","重泉應不恨，生见太平时。"]', '诗', 'shi', '', NULL, '恭禧皇太后挽歌詞三首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c6e213-cc43-4c89-a21e-95f3a90fcb7e', '恭禧皇太后挽歌詞三首 二', '恭禧皇太后挽歌词三首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["月落娥兼隱，宮空后豈還。","銜哀窮地界，親蒞泣天顏。","舊住留丹藥，新陵在碧山。","國人傷莫及，應只詠關關。"]', '["月落娥兼隐，宮空后豈還。","銜哀窮地界，親蒞泣天顏。","旧住留丹藥，新陵在碧山。","国人傷莫及，應只詠关关。"]', '诗', 'shi', '', NULL, '恭禧皇太后挽歌詞三首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48172562-5aef-49c6-ae42-12292b361e84', '恭禧皇太后挽歌詞三首 三', '恭禧皇太后挽歌词三首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["配聖三朝隔，靈儀萬姓哀。","多年好黃老，舊日薦賢才。","道著標彤管，宮閑閉綠苔。","平生六衣在，曾著祀高禖。"]', '["配聖三朝隔，靈儀万姓哀。","多年好黄老，旧日薦賢才。","道著標彤管，宮闲閉綠苔。","平生六衣在，曾著祀高禖。"]', '诗', 'shi', '', NULL, '恭禧皇太后挽歌詞三首 三 薛能 shi');
